[[nodiscard]] bool valid_sha256_hex(const QString& value) {
  static const QRegularExpression expression(
      QStringLiteral("^[0-9a-f]{64}$"));
  return expression.match(value.trimmed().toLower()).hasMatch();
}

[[nodiscard]] bool valid_timezone_aware_iso8601(const QString& value) {
  static const QRegularExpression timezone_suffix(
      QStringLiteral("(?:Z|[+-][0-9]{2}:[0-9]{2})$"));
  const auto normalized = value.trimmed();
  if (!timezone_suffix.match(normalized).hasMatch()) {
    return false;
  }
  auto parsed = QDateTime::fromString(normalized, Qt::ISODateWithMs);
  if (!parsed.isValid()) {
    parsed = QDateTime::fromString(normalized, Qt::ISODate);
  }
  return parsed.isValid();
}

[[nodiscard]] bool calibration_payload_contains_private_data(
    const QVariant& value) {
  if (value.typeId() == QMetaType::QVariantMap) {
    const auto map = value.toMap();
    for (auto iterator = map.constBegin(); iterator != map.constEnd();
         ++iterator) {
      const auto is_false_path_attestation =
          iterator.key() == QStringLiteral("storesSourcePaths") &&
          iterator.value().typeId() == QMetaType::Bool &&
          !iterator.value().toBool();
      if ((!is_false_path_attestation &&
           iterator.key().contains(QStringLiteral("path"),
                                   Qt::CaseInsensitive)) ||
          calibration_payload_contains_private_data(iterator.value())) {
        return true;
      }
    }
    return false;
  }
  if (value.typeId() == QMetaType::QVariantList ||
      value.typeId() == QMetaType::QStringList) {
    for (const auto& item : value.toList()) {
      if (calibration_payload_contains_private_data(item)) {
        return true;
      }
    }
    return false;
  }
  if (value.typeId() != QMetaType::QString) {
    return false;
  }
  const auto text = value.toString().trimmed().toLower();
  return text.startsWith(QStringLiteral("data:image")) ||
         text.startsWith(QStringLiteral("file://")) ||
         text.contains(QStringLiteral(";base64,"));
}

[[nodiscard]] QVariantMap compact_photographer_calibration_profile(
    const QVariantMap& source,
    QStringList* errors) {
  const auto append_error = [errors](const QString& error) {
    if (errors != nullptr) {
      errors->append(error);
    }
  };
  if (source.value(QStringLiteral("contract")).toString() !=
      QStringLiteral("agent-photographer-calibration-profile-v1")) {
    append_error(QStringLiteral(
        "Calibration must use agent-photographer-calibration-profile-v1."));
    return {};
  }
  if (source.value(QStringLiteral("version")).toInt() != 1 ||
      source.value(QStringLiteral("status")).toString() !=
          QStringLiteral("observed") ||
      !source.value(QStringLiteral("blindReview")).toBool() ||
      !source.value(QStringLiteral("localOnly")).toBool() ||
      source.value(QStringLiteral("professionalReadinessClaimed")).toBool() ||
      source.value(QStringLiteral("automaticThresholdMutationAllowed")).toBool() ||
      !source
           .value(QStringLiteral("freshCorpusRunRequiredAfterThresholdChange"))
           .toBool()) {
    append_error(QStringLiteral(
        "Calibration safety attestations are incomplete or incompatible."));
    return {};
  }
  if (calibration_payload_contains_private_data(source)) {
    append_error(QStringLiteral(
        "Calibration profiles cannot contain source paths or image payloads."));
    return {};
  }
  const auto claimed_digest =
      source.value(QStringLiteral("profileDigestSha256"))
          .toString()
          .trimmed()
          .toLower();
  auto digest_payload = source;
  digest_payload.remove(QStringLiteral("profileDigestSha256"));
  if (!valid_sha256_hex(claimed_digest) ||
      stable_variant_hash(digest_payload) != claimed_digest) {
    append_error(QStringLiteral(
        "Calibration profile digest does not match its contents."));
    return {};
  }
  const QStringList provenance_digest_keys{
      QStringLiteral("packetDigestSha256"),
      QStringLiteral("sourceManifestSha256"),
      QStringLiteral("reviewedManifestSha256"),
      QStringLiteral("machineReportSha256"),
  };
  for (const auto& key : provenance_digest_keys) {
    if (!valid_sha256_hex(source.value(key).toString())) {
      append_error(QStringLiteral(
          "Calibration provenance digests are incomplete or invalid."));
      return {};
    }
  }
  const auto reviewer =
      source.value(QStringLiteral("reviewer")).toString().simplified();
  const auto reviewed_at =
      source.value(QStringLiteral("reviewedAt")).toString().trimmed();
  const auto case_count = source.value(QStringLiteral("caseCount")).toInt();
  const auto cases = source.value(QStringLiteral("cases")).toList();
  if (reviewer.isEmpty() || !valid_timezone_aware_iso8601(reviewed_at) ||
      case_count < 1 ||
      case_count > 10000 || cases.size() != case_count) {
    append_error(QStringLiteral(
        "Calibration reviewer, timestamp, or case set is incomplete."));
    return {};
  }

  const auto taste_summary =
      source.value(QStringLiteral("tasteSummary")).toMap();
  const auto dimension_means =
      taste_summary.value(QStringLiteral("dimensionMeans")).toMap();
  const auto required_dimensions = photographer_calibration_dimension_keys();
  const QSet<QString> present_dimensions(
      dimension_means.keyBegin(), dimension_means.keyEnd());
  const QSet<QString> expected_dimensions(
      required_dimensions.cbegin(), required_dimensions.cend());
  if (present_dimensions != expected_dimensions) {
    append_error(QStringLiteral(
        "Calibration must include every photographic rating dimension."));
    return {};
  }
  for (const auto& key : required_dimensions) {
    const auto mean = dimension_means.value(key).toDouble();
    if (!std::isfinite(mean) || mean < 1.0 || mean > 5.0) {
      append_error(QStringLiteral(
          "Calibration dimension means must stay between 1 and 5."));
      return {};
    }
  }
  const auto issue_counts =
      taste_summary.value(QStringLiteral("issueTagCounts")).toMap();
  const auto issue_labels = photographer_calibration_issue_labels();
  for (auto iterator = issue_counts.constBegin();
       iterator != issue_counts.constEnd(); ++iterator) {
    if (!issue_labels.contains(iterator.key()) || iterator.value().toInt() < 1 ||
        iterator.value().toInt() > case_count) {
      append_error(QStringLiteral(
          "Calibration issue counts contain an unknown or invalid tag."));
      return {};
    }
  }

  const auto outcomes = source.value(QStringLiteral("outcomes")).toMap();
  const QStringList outcome_keys{
      QStringLiteral("agreementPass"),
      QStringLiteral("falseConfidence"),
      QStringLiteral("overConservative"),
      QStringLiteral("agreementFail"),
  };
  auto outcome_total = 0;
  for (const auto& key : outcome_keys) {
    const auto count = outcomes.value(key).toInt();
    if (count < 0 || count > case_count) {
      append_error(QStringLiteral("Calibration outcomes are invalid."));
      return {};
    }
    outcome_total += count;
  }
  if (outcome_total != case_count) {
    append_error(QStringLiteral(
        "Calibration outcomes must account for every reviewed case."));
    return {};
  }

  const QSet<QString> allowed_threshold_keys{
      QStringLiteral("brightness"),
      QStringLiteral("contrast"),
      QStringLiteral("warmth"),
      QStringLiteral("saturation"),
      QStringLiteral("monochromeSaturationLimit"),
      QStringLiteral("preserveLuma"),
      QStringLiteral("preserveContrast"),
      QStringLiteral("preserveSaturation"),
      QStringLiteral("retouchQuality"),
  };
  const QSet<QString> allowed_signal_statuses{
      QStringLiteral("human-rejected-machine-pass"),
      QStringLiteral("human-accepted-machine-fail"),
      QStringLiteral("conflicting-human-signal"),
      QStringLiteral("no-change-signal"),
  };
  const QSet<QString> allowed_signal_actions{
      QStringLiteral("tighten-and-rerun"),
      QStringLiteral("relax-and-rerun"),
      QStringLiteral("collect-more-evidence"),
      QStringLiteral("hold-until-disagreement"),
  };
  QVariantMap compact_signals;
  const auto threshold_signals =
      source.value(QStringLiteral("thresholdSignals")).toMap();
  for (auto iterator = threshold_signals.constBegin();
       iterator != threshold_signals.constEnd(); ++iterator) {
    const auto signal = iterator.value().toMap();
    const auto false_confidence =
        signal.value(QStringLiteral("falseConfidenceCount")).toInt();
    const auto over_conservative =
        signal.value(QStringLiteral("overConservativeCount")).toInt();
    if (!allowed_threshold_keys.contains(iterator.key()) ||
        !allowed_signal_statuses.contains(
            signal.value(QStringLiteral("status")).toString()) ||
        !allowed_signal_actions.contains(
            signal.value(QStringLiteral("suggestedAction")).toString()) ||
        signal.value(QStringLiteral("automaticThresholdChangeAllowed")).toBool() ||
        false_confidence < 0 || over_conservative < 0 ||
        false_confidence > case_count || over_conservative > case_count) {
      append_error(QStringLiteral(
          "Calibration threshold signals are invalid or unsafe."));
      return {};
    }
    compact_signals.insert(
        iterator.key(),
        QVariantMap{
            {QStringLiteral("status"),
             signal.value(QStringLiteral("status"))},
            {QStringLiteral("suggestedAction"),
             signal.value(QStringLiteral("suggestedAction"))},
            {QStringLiteral("falseConfidenceCount"), false_confidence},
            {QStringLiteral("overConservativeCount"), over_conservative},
            {QStringLiteral("automaticThresholdChangeAllowed"), false},
        });
  }

  QSet<QString> case_ids;
  QVariantList compact_cases;
  QMap<QString, int> observed_outcomes;
  QMap<QString, int> observed_issue_counts;
  for (const auto& case_value : cases) {
    const auto item = case_value.toMap();
    const auto case_id =
        item.value(QStringLiteral("caseId")).toString().trimmed();
    const auto human_status =
        item.value(QStringLiteral("humanStatus")).toString();
    const auto human_rating =
        item.value(QStringLiteral("humanRating")).toInt();
    const auto outcome = item.value(QStringLiteral("outcome")).toString();
    const auto machine_pass_value = item.value(QStringLiteral("machinePass"));
    const auto machine_pass = machine_pass_value.toBool();
    const auto case_dimensions =
        item.value(QStringLiteral("dimensions")).toMap();
    const QSet<QString> case_dimension_keys(
        case_dimensions.keyBegin(), case_dimensions.keyEnd());
    auto case_dimensions_valid = case_dimension_keys == expected_dimensions;
    for (const auto& key : required_dimensions) {
      const auto rating = case_dimensions.value(key).toInt();
      case_dimensions_valid =
          case_dimensions_valid && rating >= 1 && rating <= 5;
    }
    QStringList case_issue_tags;
    QSet<QString> unique_case_issue_tags;
    auto case_issue_tags_valid = true;
    for (const auto& issue_value :
         item.value(QStringLiteral("issueTags")).toList()) {
      const auto issue = issue_value.toString();
      if (!issue_labels.contains(issue) ||
          unique_case_issue_tags.contains(issue)) {
        case_issue_tags_valid = false;
        break;
      }
      unique_case_issue_tags.insert(issue);
      case_issue_tags.append(issue);
    }
    const auto expected_outcome =
        machine_pass
            ? (human_status == QStringLiteral("pass")
                   ? QStringLiteral("agreement-pass")
                   : QStringLiteral("false-confidence"))
            : (human_status == QStringLiteral("pass")
                   ? QStringLiteral("over-conservative")
                   : QStringLiteral("agreement-fail"));
    if (case_id.isEmpty() || case_ids.contains(case_id) ||
        item.value(QStringLiteral("caseKind")).toString().trimmed().isEmpty() ||
        machine_pass_value.typeId() != QMetaType::Bool ||
        (human_status != QStringLiteral("pass") &&
         human_status != QStringLiteral("fail")) ||
        human_rating < 1 || human_rating > 5 ||
        !case_dimensions_valid || !case_issue_tags_valid ||
        (human_status == QStringLiteral("fail") &&
         case_issue_tags.isEmpty()) ||
        outcome != expected_outcome ||
        !QSet<QString>{QStringLiteral("agreement-pass"),
                       QStringLiteral("false-confidence"),
                       QStringLiteral("over-conservative"),
                       QStringLiteral("agreement-fail")}
             .contains(outcome)) {
      append_error(QStringLiteral(
          "Calibration case outcomes are incomplete or duplicated."));
      return {};
    }
    case_ids.insert(case_id);
    observed_outcomes[outcome] += 1;
    for (const auto& issue : case_issue_tags) {
      observed_issue_counts[issue] += 1;
    }
    compact_cases.append(QVariantMap{
        {QStringLiteral("caseId"), case_id},
        {QStringLiteral("caseKind"),
         item.value(QStringLiteral("caseKind"))},
        {QStringLiteral("machinePass"),
         item.value(QStringLiteral("machinePass"))},
        {QStringLiteral("humanStatus"), human_status},
        {QStringLiteral("humanRating"), human_rating},
        {QStringLiteral("dimensions"), case_dimensions},
        {QStringLiteral("issueTags"), case_issue_tags},
        {QStringLiteral("outcome"), outcome},
    });
  }
  for (const auto& key : outcome_keys) {
    const auto source_outcome_key =
        key == QStringLiteral("agreementPass")
            ? QStringLiteral("agreement-pass")
            : key == QStringLiteral("falseConfidence")
                  ? QStringLiteral("false-confidence")
                  : key == QStringLiteral("overConservative")
                        ? QStringLiteral("over-conservative")
                        : QStringLiteral("agreement-fail");
    if (outcomes.value(key).toInt() !=
        observed_outcomes.value(source_outcome_key)) {
      append_error(QStringLiteral(
          "Calibration outcome totals do not match its reviewed cases."));
      return {};
    }
  }
  if (issue_counts.size() != observed_issue_counts.size()) {
    append_error(QStringLiteral(
        "Calibration issue totals do not match its reviewed cases."));
    return {};
  }
  for (auto iterator = observed_issue_counts.constBegin();
       iterator != observed_issue_counts.constEnd(); ++iterator) {
    if (issue_counts.value(iterator.key()).toInt() != iterator.value()) {
      append_error(QStringLiteral(
          "Calibration issue totals do not match its reviewed cases."));
      return {};
    }
  }

  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-photographer-calibration-v1")},
      {QStringLiteral("sourceContract"),
       source.value(QStringLiteral("contract"))},
      {QStringLiteral("profileDigestSha256"), claimed_digest},
      {QStringLiteral("packetDigestSha256"),
       source.value(QStringLiteral("packetDigestSha256"))},
      {QStringLiteral("sourceManifestSha256"),
       source.value(QStringLiteral("sourceManifestSha256"))},
      {QStringLiteral("reviewedManifestSha256"),
       source.value(QStringLiteral("reviewedManifestSha256"))},
      {QStringLiteral("machineReportSha256"),
       source.value(QStringLiteral("machineReportSha256"))},
      {QStringLiteral("reviewer"), reviewer.left(120)},
      {QStringLiteral("reviewedAt"), reviewed_at},
      {QStringLiteral("importedAtUtc"),
       QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)},
      {QStringLiteral("caseCount"), case_count},
      {QStringLiteral("blindReview"), true},
      {QStringLiteral("localOnly"), true},
      {QStringLiteral("tasteSummary"), taste_summary},
      {QStringLiteral("outcomes"), outcomes},
      {QStringLiteral("thresholdSignals"), compact_signals},
      {QStringLiteral("cases"), compact_cases},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("freshCorpusRunRequiredAfterThresholdChange"), true},
      {QStringLiteral("professionalReadinessClaimed"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
}

[[nodiscard]] QVariantMap portable_photographer_calibration_source(
    const QVariantMap& portable_profile,
    QStringList* errors) {
  const auto append_error = [errors](const QString& error) {
    if (errors != nullptr) {
      errors->append(error);
    }
  };
  if (portable_profile.value(QStringLiteral("contract")).toString() !=
          QStringLiteral("agent-project-photographer-calibration-v1") ||
      portable_profile.value(QStringLiteral("sourceContract")).toString() !=
          QStringLiteral("agent-photographer-calibration-profile-v1")) {
    append_error(QStringLiteral(
        "Taste Passport calibration profile is unsupported."));
    return {};
  }
  if (calibration_payload_contains_private_data(portable_profile) ||
      portable_profile.value(QStringLiteral("storesImageBytes")).toBool() ||
      portable_profile.value(QStringLiteral("storesSourcePaths")).toBool() ||
      portable_profile
          .value(QStringLiteral("automaticThresholdMutationAllowed"))
          .toBool() ||
      portable_profile
          .value(QStringLiteral("professionalReadinessClaimed"))
          .toBool() ||
      !portable_profile
           .value(QStringLiteral("freshCorpusRunRequiredAfterThresholdChange"))
           .toBool()) {
    append_error(QStringLiteral(
        "Taste Passport calibration safety boundaries are invalid."));
    return {};
  }
  const auto source_profile_digest =
      portable_profile.value(QStringLiteral("profileDigestSha256"))
          .toString()
          .trimmed()
          .toLower();
  if (!valid_sha256_hex(source_profile_digest)) {
    append_error(QStringLiteral(
        "Taste Passport source-profile provenance is invalid."));
    return {};
  }

  auto source = portable_profile;
  source.remove(QStringLiteral("contract"));
  source.remove(QStringLiteral("sourceContract"));
  source.remove(QStringLiteral("profileDigestSha256"));
  source.remove(QStringLiteral("importedAtUtc"));
  source.remove(QStringLiteral("importedFromTastePassport"));
  source.remove(QStringLiteral("tastePassportDigestSha256"));
  source.remove(QStringLiteral("passportSourceProfileDigestSha256"));
  source.remove(QStringLiteral("tastePassportImportedAtUtc"));
  source.insert(
      QStringLiteral("contract"),
      QStringLiteral("agent-photographer-calibration-profile-v1"));
  source.insert(QStringLiteral("version"), 1);
  source.insert(QStringLiteral("status"), QStringLiteral("observed"));
  source.insert(QStringLiteral("blindReview"), true);
  source.insert(QStringLiteral("localOnly"), true);
  source.insert(QStringLiteral("automaticThresholdMutationAllowed"), false);
  source.insert(
      QStringLiteral("freshCorpusRunRequiredAfterThresholdChange"), true);
  source.insert(QStringLiteral("professionalReadinessClaimed"), false);
  source.insert(
      QStringLiteral("profileDigestSha256"), stable_variant_hash(source));
  return source;
}

[[nodiscard]] QVariantMap verified_photographer_taste_passport_profile(
    const QVariantMap& passport,
    QVariantMap* verified_passport,
    QStringList* errors) {
  const auto append_error = [errors](const QString& error) {
    if (errors != nullptr) {
      errors->append(error);
    }
  };
  if (passport.value(QStringLiteral("contract")).toString() !=
          QStringLiteral("agent-photographer-taste-passport-v1") ||
      passport.value(QStringLiteral("version")).toInt() != 1 ||
      !passport.value(QStringLiteral("localOnly")).toBool() ||
      !passport.value(QStringLiteral("explicitImportRequired")).toBool() ||
      !passport.value(QStringLiteral("targetProjectOnly")).toBool() ||
      passport.value(QStringLiteral("containsProjectName")).toBool() ||
      passport.value(QStringLiteral("storesImageBytes")).toBool() ||
      passport.value(QStringLiteral("storesSourcePaths")).toBool() ||
      passport.value(QStringLiteral("automaticModelTrainingAllowed")).toBool() ||
      passport
          .value(QStringLiteral("automaticThresholdMutationAllowed"))
          .toBool() ||
      passport.value(QStringLiteral("professionalReadinessClaimed")).toBool() ||
      calibration_payload_contains_private_data(passport)) {
    append_error(
        QStringLiteral("Taste Passport safety attestations are invalid."));
    return {};
  }
  const auto passport_digest =
      passport.value(QStringLiteral("passportDigestSha256"))
          .toString()
          .trimmed()
          .toLower();
  auto passport_digest_payload = passport;
  passport_digest_payload.remove(QStringLiteral("passportDigestSha256"));
  if (!valid_sha256_hex(passport_digest) ||
      stable_variant_hash(passport_digest_payload) != passport_digest) {
    append_error(
        QStringLiteral("Taste Passport digest does not match its contents."));
    return {};
  }
  const auto portable_profile =
      passport.value(QStringLiteral("calibrationProfile")).toMap();
  const auto portable_profile_digest =
      passport.value(QStringLiteral("portableProfileDigestSha256"))
          .toString()
          .trimmed()
          .toLower();
  if (!valid_sha256_hex(portable_profile_digest) ||
      stable_variant_hash(portable_profile) != portable_profile_digest) {
    append_error(
        QStringLiteral("Taste Passport calibration digest is invalid."));
    return {};
  }
  if (passport.value(QStringLiteral("sourceProfileDigestSha256")).toString() !=
      portable_profile.value(QStringLiteral("profileDigestSha256")).toString()) {
    append_error(QStringLiteral(
        "Taste Passport source-profile provenance is inconsistent."));
    return {};
  }
  const auto portable_source = portable_photographer_calibration_source(
      portable_profile, errors);
  auto compact = compact_photographer_calibration_profile(
      portable_source, errors);
  if (compact.isEmpty() || (errors != nullptr && !errors->isEmpty())) {
    return {};
  }
  compact.insert(QStringLiteral("importedFromTastePassport"), true);
  compact.insert(QStringLiteral("tastePassportDigestSha256"), passport_digest);
  compact.insert(
      QStringLiteral("passportSourceProfileDigestSha256"),
      passport.value(QStringLiteral("sourceProfileDigestSha256")));
  if (verified_passport != nullptr) {
    *verified_passport = passport;
  }
  return compact;
}

[[nodiscard]] QVariantMap photographer_calibration_card(
    const QVariantMap& stored_profile) {
  if (stored_profile.value(QStringLiteral("contract")).toString() !=
      QStringLiteral("agent-project-photographer-calibration-v1")) {
    return QVariantMap{
        {QStringLiteral("contract"),
         QStringLiteral("agent-photographer-calibration-card-v1")},
        {QStringLiteral("available"), false},
        {QStringLiteral("projectLocal"), true},
        {QStringLiteral("numericThresholdOverridesAllowed"), false},
        {QStringLiteral("storesImageBytes"), false},
        {QStringLiteral("storesSourcePaths"), false},
    };
  }
  const auto outcomes =
      stored_profile.value(QStringLiteral("outcomes")).toMap();
  const auto taste_summary =
      stored_profile.value(QStringLiteral("tasteSummary")).toMap();
  const auto dimension_means =
      taste_summary.value(QStringLiteral("dimensionMeans")).toMap();
  const auto dimension_labels = photographer_calibration_dimension_labels();
  const auto issue_counts =
      taste_summary.value(QStringLiteral("issueTagCounts")).toMap();
  const auto issue_labels = photographer_calibration_issue_labels();
  const auto false_confidence =
      outcomes.value(QStringLiteral("falseConfidence")).toInt();
  const auto over_conservative =
      outcomes.value(QStringLiteral("overConservative")).toInt();
  const auto case_count =
      stored_profile.value(QStringLiteral("caseCount")).toInt();
  auto weakest_dimension = QString();
  auto weakest_mean = 6.0;
  for (auto iterator = dimension_means.constBegin();
       iterator != dimension_means.constEnd(); ++iterator) {
    const auto mean = iterator.value().toDouble();
    if (mean < weakest_mean) {
      weakest_mean = mean;
      weakest_dimension = iterator.key();
    }
  }
  QStringList guidance;
  if (!weakest_dimension.isEmpty() && weakest_mean < 4.5) {
    guidance.append(
        QStringLiteral("Prioritize %1; the blind-review mean was %2/5.")
            .arg(dimension_labels.value(weakest_dimension).toString())
            .arg(weakest_mean, 0, 'f', 1));
  }
  QList<QPair<int, QString>> ranked_issues;
  for (auto iterator = issue_counts.constBegin();
       iterator != issue_counts.constEnd(); ++iterator) {
    ranked_issues.append({iterator.value().toInt(), iterator.key()});
  }
  std::stable_sort(
      ranked_issues.begin(), ranked_issues.end(),
      [](const auto& left, const auto& right) {
        return left.first > right.first ||
               (left.first == right.first && left.second < right.second);
      });
  for (const auto& issue : ranked_issues.mid(0, 3)) {
    guidance.append(
        QStringLiteral("Avoid %1; the photographer flagged it in %2 case%3.")
            .arg(issue_labels.value(issue.second).toString())
            .arg(issue.first)
            .arg(issue.first == 1 ? QString() : QStringLiteral("s")));
  }
  QStringList concern_keys;
  const auto threshold_signals =
      stored_profile.value(QStringLiteral("thresholdSignals")).toMap();
  for (auto iterator = threshold_signals.constBegin();
       iterator != threshold_signals.constEnd();
       ++iterator) {
    if (iterator.value()
            .toMap()
            .value(QStringLiteral("falseConfidenceCount"))
            .toInt() > 0) {
      concern_keys.append(iterator.key());
      guidance.append(
          QStringLiteral(
              "Treat %1 as calibration-sensitive: prefer a restrained response and keep the proof in user review.")
              .arg(iterator.key()));
    }
  }
  QString summary;
  if (false_confidence > 0) {
    summary = QStringLiteral(
                  "%1 blind cases · %2 machine pass%3 rejected · %4 needs the most care")
                  .arg(case_count)
                  .arg(false_confidence)
                  .arg(false_confidence == 1 ? QString() : QStringLiteral("es"))
                  .arg(dimension_labels.value(weakest_dimension).toString());
  } else {
    summary = QStringLiteral(
                  "%1 blind cases · no machine-pass rejection%2")
                  .arg(case_count)
                  .arg(over_conservative > 0
                           ? QStringLiteral(" · %1 conservative machine stop%2")
                                 .arg(over_conservative)
                                 .arg(over_conservative == 1
                                          ? QString()
                                          : QStringLiteral("s"))
                           : QString());
  }
  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-card-v1")},
      {QStringLiteral("available"), true},
      {QStringLiteral("projectLocal"), true},
      {QStringLiteral("profileDigestSha256"),
       stored_profile.value(QStringLiteral("profileDigestSha256"))},
      {QStringLiteral("importedFromTastePassport"),
       stored_profile.value(QStringLiteral("importedFromTastePassport"))},
      {QStringLiteral("tastePassportDigestSha256"),
       stored_profile.value(QStringLiteral("tastePassportDigestSha256"))},
      {QStringLiteral("passportSourceProfileDigestSha256"),
       stored_profile.value(QStringLiteral("passportSourceProfileDigestSha256"))},
      {QStringLiteral("transferScope"), QStringLiteral("explicit-project-only")},
      {QStringLiteral("reviewer"),
       stored_profile.value(QStringLiteral("reviewer"))},
      {QStringLiteral("reviewedAt"),
       stored_profile.value(QStringLiteral("reviewedAt"))},
      {QStringLiteral("caseCount"), case_count},
      {QStringLiteral("summary"), summary},
      {QStringLiteral("dimensionMeans"), dimension_means},
      {QStringLiteral("weakestDimension"), weakest_dimension},
      {QStringLiteral("weakestDimensionMean"), weakest_mean},
      {QStringLiteral("issueTagCounts"), issue_counts},
      {QStringLiteral("outcomes"), outcomes},
      {QStringLiteral("thresholdSignals"), threshold_signals},
      {QStringLiteral("validationConcernKeys"), concern_keys},
      {QStringLiteral("planningGuidance"), guidance.mid(0, 8)},
      {QStringLiteral("requiresThresholdReview"), false_confidence > 0},
      {QStringLiteral("influencesPlanning"), true},
      {QStringLiteral("influencesProofCritique"), true},
      {QStringLiteral("numericThresholdOverridesAllowed"), false},
      {QStringLiteral("freshCorpusRunRequiredAfterThresholdChange"), true},
      {QStringLiteral("professionalReadinessClaimed"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
}

[[nodiscard]] QByteArray encode_agent_inpaint_patch(const QImage& image) {
  if (image.isNull()) {
    return {};
  }
  QByteArray encoded;
  QBuffer buffer(&encoded);
  if (!buffer.open(QIODevice::WriteOnly) || !image.save(&buffer, "PNG")) {
    return {};
  }
  return encoded;
}

[[nodiscard]] QRect selected_agent_retouch_bounds(
    const QByteArray& data,
    int width,
    int height) {
  if (!valid_segmentation_payload(data, width, height)) {
    return {};
  }
  auto left = width;
  auto top = height;
  auto right = -1;
  auto bottom = -1;
  for (int y = 0; y < height; ++y) {
    for (int x = 0; x < width; ++x) {
      if (static_cast<unsigned char>(data.at(y * width + x)) == 0U) {
        continue;
      }
      left = std::min(left, x);
      top = std::min(top, y);
      right = std::max(right, x);
      bottom = std::max(bottom, y);
    }
  }
  return right >= left && bottom >= top
             ? QRect(left, top, right - left + 1, bottom - top + 1)
             : QRect{};
}

[[nodiscard]] int agent_retouch_request_count(const QVariantMap& patch) {
  return static_cast<int>(
      patch.value(QStringLiteral("retouch"))
          .toMap()
          .value(QStringLiteral("appendRetouchStack"))
          .toList()
      .size());
}

[[nodiscard]] EditRecipeState recipe_without_materialized_agent_retouches(
    const EditRecipeState& state,
    const QVariantMap& patch) {
  QSet<QString> materialized_ids;
  const auto retouch_stack =
      patch.value(QStringLiteral("retouch"))
          .toMap()
          .value(QStringLiteral("appendRetouchStack"))
          .toList();
  for (const auto& retouch_value : retouch_stack) {
    const auto id = retouch_value.toMap().value(QStringLiteral("id")).toString();
    if (!id.isEmpty()) {
      materialized_ids.insert(id);
    }
  }

  auto baseline = state;
  QVariantList retained_masks;
  retained_masks.reserve(state.mask_stack.size());
  for (const auto& mask_value : state.mask_stack) {
    const auto id = mask_value.toMap().value(QStringLiteral("id")).toString();
    if (!materialized_ids.contains(id)) {
      retained_masks.append(mask_value);
    }
  }
  baseline.mask_stack = retained_masks;
  return baseline;
}

[[nodiscard]] bool rasterize_agent_retouch_region(
    QVariantMap* retouch,
    const QVariantMap& region) {
  if (retouch == nullptr || region.isEmpty()) {
    return false;
  }
  auto mask_data =
      retouch->value(QStringLiteral("segmentationData")).toByteArray();
  const auto width =
      retouch->value(QStringLiteral("segmentationWidth")).toInt();
  const auto height =
      retouch->value(QStringLiteral("segmentationHeight")).toInt();
  const auto expected_size =
      static_cast<qint64>(width) * static_cast<qint64>(height);
  const auto center_x = region.value(QStringLiteral("centerX"), -1.0).toDouble();
  const auto center_y = region.value(QStringLiteral("centerY"), -1.0).toDouble();
  const auto radius_x = region.value(QStringLiteral("radiusX"), 0.0).toDouble();
  const auto radius_y = region.value(QStringLiteral("radiusY"), 0.0).toDouble();
  if (width <= 0 || height <= 0 || expected_size <= 0 ||
      mask_data.size() != expected_size || center_x < 0.0 || center_x > 1.0 ||
      center_y < 0.0 || center_y > 1.0 || radius_x <= 0.0 ||
      radius_y <= 0.0 || radius_x > 0.5 || radius_y > 0.5) {
    return false;
  }
  constexpr auto kReviewedRegionCoverageExpansion = 1.5;
  constexpr auto kReviewedCoreRadiusFraction = 0.8;
  constexpr auto kTinyTargetRadiusPixels = 8.0;
  constexpr auto kTinyTargetCoreRadiusInExpandedMask = 0.88;
  const auto target_radius_pixels = std::min(
      radius_x * static_cast<double>(std::max(1, width - 1)),
      radius_y * static_cast<double>(std::max(1, height - 1)));
  const auto reviewed_core_radius_in_expanded_mask =
      target_radius_pixels <= kTinyTargetRadiusPixels
          ? kTinyTargetCoreRadiusInExpandedMask
          : kReviewedCoreRadiusFraction /
                kReviewedRegionCoverageExpansion;
  const auto effective_radius_x =
      std::min(0.5, radius_x * kReviewedRegionCoverageExpansion);
  const auto effective_radius_y =
      std::min(0.5, radius_y * kReviewedRegionCoverageExpansion);

  const auto minimum_x = std::max(
      0,
      static_cast<int>(std::floor(
          (center_x - effective_radius_x) * static_cast<double>(width - 1))));
  const auto maximum_x = std::min(
      width - 1,
      static_cast<int>(std::ceil(
          (center_x + effective_radius_x) * static_cast<double>(width - 1))));
  const auto minimum_y = std::max(
      0,
      static_cast<int>(std::floor(
          (center_y - effective_radius_y) * static_cast<double>(height - 1))));
  const auto maximum_y = std::min(
      height - 1,
      static_cast<int>(std::ceil(
          (center_y + effective_radius_y) * static_cast<double>(height - 1))));
  auto wrote_pixel = false;
  for (auto y = minimum_y; y <= maximum_y; ++y) {
    const auto normalized_y =
        height > 1 ? static_cast<double>(y) / static_cast<double>(height - 1)
                   : 0.5;
    for (auto x = minimum_x; x <= maximum_x; ++x) {
      const auto normalized_x =
          width > 1 ? static_cast<double>(x) / static_cast<double>(width - 1)
                    : 0.5;
      const auto dx = (normalized_x - center_x) / effective_radius_x;
      const auto dy = (normalized_y - center_y) / effective_radius_y;
      const auto distance = std::sqrt(dx * dx + dy * dy);
      if (distance >= 1.0) {
        continue;
      }
      // Keep the core of the user-reviewed target fully covered, then feather
      // through its outer edge and the extra safety coverage. Treating almost
      // the entire expanded region as opaque leaves visible
      // rectangular/elliptical patches on smooth backgrounds and
      // unnecessarily changes the ring around the requested target. Tiny
      // spots retain the compact feather profile so sub-pixel falloff cannot
      // erode the cleanup itself.
      const auto feather_position = std::clamp(
          (distance - reviewed_core_radius_in_expanded_mask) /
              (1.0 - reviewed_core_radius_in_expanded_mask),
          0.0,
          1.0);
      const auto smooth_feather = feather_position * feather_position *
                                  (3.0 - 2.0 * feather_position);
      const auto value = static_cast<int>(
          std::lround((1.0 - smooth_feather) * 255.0));
      if (value <= 0) {
        continue;
      }
      const auto index = y * width + x;
      mask_data[index] = static_cast<char>(std::max(
          static_cast<int>(static_cast<unsigned char>(mask_data.at(index))),
          value));
      wrote_pixel = true;
    }
  }
  if (wrote_pixel) {
    retouch->insert(QStringLiteral("segmentationData"), mask_data);
  }
  return wrote_pixel;
}

[[nodiscard]] AgentRetouchArtifactMaterialization
materialize_agent_retouch_artifacts(
    const QVariantMap& requested_patch,
    const QString& file_path,
    const EditRecipeState& state,
    const QString& source_image_version,
    bool reviewed_sensitive_plan) {
  QElapsedTimer timer;
  timer.start();
  AgentRetouchArtifactMaterialization materialization;
  materialization.patch = requested_patch;
  auto retouch_group =
      materialization.patch.value(QStringLiteral("retouch")).toMap();
  auto retouch_stack =
      retouch_group.value(QStringLiteral("appendRetouchStack")).toList();
  const auto requested_count = retouch_stack.size();
  QVariantList artifacts;
  QStringList warnings;
  QStringList errors;
  auto materialized_count = 0;
  auto fallback_count = 0;

  if (requested_count > 0 && !reviewed_sensitive_plan) {
    errors.append(QStringLiteral(
        "Agent retouch artifacts require the reviewed sensitive-plan approval receipt."));
  }

  QImage source_image;
  if (requested_count > 0 && errors.isEmpty() &&
      (!decode_source_image(file_path, &source_image, 0, state, nullptr) ||
       source_image.isNull())) {
    errors.append(QStringLiteral(
        "Unable to decode the full-resolution source for approved retouch materialization."));
  }

  for (auto index = 0; index < retouch_stack.size() && errors.isEmpty(); ++index) {
    auto retouch = retouch_stack.at(index).toMap();
    const auto retouch_id = retouch.value(QStringLiteral("id")).toString();
    const auto mode = retouch.value(QStringLiteral("retouchMode"))
                          .toString()
                          .trimmed()
                          .toLower();
    QVariantMap artifact{
        {QStringLiteral("retouchId"), retouch_id},
        {QStringLiteral("retouchMode"), mode},
        {QStringLiteral("artifactOwner"), QStringLiteral("application")},
    };
    if (retouch.value(QStringLiteral("kind")).toString() !=
            QStringLiteral("brush") ||
        (mode != QStringLiteral("remove") &&
         mode != QStringLiteral("heal"))) {
      errors.append(QStringLiteral(
          "Approved agent retouch %1 does not use a supported bounded remove/heal brush contract.")
                        .arg(retouch_id));
      artifact.insert(QStringLiteral("status"), QStringLiteral("unsupported"));
      artifacts.append(artifact);
      break;
    }

    if (!ensure_brush_raster_mask(&retouch, source_image.size())) {
      errors.append(QStringLiteral(
          "Unable to allocate the app-owned retouch mask for %1.")
                        .arg(retouch_id));
      artifact.insert(QStringLiteral("status"), QStringLiteral("mask-allocation-failed"));
      artifacts.append(artifact);
      break;
    }
    const auto agent_region =
        retouch.value(QStringLiteral("agentRegion")).toMap();
    const auto used_reviewed_region =
        rasterize_agent_retouch_region(&retouch, agent_region);
    if (!used_reviewed_region) {
      const auto points = retouch.value(QStringLiteral("brushPoints")).toList();
      for (const auto& point_value : points) {
        const auto point = point_value.toMap();
        static_cast<void>(rasterize_brush_point_into_mask(
            &retouch,
            nullptr,
            point.value(QStringLiteral("x"), 0.5).toDouble(),
            point.value(QStringLiteral("y"), 0.5).toDouble(),
            point.value(QStringLiteral("size"),
                        retouch.value(QStringLiteral("brushSize"), 0.04))
                .toDouble(),
            point.value(QStringLiteral("flow"),
                        retouch.value(QStringLiteral("brushFlow"), 1.0))
                .toDouble(),
            point.value(QStringLiteral("opacity"), 1.0).toDouble(),
            retouch.value(QStringLiteral("brushHardness"), 0.28).toDouble()));
      }
    }
    const auto mask_data =
        retouch.value(QStringLiteral("segmentationData")).toByteArray();
    const auto mask_width =
        retouch.value(QStringLiteral("segmentationWidth")).toInt();
    const auto mask_height =
        retouch.value(QStringLiteral("segmentationHeight")).toInt();
    const auto mask_bounds =
        selected_agent_retouch_bounds(mask_data, mask_width, mask_height);
    if (!mask_bounds.isValid()) {
      errors.append(QStringLiteral(
          "Approved agent retouch %1 produced an empty bounded mask.")
                        .arg(retouch_id));
      artifact.insert(QStringLiteral("status"), QStringLiteral("empty-mask"));
      artifacts.append(artifact);
      break;
    }

    auto seed_ok = false;
    const auto seed = stable_variant_hash(QVariantMap{
                          {QStringLiteral("retouchId"), retouch_id},
                          {QStringLiteral("sourceImageVersion"),
                           source_image_version},
                      })
                          .left(7)
                          .toInt(&seed_ok, 16);
    const auto target_name = retouch.value(QStringLiteral("name"))
                                 .toString()
                                 .remove(QStringLiteral("Agent · "))
                                 .simplified();
    const auto requested_result =
        retouch.value(QStringLiteral("agentInstruction")).toString().simplified();
    auto prompt = QStringLiteral(
                      "Remove only %1 inside the reviewed bounded mask.")
                      .arg(target_name.isEmpty()
                               ? QStringLiteral("the reviewed distraction")
                               : target_name);
    if (!requested_result.isEmpty()) {
      prompt.append(QStringLiteral(" Requested result: %1.")
                        .arg(requested_result.left(240)));
    }
    prompt.append(QStringLiteral(" Preserve every surrounding pixel."));
    const auto inpaint_result = run_ai_inpaint(AiInpaintRequest{
        .source_image = source_image,
        .mask_data = mask_data,
        .mask_width = mask_width,
        .mask_height = mask_height,
        .retouch_mode = mode,
        .prompt = prompt,
        .quality_mode = QStringLiteral("final"),
        .seed = seed_ok ? std::max(1, seed) : 1,
        .heal_texture_blend = std::clamp(
            retouch.value(QStringLiteral("healTextureBlend"), 0.38).toDouble(),
            0.0,
            1.0),
        .heal_color_blend = std::clamp(
            retouch.value(QStringLiteral("healColorBlend"), 0.72).toDouble(),
            0.0,
            1.0),
    });
    auto selected_patch_image = inpaint_result.patch_image;
    auto selected_candidate_index = inpaint_result.candidate_index;
    if (inpaint_result.fallback &&
        inpaint_result.region_kind == QStringLiteral("spot") &&
        inpaint_result.candidate_images.size() > 1 &&
        !inpaint_result.candidate_images.at(1).isNull()) {
      selected_patch_image = inpaint_result.candidate_images.at(1);
      selected_candidate_index = 1;
    }
    const auto patch_data = encode_agent_inpaint_patch(selected_patch_image);
    if (!inpaint_result.success || patch_data.isEmpty() ||
        patch_data.size() > kMaxAgentInpaintPatchPayloadBytes ||
        inpaint_result.patch_width <= 0 ||
        inpaint_result.patch_height <= 0) {
      const auto materialization_error =
          patch_data.size() > kMaxAgentInpaintPatchPayloadBytes
              ? QStringLiteral("the patch exceeded the 96 MiB artifact limit")
          : inpaint_result.error_message.trimmed().isEmpty()
              ? QStringLiteral("no usable patch was returned")
              : inpaint_result.error_message.trimmed();
      errors.append(QStringLiteral(
          "The app-owned inpaint runtime could not materialize approved retouch %1: %2")
                        .arg(retouch_id, materialization_error));
      artifact.insert(QStringLiteral("status"), QStringLiteral("inpaint-failed"));
      artifacts.append(artifact);
      break;
    }

    retouch.insert(QStringLiteral("toolRole"), QStringLiteral("retouch"));
    retouch.insert(QStringLiteral("committed"), true);
    retouch.insert(QStringLiteral("inpaintPatchData"), patch_data);
    retouch.insert(QStringLiteral("inpaintPatchX"), inpaint_result.patch_x);
    retouch.insert(QStringLiteral("inpaintPatchY"), inpaint_result.patch_y);
    retouch.insert(QStringLiteral("inpaintPatchWidth"), inpaint_result.patch_width);
    retouch.insert(QStringLiteral("inpaintPatchHeight"), inpaint_result.patch_height);
    retouch.insert(QStringLiteral("inpaintPatchColorSpace"), QStringLiteral("sRGB"));
    retouch.insert(QStringLiteral("inpaintPatchSchemaVersion"), 1);
    retouch.insert(QStringLiteral("inpaintModelName"), inpaint_result.model_name);
    if (!inpaint_result.runtime_provider.isEmpty()) {
      retouch.insert(QStringLiteral("inpaintRuntimeProvider"),
                     inpaint_result.runtime_provider);
    }
    if (!inpaint_result.acceleration_warning.isEmpty()) {
      retouch.insert(QStringLiteral("inpaintAccelerationWarning"),
                     inpaint_result.acceleration_warning);
    }
    retouch.insert(QStringLiteral("inpaintCandidateIndex"),
                   selected_candidate_index);
    retouch.insert(QStringLiteral("inpaintSelectedVariationIndex"),
                   selected_candidate_index);
    retouch.insert(QStringLiteral("inpaintSelectedVariationSeed"),
                   inpaint_result.seed + selected_candidate_index);
    retouch.insert(QStringLiteral("inpaintSelectedVariationModelName"),
                   inpaint_result.model_name);
    retouch.insert(QStringLiteral("inpaintSourceMaskData"), mask_data);
    retouch.insert(QStringLiteral("inpaintSourceMaskWidth"), mask_width);
    retouch.insert(QStringLiteral("inpaintSourceMaskHeight"), mask_height);
    retouch.insert(QStringLiteral("inpaintSourceBoundsX"), mask_bounds.x());
    retouch.insert(QStringLiteral("inpaintSourceBoundsY"), mask_bounds.y());
    retouch.insert(QStringLiteral("inpaintSourceBoundsWidth"), mask_bounds.width());
    retouch.insert(QStringLiteral("inpaintSourceBoundsHeight"), mask_bounds.height());
    retouch.insert(QStringLiteral("inpaintPrompt"), prompt);
    retouch.insert(QStringLiteral("inpaintQualityMode"), QStringLiteral("final"));
    retouch.insert(QStringLiteral("inpaintFinalRequired"), false);
    retouch.insert(QStringLiteral("inpaintSeed"),
                   inpaint_result.seed + selected_candidate_index);
    retouch.insert(QStringLiteral("inpaintBlendAmount"), 1.0);
    retouch.insert(
        QStringLiteral("inpaintSeamFeather"),
        inpaint_result.region_kind == QStringLiteral("spot") ? 1.0 : 4.0);
    retouch.insert(QStringLiteral("inpaintColorMatch"), 0.75);
    retouch.insert(QStringLiteral("inpaintFallback"), inpaint_result.fallback);
    retouch.insert(QStringLiteral("inpaintRegionKind"), inpaint_result.region_kind);
    retouch.insert(QStringLiteral("inpaintEdgeContinuation"),
                   inpaint_result.edge_continuation);
    retouch.insert(QStringLiteral("inpaintTextureSynthesis"),
                   inpaint_result.texture_synthesis);
    retouch.insert(QStringLiteral("inpaintTextureExemplar"),
                   inpaint_result.texture_exemplar);
    retouch.insert(QStringLiteral("inpaintTextureStrength"),
                   inpaint_result.texture_strength);
    retouch.insert(QStringLiteral("inpaintTextureResidualMean"),
                   inpaint_result.texture_residual_mean);
    retouch.insert(QStringLiteral("inpaintRegionCoverage"),
                   inpaint_result.region_coverage);
    retouch.insert(QStringLiteral("inpaintRegionX"), inpaint_result.region_x);
    retouch.insert(QStringLiteral("inpaintRegionY"), inpaint_result.region_y);
    retouch.insert(QStringLiteral("inpaintRegionWidth"),
                   inpaint_result.region_width);
    retouch.insert(QStringLiteral("inpaintRegionHeight"),
                   inpaint_result.region_height);
    if (inpaint_result.fallback && !inpaint_result.error_message.isEmpty()) {
      retouch.insert(QStringLiteral("inpaintFallbackReason"),
                     inpaint_result.error_message);
    }
    retouch.insert(QStringLiteral("inpaintPatchPayloadBytes"), patch_data.size());
    const auto reviewed_plan_hash =
        stable_variant_hash(retouch_stack.at(index));
    retouch_stack[index] = retouch;
    ++materialized_count;
    fallback_count += inpaint_result.fallback ? 1 : 0;
    artifact.insert(QStringLiteral("status"), QStringLiteral("materialized"));
    artifact.insert(QStringLiteral("modelName"), inpaint_result.model_name);
    artifact.insert(QStringLiteral("runtimeProvider"),
                    inpaint_result.runtime_provider);
    if (!inpaint_result.acceleration_warning.isEmpty()) {
      artifact.insert(QStringLiteral("accelerationWarning"),
                      inpaint_result.acceleration_warning);
    }
    artifact.insert(QStringLiteral("runtimeLabel"),
                    inpaint_result.fallback &&
                            !inpaint_result.candidate_selection.isEmpty()
                        ? QStringLiteral("Quality-Selected CPU Fill")
                        : ai_model_runtime_status().inpaint_runtime_label);
    artifact.insert(QStringLiteral("fallback"), inpaint_result.fallback);
    artifact.insert(QStringLiteral("qualityMode"), inpaint_result.quality_mode);
    artifact.insert(QStringLiteral("regionKind"), inpaint_result.region_kind);
    artifact.insert(QStringLiteral("textureResidualMean"),
                    inpaint_result.texture_residual_mean);
    artifact.insert(QStringLiteral("textureStrength"),
                    inpaint_result.texture_strength);
    artifact.insert(QStringLiteral("textureExemplar"),
                    inpaint_result.texture_exemplar);
    artifact.insert(QStringLiteral("alternateCandidateEvaluated"),
                    inpaint_result.alternate_candidate_evaluated);
    if (!inpaint_result.alternate_model_name.isEmpty()) {
      artifact.insert(QStringLiteral("alternateModelName"),
                      inpaint_result.alternate_model_name);
    }
    if (!inpaint_result.candidate_selection.isEmpty()) {
      artifact.insert(QStringLiteral("candidateSelection"),
                      inpaint_result.candidate_selection);
    }
    artifact.insert(QStringLiteral("reviewedRegionGeometryApplied"),
                    used_reviewed_region);
    if (used_reviewed_region) {
      artifact.insert(QStringLiteral("reviewedRegionCoverageExpansion"), 1.5);
    }
    artifact.insert(QStringLiteral("selectedCandidateIndex"),
                    selected_candidate_index);
    artifact.insert(QStringLiteral("sourceWidth"), mask_width);
    artifact.insert(QStringLiteral("sourceHeight"), mask_height);
    artifact.insert(QStringLiteral("sourceBoundsX"), mask_bounds.x());
    artifact.insert(QStringLiteral("sourceBoundsY"), mask_bounds.y());
    artifact.insert(QStringLiteral("sourceBoundsWidth"), mask_bounds.width());
    artifact.insert(QStringLiteral("sourceBoundsHeight"), mask_bounds.height());
    artifact.insert(QStringLiteral("patchPayloadBytes"), patch_data.size());
    artifact.insert(QStringLiteral("sourceImageVersion"), source_image_version);
    artifact.insert(QStringLiteral("reviewedPlanHash"), reviewed_plan_hash);
    artifacts.append(artifact);
  }

  if (!retouch_stack.isEmpty()) {
    retouch_group.insert(QStringLiteral("appendRetouchStack"), retouch_stack);
    materialization.patch.insert(QStringLiteral("retouch"), retouch_group);
  }
  materialization.report = QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-approved-retouch-materialization-v1")},
      {QStringLiteral("artifactOwner"), QStringLiteral("application")},
      {QStringLiteral("requestedCount"), requested_count},
      {QStringLiteral("materializedCount"), materialized_count},
      {QStringLiteral("fallbackCount"), fallback_count},
      {QStringLiteral("sourceImageVersion"), source_image_version},
      {QStringLiteral("reviewedSensitivePlan"), reviewed_sensitive_plan},
      {QStringLiteral("fullResolution"), true},
      {QStringLiteral("durationMs"), timer.elapsed()},
      {QStringLiteral("failClosed"), true},
      {QStringLiteral("artifacts"), artifacts},
      {QStringLiteral("warnings"), warnings},
      {QStringLiteral("errors"), errors},
      {QStringLiteral("ok"), errors.isEmpty() &&
                                materialized_count == requested_count},
  };
  return materialization;
}

[[nodiscard]] AgentRetouchArtifactMaterialization
materialize_agent_retouch_artifacts_on_worker(
    const QVariantMap& requested_patch,
    const QString& file_path,
    const EditRecipeState& state,
    const QString& source_image_version,
    bool reviewed_sensitive_plan) {
  QElapsedTimer worker_timer;
  worker_timer.start();
  QFutureWatcher<AgentRetouchArtifactMaterialization> watcher;
  watcher.setFuture(QtConcurrent::run(
      [requested_patch,
       file_path,
       state,
       source_image_version,
       reviewed_sensitive_plan]() {
        return materialize_agent_retouch_artifacts(
            requested_patch,
            file_path,
            state,
            source_image_version,
            reviewed_sensitive_plan);
      }));
  auto ui_event_pump_count = 0;
  while (!watcher.isFinished()) {
    QCoreApplication::processEvents(QEventLoop::AllEvents, 5);
    QThread::msleep(1);
    ++ui_event_pump_count;
  }
  QCoreApplication::processEvents(QEventLoop::AllEvents, 5);
  auto materialization = watcher.result();
  materialization.report.insert(
      QStringLiteral("executionMode"), QStringLiteral("background-worker"));
  materialization.report.insert(QStringLiteral("backgroundThread"), true);
  materialization.report.insert(
      QStringLiteral("uiEventPumpCount"), ui_event_pump_count);
  materialization.report.insert(
      QStringLiteral("uiEventLoopServiced"), ui_event_pump_count > 0);
  materialization.report.insert(
      QStringLiteral("workerDurationMs"), worker_timer.elapsed());
  return materialization;
}

QString project_taste_evidence_id(
    const QString& kind,
    const QVariantMap& evidence) {
  QString preferred_id;
  if (kind == QStringLiteral("approved-look") ||
      kind == QStringLiteral("rejected-draft")) {
    preferred_id = evidence.value(QStringLiteral("runId")).toString();
  } else if (kind == QStringLiteral("approved-correction")) {
    preferred_id = evidence.value(QStringLiteral("approvedRunId")).toString();
    if (preferred_id.trimmed().isEmpty()) {
      preferred_id =
          evidence.value(QStringLiteral("revisedFromRunId")).toString();
    }
  } else if (kind == QStringLiteral("visual-referent")) {
    preferred_id = evidence.value(QStringLiteral("id")).toString();
  } else if (kind == QStringLiteral("photographer-calibration")) {
    preferred_id =
        evidence.value(QStringLiteral("profileDigestSha256")).toString();
  } else if (kind == QStringLiteral("story-preference")) {
    preferred_id = evidence.value(QStringLiteral("id")).toString();
  }
  if (!preferred_id.trimmed().isEmpty()) {
    return preferred_id.trimmed();
  }
  return QStringLiteral("%1-%2")
      .arg(kind, stable_variant_hash(evidence).left(16));
}

double edit_loop_quality_score(const QVariantMap& validation_report) {
  auto quality_score = validation_report.value(QStringLiteral("qualityScore"), 0.0).toDouble();
  const auto style_match = validation_report.value(QStringLiteral("styleMatch")).toMap();
  if (!style_match.isEmpty() && style_match.value(QStringLiteral("available")).toBool()) {
    const auto style_score = style_match.value(QStringLiteral("score"), 1.0).toDouble();
    quality_score = std::min(quality_score, (quality_score * 0.72) + (style_score * 0.28));
  }
  if (!validation_report.value(QStringLiteral("ok")).toBool()) {
    return 0.0;
  }
  return std::clamp(quality_score, 0.0, 1.0);
}

QVariantMap explicit_intent_match_report(
    const QString& instructions,
    const QVariantMap& recipe_patch,
    const QVariantMap& validation_report) {
  const auto intent = instructions.trimmed().toLower();
  const auto monochrome_required =
      intent.contains(QStringLiteral("black and white")) ||
      intent.contains(QStringLiteral("black & white")) ||
      intent.contains(QStringLiteral("monochrome"));
  const auto crop_required =
      intent.contains(QStringLiteral("better crop")) ||
      intent.contains(QStringLiteral("improve the crop")) ||
      intent.contains(QStringLiteral("improve crop")) ||
      intent.contains(QStringLiteral("tighter crop")) ||
      intent.contains(QStringLiteral("reframe"));
  const auto strong_contrast_required =
      intent.contains(QStringLiteral("super contrast")) ||
      intent.contains(QStringLiteral("high contrast")) ||
      intent.contains(QStringLiteral("strong contrast")) ||
      intent.contains(QStringLiteral("contrasty"));
  const auto requirement_count = static_cast<int>(monochrome_required) +
                                 static_cast<int>(crop_required) +
                                 static_cast<int>(strong_contrast_required);
  if (requirement_count == 0) {
    return QVariantMap{{QStringLiteral("available"), false}};
  }

  QVariantList checks;
  QStringList issues;
  auto passed_count = 0;
  const auto append_check = [&](const QString& name, bool passed, const QString& detail) {
    checks.append(QVariantMap{
        {QStringLiteral("name"), name},
        {QStringLiteral("passed"), passed},
        {QStringLiteral("detail"), detail},
    });
    if (passed) {
      ++passed_count;
    } else {
      issues.append(detail);
    }
  };

  if (monochrome_required) {
    const auto saturation = recipe_patch.value(QStringLiteral("color"))
                                .toMap()
                                .value(QStringLiteral("saturation"))
                                .toDouble();
    const auto channel_imbalance = validation_report.value(QStringLiteral("channelImbalance"), 1.0).toDouble();
    const auto passed = saturation <= -95.0 && channel_imbalance <= 0.04;
    append_check(
        QStringLiteral("monochrome"),
        passed,
        passed ? QStringLiteral("Rendered proof is monochrome.")
               : QStringLiteral("The rendered proof is still visibly colored."));
  }
  if (crop_required) {
    const auto crop = recipe_patch.value(QStringLiteral("crop")).toMap();
    const auto width = crop.value(QStringLiteral("cropWidth"), 1.0).toDouble();
    const auto height = crop.value(QStringLiteral("cropHeight"), 1.0).toDouble();
    const auto passed = !crop.isEmpty() && width < 0.98 && height < 0.98;
    append_check(
        QStringLiteral("crop"),
        passed,
        passed ? QStringLiteral("A visible crop was rendered.")
               : QStringLiteral("The requested crop was not applied."));
  }
  if (strong_contrast_required) {
    const auto contrast = recipe_patch.value(QStringLiteral("globalTone"))
                              .toMap()
                              .value(QStringLiteral("contrast"))
                              .toDouble();
    const auto passed = contrast >= 35.0;
    append_check(
        QStringLiteral("strongContrast"),
        passed,
        passed ? QStringLiteral("Strong contrast was applied.")
               : QStringLiteral("The requested strong contrast was not applied."));
  }

  const auto score = static_cast<double>(passed_count) / static_cast<double>(requirement_count);
  return QVariantMap{
      {QStringLiteral("available"), true},
      {QStringLiteral("ok"), passed_count == requirement_count},
      {QStringLiteral("score"), score},
      {QStringLiteral("scorePercent"), static_cast<int>(std::round(score * 100.0))},
      {QStringLiteral("requiredCount"), requirement_count},
      {QStringLiteral("passedCount"), passed_count},
      {QStringLiteral("checks"), checks},
      {QStringLiteral("issues"), issues},
  };
}

