QString agent_plan_request_fingerprint(
    const AgentLocalModelPlanRequest& request) {
  const QVariantMap fingerprint_input{
      {QStringLiteral("modelId"), request.model_id},
      {QStringLiteral("style"), request.style},
      {QStringLiteral("asset"), request.asset},
      {QStringLiteral("currentAdjustmentPatchJson"),
       request.current_adjustment_patch_json},
      {QStringLiteral("userInstructions"), request.user_instructions},
      {QStringLiteral("availableToolSchemas"),
       request.available_tool_schemas},
      {QStringLiteral("priorToolResults"), request.prior_tool_results},
      {QStringLiteral("strategyPhase"), request.strategy_phase},
      {QStringLiteral("memoryPacket"), request.memory_packet},
      {QStringLiteral("fewShotExamples"), request.few_shot_examples},
      {QStringLiteral("allowToolCallPlan"), request.allow_tool_call_plan},
      {QStringLiteral("forceModelPlanning"), request.force_model_planning},
      {QStringLiteral("allowDeterministicFallback"), request.allow_deterministic_fallback},
  };
  return QString::fromLatin1(
      QCryptographicHash::hash(
          QJsonDocument::fromVariant(fingerprint_input)
              .toJson(QJsonDocument::Compact),
          QCryptographicHash::Sha256)
          .toHex());
}

