class ScopedInteractiveRenderingPriority final {
 public:
  explicit ScopedInteractiveRenderingPriority(CatalogAssetModel* catalog_model)
      : catalog_model_(catalog_model) {
    if (catalog_model_ != nullptr) {
      catalog_model_->setInteractiveRenderingActive(true);
    }
  }

  ~ScopedInteractiveRenderingPriority() {
    if (catalog_model_ != nullptr) {
      catalog_model_->setInteractiveRenderingActive(false);
    }
  }

  ScopedInteractiveRenderingPriority(
      const ScopedInteractiveRenderingPriority&) = delete;
  ScopedInteractiveRenderingPriority& operator=(
      const ScopedInteractiveRenderingPriority&) = delete;

 private:
  CatalogAssetModel* catalog_model_ = nullptr;
};

WorkerPlanResult plan_agent_recipe_patch_on_worker(const AgentLocalModelPlanRequest& request) {
  auto future = std::async(
      std::launch::async,
      [request]() {
        return plan_agent_recipe_patch(request);
      });

  WorkerPlanResult result;
  while (future.wait_for(std::chrono::milliseconds(0)) != std::future_status::ready) {
    ++result.ui_event_pump_count;
    if (QCoreApplication::instance() != nullptr) {
      QCoreApplication::processEvents(QEventLoop::AllEvents, 5);
    } else {
      std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
  }
  result.plan = future.get();
  return result;
}

WorkerProofResult render_agent_proof_artifacts_on_worker(
    const QString& file_path,
    const EditRecipeState& before_state,
    const EditRecipeState& after_state,
    const QVariantMap& style,
    const QString& run_id,
    const QString& asset_id,
    const QVariantMap& patch,
    const ProofCancellationCallback& cancellation_requested,
    const ProofSuspensionCallback& suspension_observed,
    int proof_max_edge,
    const QString& cached_before_proof_path,
    const QString& intent_instructions,
    const QVariantMap& edit_intent) {
  constexpr auto kUiEventPumpInterval = std::chrono::milliseconds(5);
  auto worker_cancellation_requested =
      std::make_shared<std::atomic_bool>(false);
  QElapsedTimer worker_timer;
  worker_timer.start();
  QElapsedTimer pump_timer;
  pump_timer.start();
  qint64 previous_pump_sample_ms = 0;
  auto future = std::async(
      std::launch::async,
      [file_path, before_state, after_state, style, run_id, asset_id, patch,
       proof_max_edge, cached_before_proof_path, intent_instructions, edit_intent,
       worker_cancellation_requested]() {
        return render_agent_proof_artifacts(
            file_path,
            before_state,
            after_state,
            style,
            run_id,
            asset_id,
            patch,
            worker_cancellation_requested.get(),
            proof_max_edge,
            cached_before_proof_path,
            intent_instructions,
            edit_intent);
      });

  WorkerProofResult result;
  while (true) {
    const auto future_status = future.wait_for(kUiEventPumpInterval);
    const auto pump_sample_ms = pump_timer.elapsed();
    const auto active_clock_sample = agent_proof_worker_active_clock_sample(
        pump_sample_ms - previous_pump_sample_ms,
        static_cast<qint64>(kUiEventPumpInterval.count()));
    previous_pump_sample_ms = pump_sample_ms;
    if (active_clock_sample.value(QStringLiteral("discontinuityDetected")).toBool()) {
      ++result.suspension_count;
      const auto suspended_duration_ms =
          active_clock_sample.value(QStringLiteral("suspendedDurationMs"))
              .toLongLong();
      result.suspended_duration_ms += suspended_duration_ms;
      if (suspension_observed) {
        suspension_observed(suspended_duration_ms);
      }
    }
    if (future_status == std::future_status::ready) {
      break;
    }
    ++result.ui_event_pump_count;
    if (QCoreApplication::instance() != nullptr) {
      QCoreApplication::processEvents(QEventLoop::AllEvents, 1);
    }
    if (cancellation_requested && cancellation_requested()) {
      result.cancellation_forwarded = true;
      worker_cancellation_requested->store(true, std::memory_order_relaxed);
    }
  }
  result.report = future.get();
  result.duration_ms =
      std::max<qint64>(0, worker_timer.elapsed() - result.suspended_duration_ms);
  result.report.insert(
      QStringLiteral("proofWorker"),
      QVariantMap{
          {QStringLiteral("contract"),
           QStringLiteral("agent-proof-worker-v1")},
          {QStringLiteral("backgroundThread"), true},
          {QStringLiteral("uiEventLoopServiced"), true},
          {QStringLiteral("controllerCallPending"), true},
          {QStringLiteral("renderLoopCancellation"), true},
          {QStringLiteral("uiEventPumpIntervalMs"),
           static_cast<int>(kUiEventPumpInterval.count())},
          {QStringLiteral("uiEventPumpCount"),
           result.ui_event_pump_count},
          {QStringLiteral("deadlineClock"),
           QStringLiteral("ui-pump-active-time")},
          {QStringLiteral("activeClockContract"),
           QStringLiteral("agent-proof-worker-active-clock-v1")},
          {QStringLiteral("discontinuityThresholdMs"), 5000},
          {QStringLiteral("suspensionCount"), result.suspension_count},
          {QStringLiteral("suspendedDurationMs"),
           result.suspended_duration_ms},
          {QStringLiteral("activeDurationMs"), result.duration_ms},
          {QStringLiteral("durationMs"), result.duration_ms},
          {QStringLiteral("cancellationForwarded"),
           result.cancellation_forwarded},
      });
  return result;
}

QString safe_artifact_id(const QString& value, const QString& fallback) {
  const auto trimmed = value.trimmed();
  QString safe;
  safe.reserve(trimmed.size());
  for (const auto character : trimmed) {
    if (character.isLetterOrNumber() || character == QLatin1Char('-') ||
        character == QLatin1Char('_') || character == QLatin1Char('.')) {
      safe.append(character);
    } else {
      safe.append(QLatin1Char('_'));
    }
  }
  return safe.isEmpty() ? fallback : safe;
}

bool write_json_artifact(const QString& path, const QVariantMap& payload, QStringList* warnings) {
  QSaveFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
    if (warnings != nullptr) {
      warnings->append(QStringLiteral("Unable to write agent artifact: %1").arg(path));
    }
    return false;
  }
  const auto bytes =
      QJsonDocument(QJsonObject::fromVariantMap(payload)).toJson(QJsonDocument::Indented);
  if (file.write(bytes) != bytes.size()) {
    if (warnings != nullptr) {
      warnings->append(QStringLiteral("Unable to write complete agent artifact: %1").arg(path));
    }
    return false;
  }
  if (!file.commit()) {
    if (warnings != nullptr) {
      warnings->append(QStringLiteral("Unable to commit agent artifact: %1").arg(path));
    }
    return false;
  }
  return true;
}

QString normalized_style_id(const QString& name) {
  auto normalized = name.trimmed().toLower();
  normalized.replace(QRegularExpression(QStringLiteral("[^a-z0-9]+")), QStringLiteral("-"));
  normalized.replace(QRegularExpression(QStringLiteral("^-+|-+$")), QString());
  normalized = normalized.left(48);
  normalized.replace(QRegularExpression(QStringLiteral("-+$")), QString());
  if (normalized.size() < 2) {
    normalized = QStringLiteral("agent-style");
  }
  return normalized;
}

QVariantMap merged_map(QVariantMap values, const QVariantMap& defaults) {
  for (auto iterator = defaults.cbegin(); iterator != defaults.cend(); ++iterator) {
    if (!values.contains(iterator.key())) {
      values.insert(iterator.key(), iterator.value());
    }
  }
  return values;
}

void insert_optional_storage_map(
    QVariantMap* document,
    const QVariantMap& style,
    const QString& storage_key,
    const QString& runtime_key) {
  if (document == nullptr) {
    return;
  }
  const auto value = style.value(storage_key, style.value(runtime_key));
  if (value.isValid() && !value.toMap().isEmpty()) {
    document->insert(storage_key, value);
  }
}

QVariantMap style_storage_document_from_runtime_style(const QVariantMap& style) {
  QVariantMap document{
      {QStringLiteral("schema_version"),
       style.value(QStringLiteral("schema_version"),
                   style.value(QStringLiteral("schemaVersion"),
                               kCurrentAgentEditStyleSchemaVersion))},
      {QStringLiteral("id"), style.value(QStringLiteral("id"))},
      {QStringLiteral("name"), style.value(QStringLiteral("name"))},
      {QStringLiteral("goal"), style.value(QStringLiteral("goal"))},
      {QStringLiteral("allowed_tools"),
       style.value(QStringLiteral("allowed_tools"),
                   style.value(QStringLiteral("allowedTools")))},
      {QStringLiteral("constraints"), style.value(QStringLiteral("constraints"))},
      {QStringLiteral("validation"), style.value(QStringLiteral("validation"))},
      {QStringLiteral("batch_behavior"),
       style.value(QStringLiteral("batch_behavior"),
                   style.value(QStringLiteral("batchBehavior")))},
  };
  const auto reference_policy =
      style.value(QStringLiteral("reference_policy"),
                  style.value(QStringLiteral("referencePolicy")));
  if (reference_policy.isValid() && !reference_policy.toMap().isEmpty()) {
    document.insert(QStringLiteral("reference_policy"), reference_policy);
  }
  insert_optional_storage_map(
      &document,
      style,
      QStringLiteral("learned_profile"),
      QStringLiteral("learnedProfile"));
  insert_optional_storage_map(
      &document,
      style,
      QStringLiteral("tool_knowledge"),
      QStringLiteral("toolKnowledge"));
  insert_optional_storage_map(
      &document,
      style,
      QStringLiteral("quality_model"),
      QStringLiteral("qualityModel"));
  insert_optional_storage_map(
      &document,
      style,
      QStringLiteral("project_workflow"),
      QStringLiteral("projectWorkflow"));
  return document;
}

