QVariantMap render_agent_analysis_artifacts(
    const QString& file_path,
    const EditRecipeState& state,
    const QVariantMap& style,
    const QString& run_id,
    const QString& asset_id,
    const QVariantMap& base_report,
    const std::atomic_bool* cancellation_requested = nullptr) {
  QVariantMap report = base_report;
  const auto canceled = [&]() {
    if (!cancellation_requested || !cancellation_requested->load(std::memory_order_relaxed)) return false;
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("canceled"), true);
    report.insert(QStringLiteral("errors"), QStringList{QStringLiteral("Planning proof canceled.")});
    return true;
  };
  if (canceled()) return report;
  QStringList warnings = report.value(QStringLiteral("warnings")).toStringList();
  const auto safe_run_id = safe_artifact_id(run_id, QStringLiteral("analysis"));
  const auto safe_asset_id = safe_artifact_id(asset_id, QStringLiteral("asset"));
  const auto artifact_directory = QDir(AppBootstrap::appDataLocation())
                                      .filePath(QStringLiteral("agent-runs/%1/%2")
                                                    .arg(safe_run_id, safe_asset_id));
  const auto proof_path = QDir(artifact_directory).filePath(QStringLiteral("current-proof.png"));
  const auto analysis_path =
      QDir(artifact_directory).filePath(QStringLiteral("analysis-report.json"));
  QVariantMap artifacts{
      {QStringLiteral("artifactDirectory"), artifact_directory},
      {QStringLiteral("currentProofPath"), proof_path},
      {QStringLiteral("analysisReportPath"), analysis_path},
  };
  if (!QDir().mkpath(artifact_directory)) {
    warnings.append(QStringLiteral("Unable to create agent artifact directory: %1")
                        .arg(artifact_directory));
  }

  QImage source;
  photo_editor::pipeline::DecodedImageMetadata decoded_metadata;
  const auto proof_render_source =
      agent_proof_render_source_policy(QStringLiteral("analysis-current-proof"));
  report.insert(QStringLiteral("proofRenderSource"), proof_render_source);
  if (!decode_source_image(
          file_path,
          &source,
          kAgentProofPreviewMaxEdge,
          state,
          &decoded_metadata)) {
    warnings.append(QStringLiteral("Unable to decode selected source for agent analysis."));
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("warnings"), warnings);
    report.insert(QStringLiteral("artifacts"), artifacts);
    write_json_artifact(analysis_path, report, &warnings);
    report.insert(QStringLiteral("warnings"), warnings);
    return report;
  }
  if (canceled()) return report;
  const auto proof = render_agent_proof_image(
      source,
      file_path,
      asset_id,
      state,
      &decoded_metadata);
  const auto& rendered = proof.image;
  if (rendered.isNull()) {
    warnings.append(
        proof.error.isEmpty()
            ? QStringLiteral(
                  "Unable to render current proof for agent analysis.")
            : QStringLiteral(
                  "Unable to render current proof for agent analysis: %1")
                  .arg(proof.error));
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("warnings"), warnings);
    report.insert(QStringLiteral("artifacts"), artifacts);
    write_json_artifact(analysis_path, report, &warnings);
    report.insert(QStringLiteral("warnings"), warnings);
    return report;
  }
  if (!proof.canonical_plan_cache_key.isEmpty()) {
    report.insert(
        QStringLiteral("canonicalPlanCacheKey"),
        proof.canonical_plan_cache_key);
  }

  if (canceled()) return report;
  if (!rendered.save(proof_path, "PNG")) {
    warnings.append(QStringLiteral("Unable to save analysis proof: %1").arg(proof_path));
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("errors"), warnings);
    return report;
  }
  auto validation_report = validate_agent_edit_image(rendered, state, style);
  const auto style_match =
      style_match_report_for_validation(validation_report, recipe_analysis_summary(state, QString()), style);
  validation_report.insert(QStringLiteral("styleMatch"), style_match);
  if (style_match.value(QStringLiteral("needsReview")).toBool()) {
    auto validation_warnings = validation_report.value(QStringLiteral("warnings")).toStringList();
    validation_warnings.append(QStringLiteral("style-match review recommended: score %1%")
                                   .arg(style_match.value(QStringLiteral("scorePercent")).toInt()));
    validation_report.insert(QStringLiteral("warnings"), validation_warnings);
  }
  warnings.append(validation_report.value(QStringLiteral("warnings")).toStringList());
  report.insert(QStringLiteral("warnings"), warnings);
  report.insert(QStringLiteral("validationReport"), validation_report);
  report.insert(QStringLiteral("proofRenderSource"), proof_render_source);
  report.insert(QStringLiteral("riskAssessment"), agent_risk_assessment(state, warnings));
  report.insert(QStringLiteral("proofWidth"), rendered.width());
  report.insert(QStringLiteral("proofHeight"), rendered.height());
  report.insert(QStringLiteral("artifacts"), artifacts);
  report.insert(QStringLiteral("artifactDirectory"), artifact_directory);
  report.insert(QStringLiteral("currentProofPath"), proof_path);
  report.insert(QStringLiteral("analysisReportPath"), analysis_path);
  write_json_artifact(analysis_path, report, &warnings);
  report.insert(QStringLiteral("warnings"), warnings);
  return report;
}

QVariantMap render_agent_proof_artifacts(
    const QString& file_path,
    const EditRecipeState& before_state,
    const EditRecipeState& after_state,
    const QVariantMap& style,
    const QString& run_id,
    const QString& asset_id,
    const QVariantMap& patch,
    const std::atomic_bool* cancellation_requested,
    int proof_max_edge,
    const QString& cached_before_proof_path,
    const QString& intent_instructions,
    const QVariantMap& edit_intent) {
  QVariantMap report;
  QStringList warnings;
  const auto safe_run_id = safe_artifact_id(run_id, QStringLiteral("draft"));
  const auto safe_asset_id = safe_artifact_id(asset_id, QStringLiteral("asset"));
  const auto run_directory = QDir(AppBootstrap::appDataLocation())
                                 .filePath(QStringLiteral("agent-runs/%1").arg(safe_run_id));
  const auto artifact_directory = QDir(run_directory).filePath(safe_asset_id);
  const auto before_path = QDir(artifact_directory).filePath(QStringLiteral("before.png"));
  const auto after_path = QDir(artifact_directory).filePath(QStringLiteral("after.png"));
  const auto retouch_baseline_path =
      QDir(artifact_directory).filePath(QStringLiteral("retouch-baseline.png"));
  const auto diff_path = QDir(artifact_directory).filePath(QStringLiteral("recipe-diff.json"));
  const auto validation_path =
      QDir(artifact_directory).filePath(QStringLiteral("validation-report.json"));
  QVariantMap artifacts{
      {QStringLiteral("artifactDirectory"), artifact_directory},
      {QStringLiteral("beforeProofPath"), before_path},
      {QStringLiteral("afterProofPath"), after_path},
      {QStringLiteral("recipeDiffPath"), diff_path},
      {QStringLiteral("validationReportPath"), validation_path},
  };
  const QVariantMap proof_render_policy{
      {QStringLiteral("cancellable"), true},
      {QStringLiteral("renderLoopCancellation"), true},
      {QStringLiteral("timeoutAware"), true},
      {QStringLiteral("maxEdge"), proof_max_edge},
      {QStringLiteral("resolutionPolicy"),
       proof_max_edge < kAgentProofPreviewMaxEdge
           ? QStringLiteral("fast-confirmed-referent-validation-preview")
           : QStringLiteral("standard-agent-validation-preview")},
      {QStringLiteral("checkpoints"),
       QStringList{
           QStringLiteral("before-decode"),
           QStringLiteral("before-before-render"),
           QStringLiteral("during-before-render"),
           QStringLiteral("before-retouch-baseline-render"),
           QStringLiteral("during-retouch-baseline-render"),
           QStringLiteral("before-after-render"),
           QStringLiteral("during-after-render"),
           QStringLiteral("before-save"),
           QStringLiteral("before-validation"),
       }},
  };
  const auto proof_render_source =
      agent_proof_render_source_policy(QStringLiteral("draft-validation-proof"));
  const auto recipe_diff = agent_recipe_patch_diff(before_state, after_state, patch);
  if (!QDir().mkpath(artifact_directory)) {
    warnings.append(QStringLiteral("Unable to create agent artifact directory: %1")
                        .arg(artifact_directory));
  }

  const auto cancellation_report = [&](const QString& checkpoint) {
    auto canceled_report = result_map(
        false,
        {},
        warnings
            << QStringLiteral("Agent proof rendering canceled at checkpoint: %1.")
                   .arg(checkpoint));
    canceled_report.insert(QStringLiteral("canceled"), true);
    canceled_report.insert(QStringLiteral("cancellationCheckpoint"), checkpoint);
    canceled_report.insert(QStringLiteral("proofRenderPolicy"), proof_render_policy);
    canceled_report.insert(QStringLiteral("proofRenderSource"), proof_render_source);
    canceled_report.insert(QStringLiteral("artifacts"), artifacts);
    canceled_report.insert(QStringLiteral("recipeDiff"), recipe_diff);
    auto cancellation_warnings =
        canceled_report.value(QStringLiteral("warnings")).toStringList();
    write_json_artifact(validation_path, canceled_report, &cancellation_warnings);
    canceled_report.insert(QStringLiteral("warnings"), cancellation_warnings);
    return canceled_report;
  };
  const auto canceled_at = [&](const QString& checkpoint, QVariantMap* output) {
    if (cancellation_requested != nullptr &&
        cancellation_requested->load(std::memory_order_relaxed)) {
      *output = cancellation_report(checkpoint);
      return true;
    }
    return false;
  };

  QImage source;
  photo_editor::pipeline::DecodedImageMetadata decoded_metadata;
  const auto capture_composition_source_fingerprint =
      edit_intent.value(QStringLiteral("compositionPhotoBaselineSourceHashRequested")).toBool();
  const auto composition_source_file_sha_before = capture_composition_source_fingerprint
      ? sha256_file_contents(file_path) : QString{};
  if (canceled_at(QStringLiteral("before-decode"), &report)) {
    return report;
  }
  if (!decode_source_image(
          file_path,
          &source,
          proof_max_edge,
          after_state,
          &decoded_metadata)) {
    warnings.append(QStringLiteral("Unable to decode selected source for agent validation."));
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("warnings"), warnings);
    report.insert(QStringLiteral("artifacts"), artifacts);
    report.insert(QStringLiteral("recipeDiff"), recipe_diff);
    report.insert(QStringLiteral("proofRenderPolicy"), proof_render_policy);
    report.insert(QStringLiteral("proofRenderSource"), proof_render_source);
    return report;
  }
  if (canceled_at(QStringLiteral("before-before-render"), &report)) {
    return report;
  }
  AgentProofRenderResult before_proof;
  auto before_proof_reused = false;
  if (!cached_before_proof_path.isEmpty()) {
    QImage cached_before(cached_before_proof_path);
    if (!cached_before.isNull()) {
      before_proof.image =
          cached_before.size() == source.size()
              ? cached_before
              : cached_before.scaled(
                    source.size(),
                    Qt::IgnoreAspectRatio,
                    Qt::SmoothTransformation);
      before_proof_reused = !before_proof.image.isNull();
    }
  }
  if (!before_proof_reused) {
    before_proof = render_agent_proof_image(
        source,
        file_path,
        asset_id,
        before_state,
        &decoded_metadata,
        cancellation_requested);
  }
  AgentProofRenderResult retouch_baseline_proof;
  const auto retouch_proof_required = agent_retouch_request_count(patch) > 0;
  if (retouch_proof_required) {
    if (canceled_at(QStringLiteral("before-retouch-baseline-render"), &report)) {
      return report;
    }
    const auto retouch_baseline_state =
        recipe_without_materialized_agent_retouches(after_state, patch);
    retouch_baseline_proof = render_agent_proof_image(
        source,
        file_path,
        asset_id,
        retouch_baseline_state,
        &decoded_metadata,
        cancellation_requested);
    artifacts.insert(
        QStringLiteral("retouchBaselineProofPath"),
        retouch_baseline_path);
  }
  if (canceled_at(QStringLiteral("before-after-render"), &report)) {
    return report;
  }
  const auto after_proof = render_agent_proof_image(
      source,
      file_path,
      asset_id,
      after_state,
      &decoded_metadata,
      cancellation_requested);
  const auto& before_rendered = before_proof.image;
  const auto& after_rendered = after_proof.image;
  if (before_rendered.isNull() || after_rendered.isNull() ||
      (retouch_proof_required && retouch_baseline_proof.image.isNull())) {
    const auto proof_error =
        !before_proof.error.isEmpty()
            ? before_proof.error
            : !after_proof.error.isEmpty()
                  ? after_proof.error
                  : retouch_baseline_proof.error;
    warnings.append(
        proof_error.isEmpty()
            ? QStringLiteral(
                  "Unable to render draft proof for agent validation.")
            : QStringLiteral(
                  "Unable to render draft proof for agent validation: %1")
                  .arg(proof_error));
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("warnings"), warnings);
    report.insert(QStringLiteral("artifacts"), artifacts);
    report.insert(QStringLiteral("recipeDiff"), recipe_diff);
    report.insert(QStringLiteral("proofRenderPolicy"), proof_render_policy);
    report.insert(QStringLiteral("proofRenderSource"), proof_render_source);
    return report;
  }
  if (canceled_at(QStringLiteral("before-save"), &report)) {
    return report;
  }
  if (!before_rendered.save(before_path, "PNG")) {
    warnings.append(QStringLiteral("Unable to save before proof: %1").arg(before_path));
  }
  if (!after_rendered.save(after_path, "PNG")) {
    warnings.append(QStringLiteral("Unable to save after proof: %1").arg(after_path));
  }
  if (retouch_proof_required &&
      !retouch_baseline_proof.image.save(retouch_baseline_path, "PNG")) {
    warnings.append(
        QStringLiteral("Unable to save retouch baseline proof: %1")
            .arg(retouch_baseline_path));
  }
  write_json_artifact(diff_path, recipe_diff, &warnings);

  if (canceled_at(QStringLiteral("before-validation"), &report)) {
    return report;
  }
  report = validate_agent_edit_image(after_rendered, after_state, style);
  const auto retouch_proof_quality = evaluate_agent_retouch_proof_quality(
      retouch_baseline_proof.image,
      after_rendered,
      patch);
  report.insert(QStringLiteral("retouchProofQuality"), retouch_proof_quality);
  if (retouch_proof_quality.value(QStringLiteral("required")).toBool() &&
      !retouch_proof_quality.value(QStringLiteral("ok")).toBool()) {
    auto retouch_errors = report.value(QStringLiteral("errors")).toStringList();
    const auto retouch_failure =
        retouch_proof_quality.value(QStringLiteral("failureReason"))
            .toString();
    retouch_errors.append(
        retouch_failure.isEmpty()
            ? QStringLiteral("Retouch proof did not pass production quality validation.")
            : retouch_failure);
    report.insert(QStringLiteral("errors"), retouch_errors);
    report.insert(QStringLiteral("failureReason"),
                  retouch_errors.join(QStringLiteral("; ")));
    report.insert(QStringLiteral("needsUserReview"), true);
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("qualityScore"), 0.0);
    report.insert(QStringLiteral("qualityScorePercent"), 0);
  }
  const auto before_image_stats =
      validate_agent_edit_image(before_rendered).value(QStringLiteral("imageStats")).toMap();
  const auto after_image_stats = report.value(QStringLiteral("imageStats")).toMap();
  report.insert(QStringLiteral("beforeImageStats"), before_image_stats);
  const auto pixel_intent_alignment = evaluate_agent_edit_intent_alignment(
      before_image_stats,
      after_image_stats,
      intent_instructions,
      edit_intent);
  report.insert(QStringLiteral("pixelIntentAlignment"), pixel_intent_alignment);
  if (pixel_intent_alignment.value(QStringLiteral("available")).toBool() &&
      !pixel_intent_alignment.value(QStringLiteral("ok")).toBool()) {
    auto intent_warnings = report.value(QStringLiteral("warnings")).toStringList();
    intent_warnings.append(
        pixel_intent_alignment.value(QStringLiteral("issues")).toStringList());
    report.insert(QStringLiteral("warnings"), intent_warnings);
    report.insert(QStringLiteral("needsUserReview"), true);
    report.insert(QStringLiteral("ok"), false);
    report.insert(QStringLiteral("qualityScore"), 0.0);
    report.insert(QStringLiteral("qualityScorePercent"), 0);
  }
  if (!before_proof.canonical_plan_cache_key.isEmpty()) {
    report.insert(
        QStringLiteral("beforeCanonicalPlanCacheKey"),
        before_proof.canonical_plan_cache_key);
  }
  if (!after_proof.canonical_plan_cache_key.isEmpty()) {
    report.insert(
        QStringLiteral("afterCanonicalPlanCacheKey"),
        after_proof.canonical_plan_cache_key);
  }
  const auto style_match =
      style_match_report_for_validation(report, recipe_analysis_summary(after_state, QString()), style);
  report.insert(QStringLiteral("styleMatch"), style_match);
  if (style_match.value(QStringLiteral("needsReview")).toBool()) {
    auto style_match_warnings = report.value(QStringLiteral("warnings")).toStringList();
    style_match_warnings.append(QStringLiteral("style-match review recommended: score %1%")
                                    .arg(style_match.value(QStringLiteral("scorePercent")).toInt()));
    report.insert(QStringLiteral("warnings"), style_match_warnings);
  }
  auto validation_warnings = report.value(QStringLiteral("warnings")).toStringList();
  validation_warnings.append(warnings);
  report.insert(QStringLiteral("warnings"), validation_warnings);
  report.insert(QStringLiteral("proofRenderPolicy"), proof_render_policy);
  report.insert(QStringLiteral("beforeProofReused"), before_proof_reused);
  report.insert(
      QStringLiteral("beforeProofReusePolicy"),
      before_proof_reused
          ? QStringLiteral("same-asset-version-and-exact-before-recipe")
          : QStringLiteral("rendered-current-before-state"));
  report.insert(QStringLiteral("proofMaxEdge"), proof_max_edge);
  report.insert(
      QStringLiteral("proofResolutionPolicy"),
      proof_max_edge < kAgentProofPreviewMaxEdge
          ? QStringLiteral("fast-confirmed-referent-validation-preview")
          : QStringLiteral("standard-agent-validation-preview"));
  report.insert(QStringLiteral("proofRenderSource"), proof_render_source);
  report.insert(QStringLiteral("proofWidth"), after_rendered.width());
  report.insert(QStringLiteral("proofHeight"), after_rendered.height());
  report.insert(QStringLiteral("artifacts"), artifacts);
  report.insert(QStringLiteral("recipeDiff"), recipe_diff);
  if (capture_composition_source_fingerprint) {
    const auto composition_source_file_sha_after = sha256_file_contents(file_path);
    report.insert(QStringLiteral("compositionPhotoSourceFileSha256"),
        !composition_source_file_sha_before.isEmpty() &&
                composition_source_file_sha_before == composition_source_file_sha_after
            ? composition_source_file_sha_before : QString{});
    report.insert(QStringLiteral("compositionPhotoSourceFileStableDuringProof"),
        !composition_source_file_sha_before.isEmpty() &&
            composition_source_file_sha_before == composition_source_file_sha_after);
  }
  write_json_artifact(validation_path, report, &validation_warnings);
  report.insert(QStringLiteral("warnings"), validation_warnings);
  return report;
}

[[nodiscard]] QVariantMap project_north_star_draft_receipt(
    const QVariantMap& north_star,
    const QVariantMap& prompt_audit,
    const QVariantList& asset_reports) {
  const auto north_star_digest =
      north_star.value(QStringLiteral("digestSha256")).toString();
  const auto prompt_digest =
      prompt_audit.value(QStringLiteral("projectNorthStarDigest")).toString();
  const auto planning_considered =
      !north_star.isEmpty() && !north_star_digest.isEmpty() &&
      prompt_audit.value(QStringLiteral("projectNorthStarAvailable")).toBool() &&
      prompt_audit.value(
                      QStringLiteral("projectNorthStarCurrentRequestWins"))
          .toBool() &&
      prompt_digest == north_star_digest;
  if (!planning_considered) {
    return {};
  }

  auto proof_validated_count = 0;
  auto proof_critique_count = 0;
  for (const auto& asset_report_value : asset_reports) {
    const auto asset_report = asset_report_value.toMap();
    const auto validation =
        asset_report.value(QStringLiteral("validationReport")).toMap();
    const auto artifacts = validation.value(QStringLiteral("artifacts")).toMap();
    if (validation.value(QStringLiteral("ok")).toBool() &&
        !artifacts.value(QStringLiteral("afterProofPath"))
             .toString()
             .trimmed()
             .isEmpty()) {
      ++proof_validated_count;
    }
    const auto critique =
        validation.value(QStringLiteral("modelProofCritique")).toMap();
    if (critique.value(QStringLiteral("projectNorthStarApplied")).toBool() &&
        critique.value(QStringLiteral("projectNorthStarDigest")).toString() ==
            north_star_digest) {
      ++proof_critique_count;
    }
  }

  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-north-star-draft-receipt-v1")},
      {QStringLiteral("available"), true},
      {QStringLiteral("northStarId"), north_star.value(QStringLiteral("id"))},
      {QStringLiteral("projectKey"),
       north_star.value(QStringLiteral("projectKey"))},
      {QStringLiteral("brief"),
       north_star.value(QStringLiteral("brief")).toString().left(360)},
      {QStringLiteral("digestSha256"), north_star_digest},
      {QStringLiteral("planningConsidered"), true},
      {QStringLiteral("qualitativePlanningInfluence"), true},
      {QStringLiteral("proofValidated"), proof_validated_count > 0},
      {QStringLiteral("proofValidatedAssetCount"), proof_validated_count},
      {QStringLiteral("proofCritiqueConsidered"), proof_critique_count > 0},
      {QStringLiteral("proofCritiqueAssetCount"), proof_critique_count},
      {QStringLiteral("proofReviewMode"),
       proof_critique_count > 0
           ? QStringLiteral("local-model-plus-deterministic-validation")
           : QStringLiteral("deterministic-validation-only")},
      {QStringLiteral("currentRequestWins"), true},
      {QStringLiteral("styleAndSafetyWin"), true},
      {QStringLiteral("alignmentClaimed"), false},
      {QStringLiteral("requiresPhotographerJudgment"), true},
      {QStringLiteral("directNumericRecipeAuthority"), false},
      {QStringLiteral("automaticCullAuthority"), false},
      {QStringLiteral("automaticRetouchAuthority"), false},
      {QStringLiteral("destructiveAuthority"), false},
  };
}

