QVariantMap agent_proof_worker_active_clock_sample(
    qint64 observed_interval_ms,
    qint64 expected_interval_ms) {
  constexpr qint64 kDiscontinuityThresholdMs = 5000;
  const auto observed = std::max<qint64>(0, observed_interval_ms);
  const auto expected = std::max<qint64>(0, expected_interval_ms);
  const auto discontinuity_detected = observed > kDiscontinuityThresholdMs;
  const auto active_duration_ms =
      discontinuity_detected ? std::min(observed, expected) : observed;
  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-proof-worker-active-clock-v1")},
      {QStringLiteral("observedIntervalMs"), observed},
      {QStringLiteral("expectedIntervalMs"), expected},
      {QStringLiteral("discontinuityThresholdMs"),
       kDiscontinuityThresholdMs},
      {QStringLiteral("discontinuityDetected"), discontinuity_detected},
      {QStringLiteral("activeDurationMs"), active_duration_ms},
      {QStringLiteral("suspendedDurationMs"),
       discontinuity_detected ? observed - active_duration_ms : 0},
      {QStringLiteral("deadlineClock"),
       QStringLiteral("ui-pump-active-time")},
  };
}

QVariantMap agent_professional_consistency_map(
    const QVariantList& asset_reports) {
  struct Metric final {
    QString key;
    QString label;
    QString section;
    QString field;
    double tolerance = 0.0;
    bool skin_metric = false;
  };
  const std::array<Metric, 7> metrics{{
      {QStringLiteral("toneResponse"), QStringLiteral("Tone"),
       QStringLiteral("histogram"), QStringLiteral("averageLuma"), 8.0, false},
      {QStringLiteral("contrastResponse"), QStringLiteral("Contrast"),
       QStringLiteral("histogram"), QStringLiteral("lumaStddev"), 5.0, false},
      {QStringLiteral("warmthResponse"), QStringLiteral("Warmth"),
       QStringLiteral("rgb"), QStringLiteral("redBlueCast"), 0.06, false},
      {QStringLiteral("greenCastResponse"), QStringLiteral("Green cast"),
       QStringLiteral("rgb"), QStringLiteral("greenCast"), 0.045, false},
      {QStringLiteral("saturationResponse"), QStringLiteral("Saturation"),
       QStringLiteral("vectorscope"), QStringLiteral("averageSaturation"), 0.05, false},
      {QStringLiteral("skinHueResponse"), QStringLiteral("Skin hue"),
       QStringLiteral("skin"), QStringLiteral("averageHue"), 6.0, true},
      {QStringLiteral("skinLumaResponse"), QStringLiteral("Skin lightness"),
       QStringLiteral("skin"), QStringLiteral("averageLuma"), 10.0, true},
  }};

  const auto metric_response = [&](const QVariantMap& validation,
                                   const Metric& metric) -> QVariant {
    const auto before_stats =
        validation.value(QStringLiteral("beforeImageStats")).toMap();
    const auto after_stats =
        validation.value(QStringLiteral("imageStats")).toMap();
    const auto before_section = before_stats.value(metric.section).toMap();
    const auto after_section = after_stats.value(metric.section).toMap();
    if (!before_section.contains(metric.field) ||
        !after_section.contains(metric.field)) {
      return {};
    }
    if (metric.skin_metric) {
      const auto before_skin = before_stats.value(QStringLiteral("skin")).toMap();
      const auto after_skin = after_stats.value(QStringLiteral("skin")).toMap();
      if (before_skin.value(QStringLiteral("candidatePercent")).toDouble() < 1.0 ||
          after_skin.value(QStringLiteral("candidatePercent")).toDouble() < 1.0) {
        return {};
      }
    }
    const auto before = before_section.value(metric.field).toDouble();
    const auto after = after_section.value(metric.field).toDouble();
    if (!std::isfinite(before) || !std::isfinite(after)) {
      return {};
    }
    return after - before;
  };

  QVariantMap reports_by_cluster;
  QStringList unavailable_asset_ids;
  for (const auto& report_value : asset_reports) {
    const auto report = report_value.toMap();
    const auto asset_id = report.value(QStringLiteral("assetId")).toString().trimmed();
    if (asset_id.isEmpty()) {
      continue;
    }
    const auto validation = report.value(QStringLiteral("validationReport")).toMap();
    if (validation.value(QStringLiteral("beforeImageStats")).toMap().isEmpty() ||
        validation.value(QStringLiteral("imageStats")).toMap().isEmpty()) {
      unavailable_asset_ids.append(asset_id);
      continue;
    }
    auto cluster_id = report.value(QStringLiteral("clusterId")).toString().trimmed();
    if (cluster_id.isEmpty()) {
      cluster_id = QStringLiteral("unclustered");
    }
    auto reports = reports_by_cluster.value(cluster_id).toList();
    reports.append(report);
    reports_by_cluster.insert(cluster_id, reports);
  }

  QVariantList groups;
  QVariantList asset_results;
  QStringList drift_asset_ids;
  auto compared_asset_count = 0;
  auto evidence_asset_count = 0;
  auto consistent_asset_count = 0;
  auto checked_metric_count = 0;
  auto insufficient_asset_count = unavailable_asset_ids.size();
  const auto cluster_ids = reports_by_cluster.keys();
  for (auto cluster_index = 0; cluster_index < cluster_ids.size(); ++cluster_index) {
    const auto& cluster_id = cluster_ids.at(cluster_index);
    auto reports = reports_by_cluster.value(cluster_id).toList();
    std::sort(
        reports.begin(), reports.end(), [](const QVariant& left, const QVariant& right) {
          return left.toMap().value(QStringLiteral("assetId")).toString() <
                 right.toMap().value(QStringLiteral("assetId")).toString();
        });
    if (reports.isEmpty()) {
      continue;
    }

    auto representative_id = reports.first()
                                 .toMap()
                                 .value(QStringLiteral("clusterRepresentativeAssetId"))
                                 .toString()
                                 .trimmed();
    auto representative_index = 0;
    if (!representative_id.isEmpty()) {
      for (auto index = 0; index < reports.size(); ++index) {
        if (reports.at(index).toMap().value(QStringLiteral("assetId")).toString() ==
            representative_id) {
          representative_index = index;
          break;
        }
      }
    }
    const auto representative = reports.at(representative_index).toMap();
    representative_id = representative.value(QStringLiteral("assetId")).toString();
    const auto representative_validation =
        representative.value(QStringLiteral("validationReport")).toMap();
    QVariantMap representative_response;
    for (const auto& metric : metrics) {
      const auto response = metric_response(representative_validation, metric);
      if (response.isValid()) {
        representative_response.insert(metric.key, response);
      }
    }

    QVariantList group_asset_results;
    auto group_compared_count = 0;
    auto group_consistent_count = 0;
    auto group_drift_count = 0;
    auto group_metric_count = 0;
    for (const auto& report_value : reports) {
      const auto report = report_value.toMap();
      const auto asset_id = report.value(QStringLiteral("assetId")).toString();
      if (asset_id == representative_id) {
        continue;
      }
      const auto validation = report.value(QStringLiteral("validationReport")).toMap();
      QVariantList metric_results;
      QStringList drift_metrics;
      QStringList drift_metric_keys;
      QVariantList drift_evidence;
      QVariantMap repair_recipe_delta;
      auto auto_repair_safe = true;
      auto score_sum = 0.0;
      auto metric_count = 0;
      for (const auto& metric : metrics) {
        const auto response = metric_response(validation, metric);
        if (!response.isValid() || !representative_response.contains(metric.key)) {
          continue;
        }
        const auto actual = response.toDouble();
        const auto baseline = representative_response.value(metric.key).toDouble();
        const auto difference = std::abs(actual - baseline);
        const auto normalized_drift = difference / metric.tolerance;
        const auto aligned = normalized_drift <= 1.0;
        if (!aligned) {
          drift_metrics.append(metric.label);
          drift_metric_keys.append(metric.key);
          const auto target_delta = baseline - actual;
          if (metric.key == QStringLiteral("toneResponse")) {
            adjust_patch_number(
                &repair_recipe_delta,
                QStringLiteral("globalTone"),
                QStringLiteral("exposure"),
                std::clamp(target_delta / 24.0, -0.35, 0.35),
                -0.35,
                0.35);
          } else if (metric.key == QStringLiteral("contrastResponse")) {
            adjust_patch_number(
                &repair_recipe_delta,
                QStringLiteral("globalTone"),
                QStringLiteral("contrast"),
                std::clamp(target_delta * 2.0, -12.0, 12.0),
                -12.0,
                12.0);
          } else if (metric.key == QStringLiteral("warmthResponse")) {
            adjust_patch_number(
                &repair_recipe_delta,
                QStringLiteral("color"),
                QStringLiteral("temperature"),
                std::clamp(target_delta * 100.0, -8.0, 8.0),
                -8.0,
                8.0);
          } else if (metric.key == QStringLiteral("greenCastResponse")) {
            adjust_patch_number(
                &repair_recipe_delta,
                QStringLiteral("color"),
                QStringLiteral("tint"),
                std::clamp(target_delta * 100.0, -6.0, 6.0),
                -6.0,
                6.0);
          } else if (metric.key == QStringLiteral("saturationResponse")) {
            adjust_patch_number(
                &repair_recipe_delta,
                QStringLiteral("color"),
                QStringLiteral("saturation"),
                std::clamp(target_delta * 100.0, -8.0, 8.0),
                -8.0,
                8.0);
          } else {
            auto_repair_safe = false;
          }
          if (metric.skin_metric) {
            auto_repair_safe = false;
          }
          drift_evidence.append(QVariantMap{
              {QStringLiteral("key"), metric.key},
              {QStringLiteral("label"), metric.label},
              {QStringLiteral("response"), actual},
              {QStringLiteral("referenceResponse"), baseline},
              {QStringLiteral("difference"), difference},
              {QStringLiteral("tolerance"), metric.tolerance},
              {QStringLiteral("direction"),
               actual > baseline ? QStringLiteral("stronger-than-reference")
                                 : QStringLiteral("weaker-than-reference")},
          });
        }
        score_sum += std::clamp(1.0 - normalized_drift, 0.0, 1.0);
        ++metric_count;
        ++checked_metric_count;
        ++group_metric_count;
        metric_results.append(QVariantMap{
            {QStringLiteral("key"), metric.key},
            {QStringLiteral("label"), metric.label},
            {QStringLiteral("response"), actual},
            {QStringLiteral("baselineResponse"), baseline},
            {QStringLiteral("difference"), difference},
            {QStringLiteral("tolerance"), metric.tolerance},
            {QStringLiteral("aligned"), aligned},
        });
      }
      const auto comparable = metric_count >= 5;
      const auto aligned = comparable && drift_metrics.isEmpty();
      const auto score = metric_count <= 0
                             ? 0
                             : static_cast<int>(std::round(
                                   (score_sum / static_cast<double>(metric_count)) * 100.0));
      if (comparable) {
        ++compared_asset_count;
        ++group_compared_count;
        if (aligned) {
          ++consistent_asset_count;
          ++group_consistent_count;
        } else {
          drift_asset_ids.append(asset_id);
          ++group_drift_count;
        }
      } else {
        ++insufficient_asset_count;
      }
      QVariantMap asset_result{
          {QStringLiteral("assetId"), asset_id},
          {QStringLiteral("clusterId"), cluster_id},
          {QStringLiteral("representativeAssetId"), representative_id},
          {QStringLiteral("role"), QStringLiteral("compared")},
          {QStringLiteral("comparable"), comparable},
          {QStringLiteral("aligned"), aligned},
          {QStringLiteral("scorePercent"), score},
          {QStringLiteral("metricCount"), metric_count},
          {QStringLiteral("driftMetrics"), drift_metrics},
          {QStringLiteral("metrics"), metric_results},
      };
      if (!drift_metrics.isEmpty()) {
        const auto drift_label = drift_metrics.join(QStringLiteral(", "));
        const auto safe_auto_repair =
            auto_repair_safe && !repair_recipe_delta.isEmpty();
        asset_result.insert(
            QStringLiteral("repairGuidance"),
            QVariantMap{
                {QStringLiteral("contract"),
                 QStringLiteral("agent-consistency-drift-repair-v1")},
                {QStringLiteral("headline"),
                 QStringLiteral("Match %1 to this lighting group").arg(drift_label)},
                {QStringLiteral("summary"),
                 QStringLiteral("%1 moved differently from the approved group reference.")
                     .arg(drift_label)},
                {QStringLiteral("actionLabel"),
                 safe_auto_repair ? QStringLiteral("Match group")
                                  : QStringLiteral("Review match")},
                {QStringLiteral("suggestedAction"),
                 safe_auto_repair
                     ? QStringLiteral("Apply a bounded tone/color correction, render again, and keep it in review until the group response aligns.")
                     : QStringLiteral("Compare this proof with the group reference; skin-sensitive differences require your decision.")},
                {QStringLiteral("preservedSummary"),
                 QStringLiteral("Crop, framing, local masks, retouch, and texture stay untouched.")},
                {QStringLiteral("driftMetricKeys"), drift_metric_keys},
                {QStringLiteral("driftMetrics"), drift_metrics},
                {QStringLiteral("evidence"), drift_evidence},
                {QStringLiteral("autoRepairSafe"), safe_auto_repair},
                {QStringLiteral("recipeDelta"), repair_recipe_delta},
                {QStringLiteral("requiresFreshProof"), true},
                {QStringLiteral("keepsExceptionOpenUntilAligned"), true},
            });
      }
      group_asset_results.append(asset_result);
      asset_results.append(asset_result);
    }

    const auto group_has_evidence = group_compared_count > 0;
    if (group_has_evidence) {
      evidence_asset_count += group_compared_count + 1;
      ++consistent_asset_count;
      ++group_consistent_count;
    }
    const auto group_status =
        group_drift_count > 0
            ? QStringLiteral("attention")
            : group_has_evidence ? QStringLiteral("aligned")
                                 : QStringLiteral("needs-more-evidence");
    auto group_label = QStringLiteral("Lighting group %1").arg(cluster_index + 1);
    if (cluster_id == QStringLiteral("unclustered")) {
      group_label = QStringLiteral("Unclustered photos");
    }
    groups.append(QVariantMap{
        {QStringLiteral("clusterId"), cluster_id},
        {QStringLiteral("label"), group_label},
        {QStringLiteral("representativeAssetId"), representative_id},
        {QStringLiteral("photoCount"), reports.size()},
        {QStringLiteral("comparedCount"), group_compared_count},
        {QStringLiteral("consistentCount"), group_consistent_count},
        {QStringLiteral("driftCount"), group_drift_count},
        {QStringLiteral("checkedMetricCount"), group_metric_count},
        {QStringLiteral("evidenceComplete"), group_has_evidence},
        {QStringLiteral("status"), group_status},
        {QStringLiteral("assetResults"), group_asset_results},
    });
  }

  const auto asset_count = asset_reports.size();
  const auto drift_count = drift_asset_ids.size();
  const auto measurement_complete =
      asset_count >= 2 && evidence_asset_count == asset_count &&
      insufficient_asset_count == 0;
  const auto professional_gate_eligible =
      asset_count >= 8 && measurement_complete && groups.size() >= 1;
  const auto consistency_passed = measurement_complete && drift_count == 0;
  const auto ready_for_professional_use = false;
  const auto status =
      drift_count > 0
          ? QStringLiteral("attention")
          : measurement_complete ? QStringLiteral("aligned")
                                 : QStringLiteral("calibrating");
  QString headline;
  QString summary;
  if (drift_count > 0) {
    headline = QStringLiteral("%1 consistent · %2 drift")
                   .arg(consistent_asset_count)
                   .arg(drift_count);
    summary = QStringLiteral("Color or tone response moved differently in %1 photo%2.")
                  .arg(drift_count)
                  .arg(drift_count == 1 ? QString() : QStringLiteral("s"));
  } else if (measurement_complete) {
    headline = QStringLiteral("%1 photos move together").arg(consistent_asset_count);
    summary = QStringLiteral("Tone, color, and available skin response align within each lighting group.");
  } else {
    headline = QStringLiteral("Consistency proof is building");
    summary = QStringLiteral("At least two comparable photos are needed inside every lighting group.");
  }

  QVariantMap report{
      {QStringLiteral("contract"),
       QStringLiteral("agent-professional-consistency-map-v1")},
      {QStringLiteral("available"), asset_count >= 2},
      {QStringLiteral("status"), status},
      {QStringLiteral("headline"), headline},
      {QStringLiteral("summary"), summary},
      {QStringLiteral("basis"),
       QStringLiteral("within-lighting-group-relative-render-response")},
      {QStringLiteral("assetCount"), asset_count},
      {QStringLiteral("groupCount"), groups.size()},
      {QStringLiteral("evidenceAssetCount"), evidence_asset_count},
      {QStringLiteral("comparedAssetCount"), compared_asset_count},
      {QStringLiteral("consistentAssetCount"), consistent_asset_count},
      {QStringLiteral("driftCount"), drift_count},
      {QStringLiteral("driftAssetIds"), drift_asset_ids},
      {QStringLiteral("unavailableAssetIds"), unavailable_asset_ids},
      {QStringLiteral("insufficientAssetCount"), insufficient_asset_count},
      {QStringLiteral("checkedMetricCount"), checked_metric_count},
      {QStringLiteral("measurementComplete"), measurement_complete},
      {QStringLiteral("minimumProfessionalBatchSize"), 8},
      {QStringLiteral("professionalGateEligible"), professional_gate_eligible},
      {QStringLiteral("consistencyPassed"), consistency_passed},
      {QStringLiteral("readyForProfessionalUse"), ready_for_professional_use},
      {QStringLiteral("professionalReadinessClaimed"), false},
      {QStringLiteral("thresholdCalibrationStatus"),
       QStringLiteral("machine-regression-only")},
      {QStringLiteral("humanCalibrationRequired"), true},
      {QStringLiteral("groups"), groups},
      {QStringLiteral("assetResults"), asset_results},
      {QStringLiteral("thresholds"),
       QVariantMap{
           {QStringLiteral("toneResponse"), 8.0},
           {QStringLiteral("contrastResponse"), 5.0},
           {QStringLiteral("warmthResponse"), 0.06},
           {QStringLiteral("greenCastResponse"), 0.045},
           {QStringLiteral("saturationResponse"), 0.05},
           {QStringLiteral("skinHueResponse"), 6.0},
           {QStringLiteral("skinLumaResponse"), 10.0},
           {QStringLiteral("minimumComparableMetrics"), 5},
       }},
      {QStringLiteral("reproducibility"),
       QVariantMap{
           {QStringLiteral("deterministic"), true},
           {QStringLiteral("stableAssetOrdering"), true},
           {QStringLiteral("fixedThresholds"), true},
           {QStringLiteral("stochasticSampling"), false},
           {QStringLiteral("contract"),
            QStringLiteral("agent-consistency-reproducibility-v1")},
       }},
  };
  const auto digest_bytes =
      QJsonDocument::fromVariant(report).toJson(QJsonDocument::Compact);
  report.insert(
      QStringLiteral("digestSha256"),
      QString::fromLatin1(
          QCryptographicHash::hash(digest_bytes, QCryptographicHash::Sha256)
              .toHex()));
  return report;
}

QVariantMap agent_consistency_exception_routing(
    const QVariantMap& consistency_map,
    const QVariantList& asset_reports,
    const QVariantList& existing_review_issues) {
  QVariantMap reports_by_asset_id;
  for (const auto& report_value : asset_reports) {
    const auto report = report_value.toMap();
    const auto asset_id = report.value(QStringLiteral("assetId")).toString().trimmed();
    if (!asset_id.isEmpty()) {
      reports_by_asset_id.insert(asset_id, report);
    }
  }

  auto review_issues = existing_review_issues;
  QStringList added_asset_ids;
  QStringList augmented_asset_ids;
  QStringList manual_review_asset_ids;
  QStringList resolved_asset_ids;
  for (const auto& result_value :
       consistency_map.value(QStringLiteral("assetResults")).toList()) {
    const auto result = result_value.toMap();
    if (!result.value(QStringLiteral("comparable")).toBool() ||
        result.value(QStringLiteral("aligned")).toBool()) {
      continue;
    }
    const auto asset_id = result.value(QStringLiteral("assetId")).toString().trimmed();
    const auto asset_report = reports_by_asset_id.value(asset_id).toMap();
    const auto prior_resolution =
        asset_report.value(QStringLiteral("reviewIssueResolution")).toString();
    if (prior_resolution == QStringLiteral("accepted_anyway") ||
        prior_resolution == QStringLiteral("rolled_back")) {
      resolved_asset_ids.append(asset_id);
      continue;
    }
    const auto guidance = result.value(QStringLiteral("repairGuidance")).toMap();
    if (!guidance.value(QStringLiteral("autoRepairSafe")).toBool()) {
      manual_review_asset_ids.append(asset_id);
    }

    auto existing_index = -1;
    for (auto index = 0; index < review_issues.size(); ++index) {
      if (review_issues.at(index).toMap().value(QStringLiteral("assetId")).toString() ==
          asset_id) {
        existing_index = index;
        break;
      }
    }
    if (existing_index >= 0) {
      auto issue = review_issues.at(existing_index).toMap();
      issue.insert(QStringLiteral("consistencyDrift"), result);
      issue.insert(QStringLiteral("repairGuidance"), guidance);
      issue.insert(
          QStringLiteral("consistencyReason"),
          guidance.value(QStringLiteral("summary")));
      issue.insert(
          QStringLiteral("suggestedAction"),
          guidance.value(QStringLiteral("suggestedAction")));
      issue.insert(
          QStringLiteral("autoRepairAvailable"),
          guidance.value(QStringLiteral("autoRepairSafe")));
      review_issues[existing_index] = issue;
      augmented_asset_ids.append(asset_id);
      continue;
    }

    const auto validation =
        asset_report.value(QStringLiteral("validationReport")).toMap();
    const auto artifacts = validation.value(QStringLiteral("artifacts")).toMap().isEmpty()
                               ? asset_report.value(QStringLiteral("artifacts")).toMap()
                               : validation.value(QStringLiteral("artifacts")).toMap();
    review_issues.append(QVariantMap{
        {QStringLiteral("assetId"), asset_id},
        {QStringLiteral("displayName"),
         asset_report.value(QStringLiteral("displayName"))},
        {QStringLiteral("status"), QStringLiteral("needs_review")},
        {QStringLiteral("category"), QStringLiteral("consistency_drift")},
        {QStringLiteral("reason"), guidance.value(QStringLiteral("summary"))},
        {QStringLiteral("consistencyReason"), guidance.value(QStringLiteral("summary"))},
        {QStringLiteral("suggestedAction"),
         guidance.value(QStringLiteral("suggestedAction"))},
        {QStringLiteral("thumbnailPath"),
         artifacts.value(QStringLiteral("afterProofPath"))},
        {QStringLiteral("afterProofPath"),
         artifacts.value(QStringLiteral("afterProofPath"))},
        {QStringLiteral("clusterId"), result.value(QStringLiteral("clusterId"))},
        {QStringLiteral("warningCount"), 0},
        {QStringLiteral("errorCount"), 0},
        {QStringLiteral("consistencyDrift"), result},
        {QStringLiteral("repairGuidance"), guidance},
        {QStringLiteral("autoRepairAvailable"),
         guidance.value(QStringLiteral("autoRepairSafe"))},
        {QStringLiteral("actions"),
         QVariantList{
             QVariantMap{{QStringLiteral("key"), QStringLiteral("fix")},
                         {QStringLiteral("label"),
                          guidance.value(QStringLiteral("actionLabel"))}},
             QVariantMap{{QStringLiteral("key"), QStringLiteral("accept_anyway")},
                         {QStringLiteral("label"), QStringLiteral("Keep anyway")}},
             QVariantMap{{QStringLiteral("key"), QStringLiteral("rollback_photo")},
                         {QStringLiteral("label"), QStringLiteral("Revert photo")}},
         }},
    });
    added_asset_ids.append(asset_id);
  }

  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-consistency-exception-routing-v1")},
      {QStringLiteral("reviewIssues"), review_issues},
      {QStringLiteral("addedAssetIds"), added_asset_ids},
      {QStringLiteral("addedIssueCount"), added_asset_ids.size()},
      {QStringLiteral("augmentedAssetIds"), augmented_asset_ids},
      {QStringLiteral("augmentedIssueCount"), augmented_asset_ids.size()},
      {QStringLiteral("manualReviewAssetIds"), manual_review_asset_ids},
      {QStringLiteral("resolvedAssetIds"), resolved_asset_ids},
      {QStringLiteral("allDriftRouted"),
       added_asset_ids.size() + augmented_asset_ids.size() +
               resolved_asset_ids.size() ==
           consistency_map.value(QStringLiteral("driftCount")).toInt()},
      {QStringLiteral("preservesPriorIssueCategory"), true},
      {QStringLiteral("acceptedOrRevertedDriftStaysOutOfQueue"), true},
  };
}

QVariantMap agent_consistency_repair_patch(
    const QVariantMap& source_patch,
    const QVariantMap& repair_guidance) {
  QVariantMap report{
      {QStringLiteral("contract"),
       QStringLiteral("agent-consistency-repair-application-v1")},
      {QStringLiteral("ok"), false},
      {QStringLiteral("applied"), false},
      {QStringLiteral("sourcePatchPreserved"), true},
      {QStringLiteral("allowedGroups"),
       QStringList{QStringLiteral("globalTone"), QStringLiteral("color")}},
      {QStringLiteral("preservedGroups"),
       QStringList{
           QStringLiteral("crop"),
           QStringLiteral("masks"),
           QStringLiteral("retouch"),
           QStringLiteral("geometry"),
           QStringLiteral("detail")}},
      {QStringLiteral("requiresFreshProof"), true},
      {QStringLiteral("recipePatch"), source_patch},
  };
  if (repair_guidance.value(QStringLiteral("contract")).toString() !=
      QStringLiteral("agent-consistency-drift-repair-v1")) {
    report.insert(
        QStringLiteral("failureReason"),
        QStringLiteral("Consistency repair guidance is missing or unsupported."));
    return report;
  }
  if (!repair_guidance.value(QStringLiteral("autoRepairSafe")).toBool()) {
    report.insert(
        QStringLiteral("failureReason"),
        QStringLiteral("Skin-sensitive consistency evidence needs a photographer decision."));
    return report;
  }
  auto repaired_patch = source_patch;
  const auto applied = apply_consistency_recipe_delta(
      &repaired_patch,
      repair_guidance.value(QStringLiteral("recipeDelta")).toMap());
  report.insert(QStringLiteral("ok"), applied);
  report.insert(QStringLiteral("applied"), applied);
  report.insert(QStringLiteral("recipePatch"), repaired_patch);
  if (!applied) {
    report.insert(
        QStringLiteral("failureReason"),
        QStringLiteral("Consistency guidance did not contain a supported bounded correction."));
  }
  return report;
}

QVariantMap agent_exception_review_summary(
    int asset_count,
    int edited_count,
    int passed_count,
    int needs_review_count,
    int failed_count,
    const QVariantList& review_issues) {
  QStringList issue_asset_ids;
  QVariantMap category_counts;
  auto auto_repairable_issue_count = 0;
  auto manual_decision_issue_count = 0;
  for (const auto& issue_value : review_issues) {
    const auto issue = issue_value.toMap();
    const auto asset_id = issue.value(QStringLiteral("assetId")).toString().trimmed();
    if (!asset_id.isEmpty() && !issue_asset_ids.contains(asset_id)) {
      issue_asset_ids.append(asset_id);
    }
    const auto category = issue.value(
        QStringLiteral("category"),
        issue.value(QStringLiteral("status")).toString() == QStringLiteral("failed")
            ? QStringLiteral("failed")
            : QStringLiteral("warning")).toString();
    category_counts.insert(
        category,
        category_counts.value(category).toInt() + 1);
    if (!issue.contains(QStringLiteral("autoRepairAvailable")) ||
        issue.value(QStringLiteral("autoRepairAvailable")).toBool()) {
      ++auto_repairable_issue_count;
    } else {
      ++manual_decision_issue_count;
    }
  }

  const auto exception_count = review_issues.size();
  const auto verified_count = std::clamp(passed_count, 0, std::max(asset_count, 0));
  const auto headline =
      exception_count > 0
          ? QStringLiteral("%1 verified · %2 need%3 review")
                .arg(verified_count)
                .arg(exception_count)
                .arg(exception_count == 1 ? QStringLiteral("s") : QString())
          : QStringLiteral("%1 verified · no exceptions").arg(verified_count);
  return QVariantMap{
      {QStringLiteral("contract"), QStringLiteral("agent-exception-review-v1")},
      {QStringLiteral("totalCount"), std::max(asset_count, 0)},
      {QStringLiteral("editedCount"), edited_count},
      {QStringLiteral("passedCount"), passed_count},
      {QStringLiteral("verifiedCount"), verified_count},
      {QStringLiteral("hiddenVerifiedCount"), verified_count},
      {QStringLiteral("needsReviewCount"), needs_review_count},
      {QStringLiteral("failedCount"), failed_count},
      {QStringLiteral("issueCount"), exception_count},
      {QStringLiteral("exceptionCount"), exception_count},
      {QStringLiteral("reviewWorkItemCount"), exception_count},
      {QStringLiteral("issueAssetIds"), issue_asset_ids},
      {QStringLiteral("queueAssetIds"), issue_asset_ids},
      {QStringLiteral("categoryCounts"), category_counts},
      {QStringLiteral("autoRepairableIssueCount"), auto_repairable_issue_count},
      {QStringLiteral("manualDecisionIssueCount"), manual_decision_issue_count},
      {QStringLiteral("headline"), headline},
      {QStringLiteral("allClear"), exception_count == 0},
      {QStringLiteral("requiresReview"), exception_count > 0},
      {QStringLiteral("commitBlockedByExceptions"), exception_count > 0},
      {QStringLiteral("showOnlyIssuesFirst"), exception_count > 0},
      {QStringLiteral("queueContainsOnlyExceptions"), true},
      {QStringLiteral("detailsCollapsedByDefault"), true},
      {QStringLiteral("workloadScalesWithExceptions"), true},
      {QStringLiteral("reviewWorkloadPolicy"),
       QStringLiteral("one-batch-receipt-plus-exceptions-only")},
      {QStringLiteral("fixAllOutliersAvailable"),
       needs_review_count > 1 && failed_count == 0 &&
           manual_decision_issue_count == 0},
  };
}

AgentEditController::AgentEditController(QObject* parent) : QObject(parent) {
  available_models_ = available_agent_local_models();
  selected_model_id_ = default_agent_local_model_id();
  reloadStyles();
  restoreAgentContinuity();
  refreshMemoryVaultSnapshot();
}

void AgentEditController::setCatalogModel(CatalogAssetModel* catalog_model) {
  if (catalog_model_ == catalog_model) {
    return;
  }
  if (catalog_filters_connection_) {
    QObject::disconnect(catalog_filters_connection_);
  }
  catalog_model_ = catalog_model;
  if (catalog_model_ != nullptr) {
    catalog_filters_connection_ = connect(
        catalog_model_,
        &CatalogAssetModel::filtersChanged,
        this,
        [this]() {
          if (!draftActive() &&
              currentContinuityProjectKey() !=
                  restored_continuity_project_key_) {
            restoreAgentContinuity();
          }
        });
  }
  restoreAgentContinuity();
}

void AgentEditController::setExportJobController(ExportJobController* export_job_controller) {
  export_job_controller_ = export_job_controller;
}

