QVariantMap AgentEditController::photographerCalibrationCoach() const {
  const auto project_key = currentContinuityProjectKey();
  const auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  const auto stored = state.value(QStringLiteral("projects"))
                          .toMap()
                          .value(project_key)
                          .toMap()
                          .value(QStringLiteral("photographerCalibration"))
                          .toMap();
  QVariantMap coach{
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-coach-v1")},
      {QStringLiteral("available"), false},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"),
       project_key != QStringLiteral("__global__")},
      {QStringLiteral("profileAvailable"),
       stored.value(QStringLiteral("contract")).toString() ==
           QStringLiteral("agent-project-photographer-calibration-v1")},
      {QStringLiteral("profileDigestSha256"),
       stored.value(QStringLiteral("profileDigestSha256"))},
      {QStringLiteral("lessonCount"), 0},
      {QStringLiteral("photographerDecisionIsAuthority"), true},
      {QStringLiteral("machineCanRate"), false},
      {QStringLiteral("automaticModelTrainingAllowed"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("requiresFreshCorpusAfterThresholdChange"), true},
      {QStringLiteral("activeDraftAffected"), false},
      {QStringLiteral("durableMemoryWritten"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  if (!coach.value(QStringLiteral("profileAvailable")).toBool() ||
      project_key == QStringLiteral("__global__")) {
    return coach;
  }

  const auto threshold_signals =
      stored.value(QStringLiteral("thresholdSignals")).toMap();
  QStringList false_confidence_concerns;
  QStringList over_conservative_concerns;
  for (auto iterator = threshold_signals.constBegin();
       iterator != threshold_signals.constEnd(); ++iterator) {
    const auto signal = iterator.value().toMap();
    if (signal.value(QStringLiteral("falseConfidenceCount")).toInt() > 0) {
      false_confidence_concerns.append(iterator.key());
    }
    if (signal.value(QStringLiteral("overConservativeCount")).toInt() > 0) {
      over_conservative_concerns.append(iterator.key());
    }
  }
  false_confidence_concerns.sort();
  over_conservative_concerns.sort();

  const auto dimension_keys = photographer_calibration_dimension_keys();
  const auto dimension_labels = photographer_calibration_dimension_labels();
  const auto issue_labels = photographer_calibration_issue_labels();
  QVariantList lessons;
  for (const auto& case_value :
       stored.value(QStringLiteral("cases")).toList()) {
    const auto item = case_value.toMap();
    const auto outcome = item.value(QStringLiteral("outcome")).toString();
    const auto false_confidence =
        outcome == QStringLiteral("false-confidence");
    const auto over_conservative =
        outcome == QStringLiteral("over-conservative");
    if (!false_confidence && !over_conservative) {
      continue;
    }
    const auto dimensions = item.value(QStringLiteral("dimensions")).toMap();
    auto weakest_dimension = QString();
    auto weakest_score = 6;
    for (const auto& key : dimension_keys) {
      const auto score = dimensions.value(key).toInt();
      if (score < weakest_score) {
        weakest_score = score;
        weakest_dimension = key;
      }
    }
    QStringList issue_names;
    for (const auto& issue_value :
         item.value(QStringLiteral("issueTags")).toList()) {
      const auto issue = issue_value.toString();
      const auto label = issue_labels.value(issue).toString();
      if (!label.isEmpty()) {
        issue_names.append(label);
      }
    }
    auto case_kind = item.value(QStringLiteral("caseKind")).toString();
    case_kind.replace(QLatin1Char('_'), QLatin1Char(' '));
    case_kind.replace(QLatin1Char('-'), QLatin1Char(' '));
    const auto human_rating =
        item.value(QStringLiteral("humanRating")).toInt();
    const auto weakest_label =
        dimension_labels.value(weakest_dimension).toString();
    const auto concerns = false_confidence
                              ? false_confidence_concerns
                              : over_conservative_concerns;
    const auto concern_text = concerns.isEmpty()
                                  ? QStringLiteral("this response")
                                  : concerns.join(QStringLiteral(", "));
    const auto explanation =
        false_confidence
            ? QStringLiteral(
                  "You rejected this %1 at %2/5. %3 was the weakest dimension at %4/5%5.")
                  .arg(case_kind, QString::number(human_rating),
                       weakest_label, QString::number(weakest_score),
                       issue_names.isEmpty()
                           ? QString()
                           : QStringLiteral("; you flagged %1")
                                 .arg(issue_names.join(QStringLiteral(", "))))
            : QStringLiteral(
                  "You would deliver this %1 at %2/5 even though my machine gate stopped it. %3 was %4/5.")
                  .arg(case_kind, QString::number(human_rating),
                       weakest_label, QString::number(weakest_score));
    const auto next_move =
        false_confidence
            ? QStringLiteral(
                  "Keep %1 photographer-visible and offer a restrained comparison when it appears. Any threshold change still needs a fresh corpus.")
                  .arg(concern_text)
            : QStringLiteral(
                  "Treat %1 as a possible false stop and collect another blind example before relaxing anything.")
                  .arg(concern_text);
    const auto case_id = item.value(QStringLiteral("caseId")).toString();
    lessons.append(QVariantMap{
        {QStringLiteral("contract"),
         QStringLiteral("agent-photographer-calibration-lesson-v1")},
        {QStringLiteral("lessonId"),
         stable_variant_hash(QVariantMap{
             {QStringLiteral("profileDigestSha256"),
              stored.value(QStringLiteral("profileDigestSha256"))},
             {QStringLiteral("caseId"), case_id},
             {QStringLiteral("outcome"), outcome},
         }).left(16)},
        {QStringLiteral("caseId"), case_id},
        {QStringLiteral("caseKind"),
         item.value(QStringLiteral("caseKind"))},
        {QStringLiteral("outcome"), outcome},
        {QStringLiteral("priority"), false_confidence ? 0 : 1},
        {QStringLiteral("headline"),
         false_confidence
             ? QStringLiteral("I was too confident about this result.")
             : QStringLiteral("I was too cautious about this result.")},
        {QStringLiteral("explanation"), explanation},
        {QStringLiteral("decisionContrast"),
         false_confidence
             ? QStringLiteral("MACHINE PASSED · PHOTOGRAPHER: DO NOT DELIVER")
             : QStringLiteral("MACHINE STOPPED · PHOTOGRAPHER: DELIVER")},
        {QStringLiteral("humanRating"), human_rating},
        {QStringLiteral("weakestDimension"), weakest_dimension},
        {QStringLiteral("weakestDimensionLabel"), weakest_label},
        {QStringLiteral("weakestDimensionScore"), weakest_score},
        {QStringLiteral("issueTags"),
         item.value(QStringLiteral("issueTags"))},
        {QStringLiteral("issueLabels"), issue_names},
        {QStringLiteral("relatedConcernKeys"), concerns},
        {QStringLiteral("nextMove"), next_move},
        {QStringLiteral("signedHumanJudgment"), true},
        {QStringLiteral("automaticActionTaken"), false},
    });
  }
  std::sort(
      lessons.begin(), lessons.end(), [](const QVariant& left_value,
                                         const QVariant& right_value) {
        const auto left = left_value.toMap();
        const auto right = right_value.toMap();
        const auto left_priority = left.value(QStringLiteral("priority")).toInt();
        const auto right_priority =
            right.value(QStringLiteral("priority")).toInt();
        if (left_priority != right_priority) {
          return left_priority < right_priority;
        }
        const auto left_rating =
            left.value(QStringLiteral("humanRating")).toInt();
        const auto right_rating =
            right.value(QStringLiteral("humanRating")).toInt();
        if (left_rating != right_rating) {
          return left_rating < right_rating;
        }
        return left.value(QStringLiteral("caseId")).toString() <
               right.value(QStringLiteral("caseId")).toString();
      });

  const auto outcomes = stored.value(QStringLiteral("outcomes")).toMap();
  const auto false_confidence_count =
      outcomes.value(QStringLiteral("falseConfidence")).toInt();
  const auto over_conservative_count =
      outcomes.value(QStringLiteral("overConservative")).toInt();
  coach.insert(QStringLiteral("available"), !lessons.isEmpty());
  coach.insert(QStringLiteral("lessonCount"), lessons.size());
  coach.insert(QStringLiteral("lessons"), lessons);
  coach.insert(QStringLiteral("primaryLesson"),
               lessons.isEmpty() ? QVariantMap{} : lessons.first().toMap());
  coach.insert(QStringLiteral("falseConfidenceCount"),
               false_confidence_count);
  coach.insert(QStringLiteral("overConservativeCount"),
               over_conservative_count);
  coach.insert(QStringLiteral("headline"),
               QStringLiteral("Here’s where my judgment differed from yours."));
  coach.insert(
      QStringLiteral("summary"),
      QStringLiteral("%1 signed disagreement%2 · %3 too confident · %4 too cautious")
          .arg(lessons.size())
          .arg(lessons.size() == 1 ? QString() : QStringLiteral("s"))
          .arg(false_confidence_count)
          .arg(over_conservative_count));
  auto calibration_concerns =
      false_confidence_concerns + over_conservative_concerns;
  calibration_concerns.removeDuplicates();
  coach.insert(QStringLiteral("calibrationConcernKeys"),
               calibration_concerns);
  return coach;
}

QVariantMap AgentEditController::photographerTasteCheck() const {
  const auto calibration = photographerCalibrationProfile();
  QVariantMap check{
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-taste-check-v1")},
      {QStringLiteral("available"), false},
      {QStringLiteral("recommended"), false},
      {QStringLiteral("projectLocal"), true},
      {QStringLiteral("projectKey"), currentContinuityProjectKey()},
      {QStringLiteral("calibrationAvailable"),
       calibration.value(QStringLiteral("available"))},
      {QStringLiteral("profileDigestSha256"),
       calibration.value(QStringLiteral("profileDigestSha256"))},
      {QStringLiteral("requiresExplicitChoice"), true},
      {QStringLiteral("automaticComparisonStarted"), false},
      {QStringLiteral("durableMemoryWritten"), false},
      {QStringLiteral("choicePromotionPolicy"),
       QStringLiteral("explicit-direction-choice-confirmed-by-commit-only")},
      {QStringLiteral("numericThresholdOverridesAllowed"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
  };
  if (!calibration.value(QStringLiteral("available")).toBool() ||
      !draftActive() || running_ ||
      !draft_direction_comparison_.isEmpty() ||
      draft_project_key_ != currentContinuityProjectKey() ||
      direction_proof_path(last_run_report_).trimmed().isEmpty()) {
    return check;
  }

  const auto prompt_audit =
      last_run_report_.value(QStringLiteral("modelPromptAudit")).toMap();
  const auto adjusted_groups =
      prompt_audit
          .value(QStringLiteral("photographerCalibrationAdjustedGroups"))
          .toStringList();
  const auto concern_keys =
      calibration.value(QStringLiteral("validationConcernKeys"))
          .toStringList();
  const auto intent_text =
      QStringLiteral("%1 %2 %3")
          .arg(user_instructions_,
               last_run_report_.value(QStringLiteral("planSummary")).toString(),
               QString::fromUtf8(
                   QJsonDocument::fromVariant(
                       last_run_report_.value(QStringLiteral("editIntent")))
                       .toJson(QJsonDocument::Compact)))
          .toLower();
  const auto mentions_any = [&intent_text](const QStringList& words) {
    for (const auto& word : words) {
      if (intent_text.contains(word)) {
        return true;
      }
    }
    return false;
  };
  const auto concern_group = [](const QString& concern) {
    if (concern == QStringLiteral("brightness")) {
      return QStringLiteral("brightness");
    }
    if (concern == QStringLiteral("contrast") ||
        concern == QStringLiteral("preserveContrast")) {
      return QStringLiteral("contrast");
    }
    if (concern == QStringLiteral("warmth")) {
      return QStringLiteral("warmth");
    }
    if (concern == QStringLiteral("saturation") ||
        concern == QStringLiteral("preserveSaturation") ||
        concern == QStringLiteral("monochromeSaturationLimit")) {
      return QStringLiteral("saturation");
    }
    return QString{};
  };
  const auto intent_mentions_group = [&mentions_any](const QString& group) {
    if (group == QStringLiteral("brightness")) {
      return mentions_any({QStringLiteral("bright"),
                           QStringLiteral("dark"),
                           QStringLiteral("exposure"),
                           QStringLiteral("highlight"),
                           QStringLiteral("shadow"),
                           QStringLiteral("luminous")});
    }
    if (group == QStringLiteral("contrast")) {
      return mentions_any({QStringLiteral("contrast"),
                           QStringLiteral("flat"),
                           QStringLiteral("punch"),
                           QStringLiteral("soft")});
    }
    if (group == QStringLiteral("warmth")) {
      return mentions_any({QStringLiteral("warm"),
                           QStringLiteral("cool"),
                           QStringLiteral("temperature"),
                           QStringLiteral("white balance"),
                           QStringLiteral("golden"),
                           QStringLiteral("amber")});
    }
    if (group == QStringLiteral("saturation")) {
      return mentions_any({QStringLiteral("saturat"),
                           QStringLiteral("vibran"),
                           QStringLiteral("colorful"),
                           QStringLiteral("muted"),
                           QStringLiteral("monochrome")});
    }
    return false;
  };

  QStringList active_groups;
  QStringList active_concerns;
  for (const auto& concern : concern_keys) {
    const auto group = concern_group(concern);
    if (group.isEmpty() ||
        (!adjusted_groups.contains(group) &&
         !intent_mentions_group(group))) {
      continue;
    }
    if (!active_groups.contains(group)) {
      active_groups.append(group);
    }
    active_concerns.append(concern);
  }
  if (active_groups.isEmpty()) {
    return check;
  }

  const auto primary_group = active_groups.first();
  const QVariantMap group_labels{
      {QStringLiteral("brightness"), QStringLiteral("brightness")},
      {QStringLiteral("contrast"), QStringLiteral("contrast")},
      {QStringLiteral("warmth"), QStringLiteral("warmth")},
      {QStringLiteral("saturation"), QStringLiteral("color intensity")},
  };
  const QVariantMap alternatives{
      {QStringLiteral("brightness"),
       QStringLiteral(
           "Keep the same intent and protected areas, but create a more restrained brightness direction with gentler exposure and highlight movement. Preserve color, contrast, saturation, framing, masks, and retouch.")},
      {QStringLiteral("contrast"),
       QStringLiteral(
           "Keep the same intent and protected areas, but create a more restrained contrast direction with softer tonal separation. Preserve brightness, color, saturation, framing, masks, and retouch.")},
      {QStringLiteral("warmth"),
       QStringLiteral(
           "Keep the same intent and protected areas, but create a more restrained, natural warmth direction. Preserve brightness, contrast, saturation, framing, masks, and retouch.")},
      {QStringLiteral("saturation"),
       QStringLiteral(
           "Keep the same intent and protected areas, but create a more restrained color-intensity direction with natural saturation. Preserve brightness, contrast, white balance, framing, masks, and retouch.")},
  };
  const auto label = group_labels.value(primary_group).toString();
  check.insert(QStringLiteral("available"), true);
  check.insert(QStringLiteral("recommended"), true);
  check.insert(QStringLiteral("sourceRunId"), draft_run_id_);
  check.insert(QStringLiteral("trigger"),
               QStringLiteral("calibration-sensitive-draft"));
  check.insert(QStringLiteral("primaryConcernGroup"), primary_group);
  check.insert(QStringLiteral("activeConcernGroups"), active_groups);
  check.insert(QStringLiteral("activeConcernKeys"), active_concerns);
  check.insert(QStringLiteral("calibrationAdjustedGroups"), adjusted_groups);
  check.insert(QStringLiteral("weakestDimension"),
               calibration.value(QStringLiteral("weakestDimension")));
  check.insert(QStringLiteral("headline"),
               QStringLiteral("I’m less certain about %1 here.").arg(label));
  check.insert(
      QStringLiteral("explanation"),
      QStringLiteral(
          "Your blind ratings marked %1 as calibration-sensitive. I can render a more restrained version before you decide.")
          .arg(label));
  check.insert(QStringLiteral("alternativeDirection"),
               alternatives.value(primary_group));
  check.insert(QStringLiteral("currentDirectionLabel"),
               QStringLiteral("Current direction"));
  check.insert(QStringLiteral("alternativeDirectionLabel"),
               QStringLiteral("More restrained"));
  check.insert(QStringLiteral("actualRenderedCurrentDirection"), true);
  check.insert(QStringLiteral("storesImageBytes"), false);
  check.insert(QStringLiteral("storesSourcePaths"), false);
  return check;
}

QVariantMap AgentEditController::importPhotographerCalibrationProfile(
    const QString& profile_json) {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("import-photographer-calibration")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-import-v1")},
      {QStringLiteral("projectKey"), currentContinuityProjectKey()},
      {QStringLiteral("projectLocal"),
       currentContinuityProjectKey() != QStringLiteral("__global__")},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("numericThresholdOverridesAllowed"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  if (currentContinuityProjectKey() == QStringLiteral("__global__")) {
    const auto error = QStringLiteral(
        "Choose a project before importing photographer calibration.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  QJsonParseError parse_error;
  const auto document =
      QJsonDocument::fromJson(profile_json.toUtf8(), &parse_error);
  if (parse_error.error != QJsonParseError::NoError || !document.isObject()) {
    const auto error = QStringLiteral(
                           "Calibration profile is invalid JSON: %1")
                           .arg(parse_error.errorString());
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  QStringList errors;
  const auto compact = compact_photographer_calibration_profile(
      document.object().toVariantMap(), &errors);
  if (compact.isEmpty() || !errors.isEmpty()) {
    report.insert(QStringLiteral("errors"), errors);
    report.insert(
        QStringLiteral("failureReason"),
        errors.isEmpty()
            ? QStringLiteral("Calibration profile could not be verified.")
            : errors.join(QStringLiteral("; ")));
    return report;
  }

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  if (!state.value(QStringLiteral("ok")).toBool()) {
    state = QVariantMap{
        {QStringLiteral("version"), 1},
        {QStringLiteral("projects"), QVariantMap{}},
    };
  }
  const auto project_key = currentContinuityProjectKey();
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  entry.insert(QStringLiteral("projectKey"), project_key);
  entry.insert(QStringLiteral("photographerCalibration"), compact);
  entry.insert(
      QStringLiteral("tasteUpdatedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(
        QStringLiteral("failureReason"),
        write_report.value(QStringLiteral("errors"))
            .toStringList()
            .join(QStringLiteral("; ")));
    return report;
  }
  const auto card = photographer_calibration_card(compact);
  auto memory_event = user_visible_memory_event(
      QStringLiteral("photographer_calibration_imported"),
      selected_style_id_,
      selectedStyle().value(QStringLiteral("name")).toString(),
      QStringLiteral("Photographer calibration active"),
      card.value(QStringLiteral("summary")).toString(),
      QVariantMap{
          {QStringLiteral("profileDigestSha256"),
           compact.value(QStringLiteral("profileDigestSha256"))},
          {QStringLiteral("caseCount"),
           compact.value(QStringLiteral("caseCount"))},
      });
  memory_event.insert(QStringLiteral("requiresUserVisibility"), true);
  memory_event.insert(QStringLiteral("memoryWriteApproved"), true);
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("imported"), true);
  report.insert(QStringLiteral("profile"), card);
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.insert(
      QStringLiteral("userVisibleMemoryEvents"),
      QVariantList{memory_event});
  emit projectTasteChanged();
  return report;
}

QVariantMap AgentEditController::importPhotographerCalibrationProfileFile(
    const QString& path_or_url) {
  const auto source = path_or_url.trimmed();
  QUrl url(source);
  auto path = url.isLocalFile() ? url.toLocalFile() : source;
  if (path.isEmpty()) {
    return result_map(
        false,
        {QStringLiteral("Choose one photographer calibration JSON file.")});
  }
  QFile file(path);
  if (!file.open(QIODevice::ReadOnly)) {
    return result_map(
        false,
        {QStringLiteral("Unable to read photographer calibration: %1")
             .arg(QFileInfo(path).fileName())});
  }
  if (file.size() > 8 * 1024 * 1024) {
    return result_map(
        false,
        {QStringLiteral(
            "Photographer calibration exceeds the 8 MB local import limit.")});
  }
  return importPhotographerCalibrationProfile(
      QString::fromUtf8(file.readAll()));
}

QVariantMap AgentEditController::exportPhotographerTastePassportFile(
    const QString& path_or_url) const {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("export-photographer-taste-passport")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-taste-passport-export-v1")},
      {QStringLiteral("explicitUserAction"), true},
      {QStringLiteral("projectLocalSource"), true},
      {QStringLiteral("targetProjectUnaffected"), true},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
      {QStringLiteral("automaticModelTrainingAllowed"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
  };
  const auto project_key = currentContinuityProjectKey();
  if (project_key == QStringLiteral("__global__")) {
    const auto error =
        QStringLiteral("Choose a project before exporting its Taste Passport.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  const auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  const auto stored = state.value(QStringLiteral("projects"))
                          .toMap()
                          .value(project_key)
                          .toMap()
                          .value(QStringLiteral("photographerCalibration"))
                          .toMap();
  if (stored.value(QStringLiteral("contract")).toString() !=
      QStringLiteral("agent-project-photographer-calibration-v1")) {
    const auto error = QStringLiteral(
        "Finish or import photographer calibration before exporting a Taste Passport.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  if (calibration_payload_contains_private_data(stored) ||
      stored.value(QStringLiteral("storesImageBytes")).toBool() ||
      stored.value(QStringLiteral("storesSourcePaths")).toBool()) {
    const auto error = QStringLiteral(
        "Taste Passport export refused calibration containing private data.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }

  const auto source = path_or_url.trimmed();
  const QUrl url(source);
  auto path = url.isLocalFile() ? url.toLocalFile() : source;
  if (path.isEmpty()) {
    const auto error = QStringLiteral("Choose where to save the Taste Passport.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  if (QFileInfo(path).suffix().isEmpty()) {
    path.append(QStringLiteral(".json"));
  }
  const auto parent_path = QFileInfo(path).absolutePath();
  if (!QDir(parent_path).exists() &&
      !QDir().mkpath(parent_path)) {
    const auto error = QStringLiteral(
        "Unable to create the Taste Passport destination folder.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }

  const auto portable_profile_digest = stable_variant_hash(stored);
  QVariantMap passport{
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-taste-passport-v1")},
      {QStringLiteral("version"), 1},
      {QStringLiteral("createdAtUtc"),
       QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)},
      {QStringLiteral("localOnly"), true},
      {QStringLiteral("explicitImportRequired"), true},
      {QStringLiteral("targetProjectOnly"), true},
      {QStringLiteral("sourceProjectFingerprintSha256"),
       stable_variant_hash(project_key)},
      {QStringLiteral("sourceProfileDigestSha256"),
       stored.value(QStringLiteral("profileDigestSha256"))},
      {QStringLiteral("portableProfileDigestSha256"),
       portable_profile_digest},
      {QStringLiteral("calibrationProfile"), stored},
      {QStringLiteral("containsProjectName"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
      {QStringLiteral("automaticModelTrainingAllowed"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
  };
  passport.insert(
      QStringLiteral("passportDigestSha256"), stable_variant_hash(passport));
  QSaveFile file(path);
  if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)) {
    const auto error = QStringLiteral("Unable to save Taste Passport: %1")
                           .arg(file.errorString());
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  const auto bytes = QJsonDocument::fromVariant(passport)
                         .toJson(QJsonDocument::Indented);
  if (file.write(bytes) != bytes.size() || !file.commit()) {
    const auto error = QStringLiteral("Unable to finish saving Taste Passport: %1")
                           .arg(file.errorString());
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("exported"), true);
  report.insert(QStringLiteral("fileName"), QFileInfo(path).fileName());
  report.insert(
      QStringLiteral("passportDigestSha256"),
      passport.value(QStringLiteral("passportDigestSha256")));
  report.insert(
      QStringLiteral("portableProfileDigestSha256"),
      portable_profile_digest);
  report.insert(
      QStringLiteral("caseCount"),
      stored.value(QStringLiteral("caseCount")));
  return report;
}

QVariantMap AgentEditController::inspectPhotographerTastePassportFile(
    const QString& path_or_url) const {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("inspect-photographer-taste-passport")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-taste-passport-preview-v1")},
      {QStringLiteral("confirmationRequired"), true},
      {QStringLiteral("durableMemoryWritten"), false},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("targetProjectOnly"), true},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
      {QStringLiteral("automaticModelTrainingAllowed"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
  };
  const auto fail_preview = [&report](const QString& error) {
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  };
  if (currentContinuityProjectKey() == QStringLiteral("__global__")) {
    return fail_preview(
        QStringLiteral("Choose a project before previewing a Taste Passport."));
  }
  const auto source = path_or_url.trimmed();
  const QUrl url(source);
  const auto path = url.isLocalFile() ? url.toLocalFile() : source;
  if (path.isEmpty()) {
    return fail_preview(QStringLiteral("Choose one Taste Passport JSON file."));
  }
  QFile file(path);
  if (!file.open(QIODevice::ReadOnly)) {
    return fail_preview(
        QStringLiteral("Unable to read Taste Passport: %1")
            .arg(QFileInfo(path).fileName()));
  }
  if (file.size() > 8 * 1024 * 1024) {
    return fail_preview(
        QStringLiteral("Taste Passport exceeds the 8 MB local import limit."));
  }
  QJsonParseError parse_error;
  const auto document = QJsonDocument::fromJson(file.readAll(), &parse_error);
  if (parse_error.error != QJsonParseError::NoError || !document.isObject()) {
    return fail_preview(
        QStringLiteral("Taste Passport is invalid JSON: %1")
            .arg(parse_error.errorString()));
  }
  QVariantMap verified_passport;
  QStringList errors;
  const auto compact = verified_photographer_taste_passport_profile(
      document.object().toVariantMap(), &verified_passport, &errors);
  if (compact.isEmpty() || !errors.isEmpty()) {
    return fail_preview(
        errors.isEmpty()
            ? QStringLiteral("Taste Passport could not be verified.")
            : errors.join(QStringLiteral("; ")));
  }
  const auto card = photographer_calibration_card(compact);
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("verified"), true);
  report.insert(QStringLiteral("fileName"), QFileInfo(path).fileName());
  report.insert(
      QStringLiteral("passportDigestSha256"),
      verified_passport.value(QStringLiteral("passportDigestSha256")));
  report.insert(
      QStringLiteral("sourceProfileDigestSha256"),
      verified_passport.value(QStringLiteral("sourceProfileDigestSha256")));
  report.insert(QStringLiteral("profile"), card);
  report.insert(QStringLiteral("caseCount"), card.value(QStringLiteral("caseCount")));
  report.insert(QStringLiteral("reviewer"), card.value(QStringLiteral("reviewer")));
  report.insert(QStringLiteral("summary"), card.value(QStringLiteral("summary")));
  report.insert(
      QStringLiteral("wouldReplaceExisting"),
      photographerCalibrationProfile().value(QStringLiteral("available")).toBool());
  return report;
}

QVariantMap AgentEditController::importPhotographerTastePassportFile(
    const QString& path_or_url,
    const QString& expected_passport_digest) {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("import-photographer-taste-passport")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-taste-passport-import-v1")},
      {QStringLiteral("explicitUserAction"), true},
      {QStringLiteral("targetProjectOnly"), true},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
      {QStringLiteral("automaticModelTrainingAllowed"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
  };
  const auto fail_import = [&report](const QString& error) {
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  };
  const auto project_key = currentContinuityProjectKey();
  report.insert(QStringLiteral("projectKey"), project_key);
  if (project_key == QStringLiteral("__global__")) {
    return fail_import(
        QStringLiteral("Choose a project before importing a Taste Passport."));
  }
  const auto source = path_or_url.trimmed();
  const QUrl url(source);
  const auto path = url.isLocalFile() ? url.toLocalFile() : source;
  if (path.isEmpty()) {
    return fail_import(QStringLiteral("Choose one Taste Passport JSON file."));
  }
  QFile file(path);
  if (!file.open(QIODevice::ReadOnly)) {
    return fail_import(
        QStringLiteral("Unable to read Taste Passport: %1")
            .arg(QFileInfo(path).fileName()));
  }
  if (file.size() > 8 * 1024 * 1024) {
    return fail_import(
        QStringLiteral("Taste Passport exceeds the 8 MB local import limit."));
  }
  QJsonParseError parse_error;
  const auto document = QJsonDocument::fromJson(file.readAll(), &parse_error);
  if (parse_error.error != QJsonParseError::NoError || !document.isObject()) {
    return fail_import(
        QStringLiteral("Taste Passport is invalid JSON: %1")
            .arg(parse_error.errorString()));
  }
  QVariantMap passport;
  QStringList profile_errors;
  auto compact = verified_photographer_taste_passport_profile(
      document.object().toVariantMap(), &passport, &profile_errors);
  if (compact.isEmpty() || !profile_errors.isEmpty()) {
    return fail_import(
        profile_errors.isEmpty()
            ? QStringLiteral("Taste Passport calibration could not be verified.")
            : profile_errors.join(QStringLiteral("; ")));
  }
  const auto passport_digest =
      passport.value(QStringLiteral("passportDigestSha256"))
          .toString()
          .trimmed()
          .toLower();
  const auto expected_digest = expected_passport_digest.trimmed().toLower();
  report.insert(QStringLiteral("expectedPassportDigestSha256"), expected_digest);
  report.insert(QStringLiteral("previewDigestPinned"), !expected_digest.isEmpty());
  if (!expected_digest.isEmpty() && expected_digest != passport_digest) {
    return fail_import(
        QStringLiteral(
            "Taste Passport changed after preview; review it again before importing."));
  }
  compact.insert(
      QStringLiteral("tastePassportImportedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  if (!state.value(QStringLiteral("ok")).toBool()) {
    state = QVariantMap{
        {QStringLiteral("version"), 1},
        {QStringLiteral("projects"), QVariantMap{}},
    };
  }
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  entry.insert(QStringLiteral("projectKey"), project_key);
  entry.insert(QStringLiteral("photographerCalibration"), compact);
  entry.insert(
      QStringLiteral("tasteUpdatedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    return fail_import(
        write_report.value(QStringLiteral("errors"))
            .toStringList()
            .join(QStringLiteral("; ")));
  }
  const auto card = photographer_calibration_card(compact);
  auto memory_event = user_visible_memory_event(
      QStringLiteral("photographer_taste_passport_imported"),
      selected_style_id_,
      selectedStyle().value(QStringLiteral("name")).toString(),
      QStringLiteral("Taste Passport active"),
      QStringLiteral("%1 · explicitly imported for this project only")
          .arg(card.value(QStringLiteral("summary")).toString()),
      QVariantMap{
          {QStringLiteral("passportDigestSha256"), passport_digest},
          {QStringLiteral("sourceProfileDigestSha256"),
           passport.value(QStringLiteral("sourceProfileDigestSha256"))},
          {QStringLiteral("caseCount"), compact.value(QStringLiteral("caseCount"))},
      });
  memory_event.insert(QStringLiteral("requiresUserVisibility"), true);
  memory_event.insert(QStringLiteral("memoryWriteApproved"), true);
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("imported"), true);
  report.insert(QStringLiteral("profile"), card);
  report.insert(QStringLiteral("passportDigestSha256"), passport_digest);
  report.insert(
      QStringLiteral("sourceProfileDigestSha256"),
      passport.value(QStringLiteral("sourceProfileDigestSha256")));
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.insert(
      QStringLiteral("userVisibleMemoryEvents"), QVariantList{memory_event});
  emit projectTasteChanged();
  return report;
}

QVariantMap AgentEditController::openPhotographerCalibrationReviewPacketFile(
    const QString& path_or_url,
    bool dry_run) const {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("open-photographer-calibration-review")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-review-launch-v1")},
      {QStringLiteral("dryRun"), dry_run},
      {QStringLiteral("opened"), false},
      {QStringLiteral("validated"), false},
      {QStringLiteral("requiresPhotographerJudgment"), true},
      {QStringLiteral("machineCanCompleteRatings"), false},
      {QStringLiteral("ratingsImported"), false},
      {QStringLiteral("durableMemoryWritten"), false},
      {QStringLiteral("storesSourcePaths"), false},
      {QStringLiteral("storesImageBytes"), false},
  };
  const auto fail_review = [&report](const QString& error) {
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  };

  const auto source = path_or_url.trimmed();
  const QUrl url(source);
  auto selected_path = url.isLocalFile() ? url.toLocalFile() : source;
  if (selected_path.isEmpty()) {
    return fail_review(QStringLiteral(
        "Choose index.html or review-contract.json from one calibration packet."));
  }

  QFileInfo selected_info(selected_path);
  if (selected_info.isDir()) {
    selected_info = QFileInfo(
        QDir(selected_info.absoluteFilePath()).filePath(QStringLiteral("index.html")));
  }
  const auto selected_name = selected_info.fileName().toLower();
  if (selected_name != QStringLiteral("index.html") &&
      selected_name != QStringLiteral("review-contract.json")) {
    return fail_review(QStringLiteral(
        "Choose index.html or review-contract.json from one calibration packet."));
  }
  const auto packet_directory = selected_info.absoluteDir();
  const auto page_path = packet_directory.filePath(QStringLiteral("index.html"));
  const auto contract_path =
      packet_directory.filePath(QStringLiteral("review-contract.json"));
  report.insert(QStringLiteral("selectedFileName"), selected_info.fileName());

  QFile contract_file(contract_path);
  if (!contract_file.open(QIODevice::ReadOnly) ||
      contract_file.size() <= 0 || contract_file.size() > 8 * 1024 * 1024) {
    return fail_review(QStringLiteral(
        "The calibration review contract is missing, empty, or too large."));
  }
  QJsonParseError parse_error;
  const auto contract_document =
      QJsonDocument::fromJson(contract_file.readAll(), &parse_error);
  if (parse_error.error != QJsonParseError::NoError ||
      !contract_document.isObject()) {
    return fail_review(QStringLiteral(
        "The calibration review contract is not valid JSON."));
  }
  const auto contract = contract_document.object().toVariantMap();
  const auto packet_digest =
      contract.value(QStringLiteral("packetDigestSha256")).toString();
  auto digest_payload = contract;
  digest_payload.remove(QStringLiteral("packetDigestSha256"));
  const auto cases = contract.value(QStringLiteral("cases")).toList();
  if (contract.value(QStringLiteral("contract")).toString() !=
          QStringLiteral("agent-human-review-packet-v2") ||
      contract.value(QStringLiteral("reviewExperienceContract")).toString() !=
          QStringLiteral("agent-blind-light-table-v1") ||
      !contract.value(QStringLiteral("humanDecisionRequired")).toBool() ||
      !contract.value(QStringLiteral("machineResultCannotSetHumanRating")).toBool() ||
      !contract.value(QStringLiteral("blindReviewRequired")).toBool() ||
      contract.value(QStringLiteral("machineEvidenceEmbeddedInReviewPage"), true)
          .toBool() ||
      contract.value(QStringLiteral("sourcePathsEmbeddedInReviewPage"), true)
          .toBool() ||
      !contract.value(QStringLiteral("localDraftAutosave")).toBool() ||
      contract.value(QStringLiteral("localDraftContainsProofPixels"), true)
          .toBool() ||
      !contract.value(QStringLiteral("directBeforeAfterComparison")).toBool() ||
      !valid_sha256_hex(packet_digest) ||
      stable_variant_hash(digest_payload) != packet_digest ||
      cases.isEmpty() || cases.size() > 256 ||
      contract.value(QStringLiteral("manifestCaseCount")).toInt() != cases.size() ||
      contract.value(QStringLiteral("reportCaseCount")).toInt() != cases.size()) {
    return fail_review(QStringLiteral(
        "The calibration packet contract or digest could not be verified."));
  }

  const auto canonical_packet_root =
      QFileInfo(contract_path).absoluteDir().canonicalPath();
  if (canonical_packet_root.isEmpty()) {
    return fail_review(QStringLiteral(
        "The calibration packet directory could not be verified."));
  }
  const auto canonical_page_path = QFileInfo(page_path).canonicalFilePath();
  if (canonical_page_path.isEmpty() ||
      !canonical_page_path.startsWith(
          canonical_packet_root + QDir::separator())) {
    return fail_review(QStringLiteral(
        "The blind calibration review page must stay inside its packet."));
  }
  const auto file_sha256 = [](const QString& path) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
      return QString{};
    }
    QCryptographicHash hash(QCryptographicHash::Sha256);
    while (!file.atEnd()) {
      const auto chunk = file.read(1024 * 1024);
      if (chunk.isEmpty() && file.error() != QFileDevice::NoError) {
        return QString{};
      }
      hash.addData(chunk);
    }
    return QString::fromLatin1(hash.result().toHex());
  };
  for (const auto& case_value : cases) {
    const auto review_case = case_value.toMap();
    if (review_case.value(QStringLiteral("caseId")).toString().trimmed().isEmpty()) {
      return fail_review(QStringLiteral(
          "A calibration case is missing its stable identity."));
    }
    const std::array<std::pair<QString, QString>, 2> proofs{{
        {QStringLiteral("beforeProof"), QStringLiteral("beforeProofSha256")},
        {QStringLiteral("afterProof"), QStringLiteral("afterProofSha256")},
    }};
    for (const auto& [path_key, digest_key] : proofs) {
      const auto relative_path = review_case.value(path_key).toString();
      const auto expected_digest = review_case.value(digest_key).toString();
      if (relative_path.trimmed().isEmpty() ||
          QDir::isAbsolutePath(relative_path) ||
          QDir::cleanPath(relative_path).startsWith(QStringLiteral("..")) ||
          !valid_sha256_hex(expected_digest)) {
        return fail_review(QStringLiteral(
            "A calibration proof path or digest is unsafe."));
      }
      const QFileInfo proof_info(packet_directory.filePath(relative_path));
      const auto canonical_proof = proof_info.canonicalFilePath();
      if (!proof_info.isFile() || canonical_proof.isEmpty() ||
          (!canonical_proof.startsWith(canonical_packet_root + QDir::separator()) &&
           canonical_proof != canonical_packet_root) ||
          file_sha256(canonical_proof) != expected_digest) {
        return fail_review(QStringLiteral(
            "A calibration proof is missing, outside the packet, or altered."));
      }
    }
  }

  QFile page_file(canonical_page_path);
  if (!page_file.open(QIODevice::ReadOnly) ||
      page_file.size() <= 0 || page_file.size() > 32 * 1024 * 1024) {
    return fail_review(QStringLiteral(
        "The blind calibration review page is missing, empty, or too large."));
  }
  const auto page_bytes = page_file.readAll();
  const auto source_manifest =
      contract.value(QStringLiteral("sourceManifest")).toString().toUtf8();
  const auto source_report =
      contract.value(QStringLiteral("sourceMachineReport")).toString().toUtf8();
  if (!page_bytes.contains("agent-blind-light-table-v1") ||
      !page_bytes.contains(packet_digest.toUtf8()) ||
      page_bytes.contains("\"machinePass\"") ||
      page_bytes.contains("\"machineFailures\"") ||
      (!source_manifest.isEmpty() && page_bytes.contains(source_manifest)) ||
      (!source_report.isEmpty() && page_bytes.contains(source_report))) {
    return fail_review(QStringLiteral(
        "The review page is stale or exposes hidden machine evidence."));
  }

  report.insert(QStringLiteral("validated"), true);
  report.insert(QStringLiteral("openReady"), true);
  report.insert(QStringLiteral("packetDigestSha256"), packet_digest);
  report.insert(QStringLiteral("caseCount"), cases.size());
  report.insert(QStringLiteral("reviewExperienceContract"),
                QStringLiteral("agent-blind-light-table-v1"));
  report.insert(QStringLiteral("machineEvidenceHidden"), true);
  report.insert(QStringLiteral("sourcePathsHidden"), true);
  report.insert(QStringLiteral("proofHashesVerified"), cases.size() * 2);
  if (dry_run) {
    report.insert(QStringLiteral("ok"), true);
    return report;
  }
  const auto opened =
      QDesktopServices::openUrl(QUrl::fromLocalFile(canonical_page_path));
  report.insert(QStringLiteral("opened"), opened);
  report.insert(QStringLiteral("ok"), opened);
  if (!opened) {
    report.insert(QStringLiteral("failureReason"),
                  QStringLiteral("The verified calibration review could not be opened."));
    report.insert(QStringLiteral("errors"),
                  QStringList{report.value(QStringLiteral("failureReason")).toString()});
  }
  return report;
}

QVariantMap AgentEditController::finalizePhotographerCalibrationReviewFiles(
    const QString& ratings_path_or_url,
    const QString& packet_path_or_url) {
  const auto source_to_path = [](const QString& source) {
    const QUrl url(source.trimmed());
    return url.isLocalFile() ? url.toLocalFile() : source.trimmed();
  };
  QFile ratings_file(source_to_path(ratings_path_or_url));
  if (!ratings_file.open(QIODevice::ReadOnly) ||
      ratings_file.size() <= 0 || ratings_file.size() > 8 * 1024 * 1024) {
    return QVariantMap{
        {QStringLiteral("ok"), false},
        {QStringLiteral("mode"),
         QStringLiteral("finalize-photographer-calibration-review")},
        {QStringLiteral("contract"),
         QStringLiteral("agent-photographer-calibration-native-finalize-v1")},
        {QStringLiteral("requiresHumanRatings"), true},
        {QStringLiteral("machineCanCompleteRatings"), false},
        {QStringLiteral("failureReason"),
         QStringLiteral(
             "The exported photographer ratings are missing, empty, or too large.")},
        {QStringLiteral("errors"),
         QStringList{QStringLiteral(
             "The exported photographer ratings are missing, empty, or too large.")}},
    };
  }
  return finalizePhotographerCalibrationReviewPayload(
      ratings_file.readAll(), packet_path_or_url);
}

QVariantMap AgentEditController::finalizePhotographerCalibrationReviewClipboard(
    const QString& packet_path_or_url) {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("finalize-photographer-calibration-review-clipboard")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-clipboard-handoff-v1")},
      {QStringLiteral("requiresHumanRatings"), true},
      {QStringLiteral("machineCanCompleteRatings"), false},
      {QStringLiteral("ratingsFileRequired"), false},
      {QStringLiteral("clipboardCleared"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  const auto fail_clipboard = [&report](const QString& error) {
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  };
  if (qobject_cast<QGuiApplication*>(QCoreApplication::instance()) == nullptr) {
    return fail_clipboard(QStringLiteral(
        "The clipboard is unavailable in this app session."));
  }
  auto* clipboard = QGuiApplication::clipboard();
  if (clipboard == nullptr) {
    return fail_clipboard(QStringLiteral(
        "The clipboard is unavailable in this app session."));
  }
  const auto ratings_bytes = clipboard->text().toUtf8();
  if (ratings_bytes.isEmpty() || ratings_bytes.size() > 8 * 1024 * 1024) {
    return fail_clipboard(QStringLiteral(
        "Copy the completed signed calibration from the review page first."));
  }
  auto finalized = finalizePhotographerCalibrationReviewPayload(
      ratings_bytes, packet_path_or_url);
  finalized.insert(QStringLiteral("handoffContract"),
                   QStringLiteral(
                       "agent-photographer-calibration-clipboard-handoff-v1"));
  finalized.insert(QStringLiteral("ratingsFileRequired"), false);
  finalized.insert(QStringLiteral("clipboardPayloadRetained"),
                   !finalized.value(QStringLiteral("ok")).toBool());
  if (finalized.value(QStringLiteral("ok")).toBool()) {
    clipboard->clear();
    finalized.insert(QStringLiteral("clipboardCleared"), true);
  } else {
    finalized.insert(QStringLiteral("clipboardCleared"), false);
  }
  return finalized;
}

QVariantMap AgentEditController::finalizePhotographerCalibrationReviewPayload(
    const QByteArray& ratings_bytes,
    const QString& packet_path_or_url) {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("finalize-photographer-calibration-review")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-native-finalize-v1")},
      {QStringLiteral("projectKey"), currentContinuityProjectKey()},
      {QStringLiteral("projectLocal"),
       currentContinuityProjectKey() != QStringLiteral("__global__")},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("requiresHumanRatings"), true},
      {QStringLiteral("machineCanCompleteRatings"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("professionalReadinessClaimed"), false},
      {QStringLiteral("sourceManifestOverwritten"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  const auto fail_finalize = [&report](const QString& error) {
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  };
  if (currentContinuityProjectKey() == QStringLiteral("__global__")) {
    return fail_finalize(QStringLiteral(
        "Choose a project before finalizing photographer calibration."));
  }

  const auto packet_ready = openPhotographerCalibrationReviewPacketFile(
      packet_path_or_url, true);
  if (!packet_ready.value(QStringLiteral("ok")).toBool()) {
    return fail_finalize(
        packet_ready.value(QStringLiteral("failureReason")).toString());
  }
  const auto source_to_path = [](const QString& source) {
    const QUrl url(source.trimmed());
    return url.isLocalFile() ? url.toLocalFile() : source.trimmed();
  };
  auto packet_selection = QFileInfo(source_to_path(packet_path_or_url));
  if (packet_selection.isDir()) {
    packet_selection = QFileInfo(
        QDir(packet_selection.absoluteFilePath())
            .filePath(QStringLiteral("review-contract.json")));
  }
  const auto packet_directory = packet_selection.absoluteDir();
  const auto packet_contract_path =
      packet_directory.filePath(QStringLiteral("review-contract.json"));
  QFile packet_file(packet_contract_path);
  if (!packet_file.open(QIODevice::ReadOnly)) {
    return fail_finalize(QStringLiteral(
        "The verified calibration contract could not be read again."));
  }
  const auto packet =
      QJsonDocument::fromJson(packet_file.readAll()).object().toVariantMap();
  const auto packet_digest =
      packet.value(QStringLiteral("packetDigestSha256")).toString();
  const auto packet_cases = packet.value(QStringLiteral("cases")).toList();
  QMap<QString, QVariantMap> packet_by_id;
  QStringList case_order;
  for (const auto& value : packet_cases) {
    const auto item = value.toMap();
    const auto case_id = item.value(QStringLiteral("caseId")).toString();
    if (case_id.isEmpty() || packet_by_id.contains(case_id)) {
      return fail_finalize(QStringLiteral(
          "The verified packet contains an invalid case identity."));
    }
    packet_by_id.insert(case_id, item);
    case_order.append(case_id);
  }

  QJsonParseError ratings_parse_error;
  const auto ratings_document =
      QJsonDocument::fromJson(ratings_bytes, &ratings_parse_error);
  if (ratings_parse_error.error != QJsonParseError::NoError ||
      !ratings_document.isObject()) {
    return fail_finalize(QStringLiteral(
        "The exported photographer ratings are not valid JSON."));
  }
  const auto ratings = ratings_document.object().toVariantMap();
  const auto reviewer =
      ratings.value(QStringLiteral("reviewer")).toString().simplified();
  const auto reviewed_at =
      ratings.value(QStringLiteral("reviewedAt")).toString().trimmed();
  const auto ratings_cases = ratings.value(QStringLiteral("cases")).toMap();
  const QSet<QString> rating_case_ids(
      ratings_cases.keyBegin(), ratings_cases.keyEnd());
  const QSet<QString> packet_case_ids(
      packet_by_id.keyBegin(), packet_by_id.keyEnd());
  if (ratings.value(QStringLiteral("contract")).toString() !=
          QStringLiteral("agent-human-review-ratings-v2") ||
      !ratings.value(QStringLiteral("blindReview")).toBool() ||
      ratings.value(QStringLiteral("packetDigestSha256")).toString() !=
          packet_digest ||
      ratings.value(QStringLiteral("manifestSha256")).toString() !=
          packet.value(QStringLiteral("manifestSha256")).toString() ||
      ratings.value(QStringLiteral("machineReportSha256")).toString() !=
          packet.value(QStringLiteral("machineReportSha256")).toString() ||
      reviewer.isEmpty() || !valid_timezone_aware_iso8601(reviewed_at) ||
      rating_case_ids != packet_case_ids) {
    return fail_finalize(QStringLiteral(
        "The ratings are incomplete or belong to a different blind packet."));
  }

  const auto required_dimensions = photographer_calibration_dimension_keys();
  const QSet<QString> required_dimension_set(
      required_dimensions.cbegin(), required_dimensions.cend());
  const auto issue_labels = photographer_calibration_issue_labels();
  const auto is_json_rating_integer = [](const QVariant& value) {
    if (value.typeId() != QMetaType::Double &&
        value.typeId() != QMetaType::Int &&
        value.typeId() != QMetaType::LongLong &&
        value.typeId() != QMetaType::UInt &&
        value.typeId() != QMetaType::ULongLong) {
      return false;
    }
    const auto number = value.toDouble();
    return std::isfinite(number) && number == std::round(number);
  };
  QMap<QString, QVariantMap> normalized_ratings;
  for (const auto& case_id : case_order) {
    const auto rating = ratings_cases.value(case_id).toMap();
    const auto status = rating.value(QStringLiteral("status")).toString();
    const auto score_value = rating.value(QStringLiteral("rating"));
    const auto score = score_value.toInt();
    const auto dimensions = rating.value(QStringLiteral("dimensions")).toMap();
    const QSet<QString> dimension_keys(
        dimensions.keyBegin(), dimensions.keyEnd());
    auto dimensions_valid = dimension_keys == required_dimension_set;
    for (const auto& dimension : required_dimensions) {
      const auto value = dimensions.value(dimension);
      const auto dimension_score = value.toInt();
      dimensions_valid = dimensions_valid &&
                         is_json_rating_integer(value) &&
                         dimension_score >= 1 && dimension_score <= 5;
    }
    QStringList issue_tags;
    QSet<QString> unique_issue_tags;
    auto issues_valid = true;
    for (const auto& value : rating.value(QStringLiteral("issueTags")).toList()) {
      const auto tag = value.toString();
      if (!issue_labels.contains(tag) || unique_issue_tags.contains(tag)) {
        issues_valid = false;
        break;
      }
      unique_issue_tags.insert(tag);
      issue_tags.append(tag);
    }
    const auto notes =
        rating.value(QStringLiteral("notes")).toString().trimmed();
    if ((status != QStringLiteral("pass") &&
         status != QStringLiteral("fail")) ||
        !is_json_rating_integer(score_value) || score < 1 || score > 5 ||
        !dimensions_valid || !issues_valid ||
        (status == QStringLiteral("fail") && issue_tags.isEmpty()) ||
        notes.isEmpty()) {
      return fail_finalize(QStringLiteral(
          "%1 still needs a complete decision, ratings, and note.")
                               .arg(case_id));
    }
    normalized_ratings.insert(
        case_id,
        QVariantMap{
            {QStringLiteral("status"), status},
            {QStringLiteral("rating"), score},
            {QStringLiteral("dimensions"), dimensions},
            {QStringLiteral("issueTags"), issue_tags},
            {QStringLiteral("notes"), notes},
        });
  }

  const auto file_sha256 = [](const QString& path) {
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
      return QString{};
    }
    QCryptographicHash hash(QCryptographicHash::Sha256);
    while (!file.atEnd()) {
      const auto chunk = file.read(1024 * 1024);
      if (chunk.isEmpty() && file.error() != QFileDevice::NoError) {
        return QString{};
      }
      hash.addData(chunk);
    }
    return QString::fromLatin1(hash.result().toHex());
  };
  const auto source_manifest_path = source_to_path(
      packet.value(QStringLiteral("sourceManifest")).toString());
  const auto machine_report_path = source_to_path(
      packet.value(QStringLiteral("sourceMachineReport")).toString());
  if (file_sha256(source_manifest_path) !=
          packet.value(QStringLiteral("manifestSha256")).toString() ||
      file_sha256(machine_report_path) !=
          packet.value(QStringLiteral("machineReportSha256")).toString()) {
    return fail_finalize(QStringLiteral(
        "The source manifest or machine report changed after blind review began."));
  }
  QFile source_manifest_file(source_manifest_path);
  QFile machine_report_file(machine_report_path);
  if (!source_manifest_file.open(QIODevice::ReadOnly) ||
      !machine_report_file.open(QIODevice::ReadOnly)) {
    return fail_finalize(QStringLiteral(
        "The source manifest or machine report could not be read."));
  }
  const auto source_manifest_document =
      QJsonDocument::fromJson(source_manifest_file.readAll());
  const auto machine_report_document =
      QJsonDocument::fromJson(machine_report_file.readAll());
  if (!source_manifest_document.isObject() ||
      !machine_report_document.isObject()) {
    return fail_finalize(QStringLiteral(
        "The source manifest or machine report is invalid JSON."));
  }
  auto reviewed_manifest = source_manifest_document.object().toVariantMap();
  const auto machine_report = machine_report_document.object().toVariantMap();
  QMap<QString, QVariantMap> machine_by_id;
  for (const auto& value :
       machine_report.value(QStringLiteral("cases")).toList()) {
    const auto item = value.toMap();
    const auto case_id = item.value(QStringLiteral("caseId")).toString();
    if (!case_id.isEmpty() && !machine_by_id.contains(case_id)) {
      machine_by_id.insert(case_id, item);
    }
  }
  if (QSet<QString>(machine_by_id.keyBegin(), machine_by_id.keyEnd()) !=
      packet_case_ids) {
    return fail_finalize(QStringLiteral(
        "The machine report case set does not match the reviewed packet."));
  }

  auto assets = reviewed_manifest.value(QStringLiteral("assets")).toList();
  QSet<QString> manifest_case_ids;
  for (auto asset_index = 0; asset_index < assets.size(); ++asset_index) {
    auto asset = assets.at(asset_index).toMap();
    auto agent_cases = asset.value(QStringLiteral("agent_cases")).toList();
    for (auto case_index = 0; case_index < agent_cases.size(); ++case_index) {
      auto agent_case = agent_cases.at(case_index).toMap();
      const auto case_id =
          agent_case.value(QStringLiteral("case_id")).toString();
      if (case_id.isEmpty()) {
        continue;
      }
      if (manifest_case_ids.contains(case_id) ||
          !normalized_ratings.contains(case_id)) {
        return fail_finalize(QStringLiteral(
            "The source manifest case set does not match the reviewed packet."));
      }
      manifest_case_ids.insert(case_id);
      const auto rating = normalized_ratings.value(case_id);
      const auto proof = packet_by_id.value(case_id);
      agent_case.insert(
          QStringLiteral("human_review"),
          QVariantMap{
              {QStringLiteral("status"), rating.value(QStringLiteral("status"))},
              {QStringLiteral("rating"), rating.value(QStringLiteral("rating"))},
              {QStringLiteral("dimensions"),
               rating.value(QStringLiteral("dimensions"))},
              {QStringLiteral("issue_tags"),
               rating.value(QStringLiteral("issueTags"))},
              {QStringLiteral("reviewer"), reviewer},
              {QStringLiteral("reviewed_at"), reviewed_at},
              {QStringLiteral("notes"), rating.value(QStringLiteral("notes"))},
              {QStringLiteral("rating_source_contract"),
               QStringLiteral("agent-human-review-ratings-v2")},
              {QStringLiteral("review_packet_digest_sha256"), packet_digest},
              {QStringLiteral("machine_report_sha256"),
               packet.value(QStringLiteral("machineReportSha256"))},
              {QStringLiteral("before_proof_sha256"),
               proof.value(QStringLiteral("beforeProofSha256"))},
              {QStringLiteral("after_proof_sha256"),
               proof.value(QStringLiteral("afterProofSha256"))},
          });
      agent_cases[case_index] = agent_case;
    }
    asset.insert(QStringLiteral("agent_cases"), agent_cases);
    assets[asset_index] = asset;
  }
  if (manifest_case_ids != packet_case_ids) {
    return fail_finalize(QStringLiteral(
        "The source manifest case set does not match the reviewed packet."));
  }
  reviewed_manifest.insert(QStringLiteral("assets"), assets);
  const auto reviewed_manifest_bytes =
      QJsonDocument::fromVariant(reviewed_manifest)
          .toJson(QJsonDocument::Indented);
  const auto reviewed_manifest_digest = QString::fromLatin1(
      QCryptographicHash::hash(reviewed_manifest_bytes,
                               QCryptographicHash::Sha256)
          .toHex());

  QMap<QString, QList<int>> dimension_scores;
  QMap<QString, int> issue_counts;
  QVariantMap outcomes{
      {QStringLiteral("agreementPass"), 0},
      {QStringLiteral("falseConfidence"), 0},
      {QStringLiteral("overConservative"), 0},
      {QStringLiteral("agreementFail"), 0},
  };
  QVariantMap threshold_signals;
  QVariantList profile_cases;
  const auto threshold_keys_for_check = [](const QString& check) {
    if (check == QStringLiteral("brighter") ||
        check == QStringLiteral("darker")) {
      return QStringList{QStringLiteral("brightness")};
    }
    if (check == QStringLiteral("strongerContrast") ||
        check == QStringLiteral("softerContrast")) {
      return QStringList{QStringLiteral("contrast")};
    }
    if (check == QStringLiteral("warmer")) {
      return QStringList{QStringLiteral("warmth")};
    }
    if (check == QStringLiteral("moreSaturated")) {
      return QStringList{QStringLiteral("saturation")};
    }
    if (check == QStringLiteral("monochrome")) {
      return QStringList{QStringLiteral("monochromeSaturationLimit")};
    }
    if (check == QStringLiteral("preserveTone")) {
      return QStringList{QStringLiteral("preserveLuma"),
                         QStringLiteral("preserveContrast"),
                         QStringLiteral("preserveSaturation")};
    }
    return QStringList{};
  };
  const auto record_threshold_outcome = [&threshold_signals](
                                            const QString& key,
                                            const QVariantMap& observation,
                                            const QString& outcome) {
    auto signal = threshold_signals.value(key).toMap();
    auto observations = signal.value(QStringLiteral("observations")).toList();
    observations.append(observation);
    signal.insert(QStringLiteral("observations"), observations);
    auto false_confidence =
        signal.value(QStringLiteral("falseConfidenceCount")).toInt();
    auto over_conservative =
        signal.value(QStringLiteral("overConservativeCount")).toInt();
    if (outcome == QStringLiteral("false-confidence")) {
      ++false_confidence;
    } else if (outcome == QStringLiteral("over-conservative")) {
      ++over_conservative;
    }
    signal.insert(QStringLiteral("falseConfidenceCount"), false_confidence);
    signal.insert(QStringLiteral("overConservativeCount"), over_conservative);
    threshold_signals.insert(key, signal);
  };
  for (const auto& case_id : case_order) {
    const auto rating = normalized_ratings.value(case_id);
    const auto machine = machine_by_id.value(case_id);
    const auto machine_pass =
        machine.value(QStringLiteral("machinePass")).toBool();
    const auto human_status = rating.value(QStringLiteral("status")).toString();
    QString outcome;
    QString outcome_key;
    if (machine_pass && human_status == QStringLiteral("pass")) {
      outcome = QStringLiteral("agreement-pass");
      outcome_key = QStringLiteral("agreementPass");
    } else if (machine_pass) {
      outcome = QStringLiteral("false-confidence");
      outcome_key = QStringLiteral("falseConfidence");
    } else if (human_status == QStringLiteral("pass")) {
      outcome = QStringLiteral("over-conservative");
      outcome_key = QStringLiteral("overConservative");
    } else {
      outcome = QStringLiteral("agreement-fail");
      outcome_key = QStringLiteral("agreementFail");
    }
    outcomes.insert(outcome_key, outcomes.value(outcome_key).toInt() + 1);
    const auto dimensions = rating.value(QStringLiteral("dimensions")).toMap();
    for (const auto& dimension : required_dimensions) {
      dimension_scores[dimension].append(dimensions.value(dimension).toInt());
    }
    for (const auto& value : rating.value(QStringLiteral("issueTags")).toList()) {
      issue_counts[value.toString()] += 1;
    }
    const auto pixel_alignment_value =
        machine.value(QStringLiteral("pixelIntentAlignment"));
    const auto pixel_alignment = pixel_alignment_value.toMap();
    for (const auto& check_value :
         pixel_alignment.value(QStringLiteral("checks")).toList()) {
      const auto check = check_value.toMap();
      const auto check_name = check.value(QStringLiteral("name")).toString();
      for (const auto& threshold_key : threshold_keys_for_check(check_name)) {
        record_threshold_outcome(
            threshold_key,
            QVariantMap{
                {QStringLiteral("caseId"), case_id},
                {QStringLiteral("check"), check_name},
                {QStringLiteral("delta"), check.value(QStringLiteral("delta"))},
                {QStringLiteral("threshold"),
                 check.value(QStringLiteral("threshold"))},
                {QStringLiteral("machineCheckPassed"),
                 check.value(QStringLiteral("passed"))},
                {QStringLiteral("humanStatus"), human_status},
                {QStringLiteral("humanRating"),
                 rating.value(QStringLiteral("rating"))},
            },
            outcome);
      }
    }
    const auto retouch = machine.value(QStringLiteral("retouchQuality")).toMap();
    QVariant retouch_summary;
    if (retouch.value(QStringLiteral("available")).toBool()) {
      const QStringList retouch_keys{
          QStringLiteral("targetMeanRgbDelta"),
          QStringLiteral("surroundingMeanRgbDelta"),
          QStringLiteral("surroundingChangedFraction"),
          QStringLiteral("surroundingGradientEnergyRatio"),
          QStringLiteral("reconstructionGradientEnergyRatio"),
      };
      QVariantMap observation{
          {QStringLiteral("caseId"), case_id},
          {QStringLiteral("humanStatus"), human_status},
          {QStringLiteral("humanRating"),
           rating.value(QStringLiteral("rating"))},
      };
      for (const auto& key : retouch_keys) {
        auto summary = retouch_summary.toMap();
        summary.insert(key, retouch.value(key));
        retouch_summary = summary;
        observation.insert(key, retouch.value(key));
      }
      record_threshold_outcome(
          QStringLiteral("retouchQuality"), observation, outcome);
    }
    profile_cases.append(QVariantMap{
        {QStringLiteral("caseId"), case_id},
        {QStringLiteral("caseKind"),
         packet_by_id.value(case_id).value(QStringLiteral("caseKind"))},
        {QStringLiteral("machinePass"), machine_pass},
        {QStringLiteral("humanStatus"), human_status},
        {QStringLiteral("humanRating"),
         rating.value(QStringLiteral("rating"))},
        {QStringLiteral("dimensions"), dimensions},
        {QStringLiteral("issueTags"),
         rating.value(QStringLiteral("issueTags"))},
        {QStringLiteral("outcome"), outcome},
        {QStringLiteral("pixelIntentAlignment"), pixel_alignment_value},
        {QStringLiteral("retouchQuality"), retouch_summary},
    });
  }
  for (auto iterator = threshold_signals.begin();
       iterator != threshold_signals.end(); ++iterator) {
    auto signal = iterator.value().toMap();
    const auto false_confidence =
        signal.value(QStringLiteral("falseConfidenceCount")).toInt();
    const auto over_conservative =
        signal.value(QStringLiteral("overConservativeCount")).toInt();
    QString status;
    QString action;
    if (false_confidence > 0 && over_conservative > 0) {
      status = QStringLiteral("conflicting-human-signal");
      action = QStringLiteral("collect-more-evidence");
    } else if (false_confidence > 0) {
      status = QStringLiteral("human-rejected-machine-pass");
      action = QStringLiteral("tighten-and-rerun");
    } else if (over_conservative > 0) {
      status = QStringLiteral("human-accepted-machine-fail");
      action = QStringLiteral("relax-and-rerun");
    } else {
      status = QStringLiteral("no-change-signal");
      action = QStringLiteral("hold-until-disagreement");
    }
    signal.insert(QStringLiteral("status"), status);
    signal.insert(QStringLiteral("suggestedAction"), action);
    signal.insert(QStringLiteral("automaticThresholdChangeAllowed"), false);
    iterator.value() = signal;
  }

  QVariantMap dimension_means;
  QStringList weakest_dimensions = required_dimensions;
  for (const auto& dimension : required_dimensions) {
    const auto values = dimension_scores.value(dimension);
    const auto total = std::accumulate(values.cbegin(), values.cend(), 0.0);
    const auto mean = std::round((total / values.size()) * 1000.0) / 1000.0;
    dimension_means.insert(dimension, mean);
  }
  std::sort(
      weakest_dimensions.begin(), weakest_dimensions.end(),
      [&dimension_means](const QString& left, const QString& right) {
        const auto left_mean = dimension_means.value(left).toDouble();
        const auto right_mean = dimension_means.value(right).toDouble();
        return left_mean == right_mean ? left < right : left_mean < right_mean;
      });
  QVariantMap issue_count_map;
  for (auto iterator = issue_counts.constBegin();
       iterator != issue_counts.constEnd(); ++iterator) {
    if (iterator.value() > 0) {
      issue_count_map.insert(iterator.key(), iterator.value());
    }
  }
  QVariantMap profile{
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-profile-v1")},
      {QStringLiteral("version"), 1},
      {QStringLiteral("status"), QStringLiteral("observed")},
      {QStringLiteral("reviewer"), reviewer},
      {QStringLiteral("reviewedAt"), reviewed_at},
      {QStringLiteral("caseCount"), case_order.size()},
      {QStringLiteral("packetDigestSha256"), packet_digest},
      {QStringLiteral("sourceManifestSha256"),
       packet.value(QStringLiteral("manifestSha256"))},
      {QStringLiteral("reviewedManifestSha256"), reviewed_manifest_digest},
      {QStringLiteral("machineReportSha256"),
       packet.value(QStringLiteral("machineReportSha256"))},
      {QStringLiteral("blindReview"), true},
      {QStringLiteral("localOnly"), true},
      {QStringLiteral("professionalReadinessClaimed"), false},
      {QStringLiteral("automaticThresholdMutationAllowed"), false},
      {QStringLiteral("freshCorpusRunRequiredAfterThresholdChange"), true},
      {QStringLiteral("tasteSummary"),
       QVariantMap{
           {QStringLiteral("dimensionMeans"), dimension_means},
           {QStringLiteral("weakestDimensions"), weakest_dimensions},
           {QStringLiteral("issueTagCounts"), issue_count_map},
       }},
      {QStringLiteral("outcomes"), outcomes},
      {QStringLiteral("thresholdSignals"), threshold_signals},
      {QStringLiteral("cases"), profile_cases},
  };
  profile.insert(QStringLiteral("profileDigestSha256"),
                 stable_variant_hash(profile));
  QStringList profile_errors;
  if (compact_photographer_calibration_profile(profile, &profile_errors)
          .isEmpty() ||
      !profile_errors.isEmpty()) {
    return fail_finalize(
        profile_errors.isEmpty()
            ? QStringLiteral("The native calibration profile could not be verified.")
            : profile_errors.join(QStringLiteral("; ")));
  }
  const auto profile_bytes =
      QJsonDocument::fromVariant(profile).toJson(QJsonDocument::Indented);
  const auto results_directory =
      packet_directory.filePath(QStringLiteral("calibration-results"));
  if (!QDir().mkpath(results_directory)) {
    return fail_finalize(QStringLiteral(
        "The calibration results directory could not be created."));
  }
  const auto ratings_digest = stable_variant_hash(ratings).left(16);
  const auto reviewed_manifest_name =
      QStringLiteral("reviewed-manifest-%1.json").arg(ratings_digest);
  const auto profile_name =
      QStringLiteral("photographer-taste-profile-%1.json").arg(ratings_digest);
  const auto reviewed_manifest_path =
      QDir(results_directory).filePath(reviewed_manifest_name);
  const auto profile_path = QDir(results_directory).filePath(profile_name);
  const auto write_exact = [](const QString& path,
                              const QByteArray& bytes,
                              QString* error) {
    QFile existing(path);
    if (existing.exists()) {
      if (existing.open(QIODevice::ReadOnly) && existing.readAll() == bytes) {
        return true;
      }
      if (error != nullptr) {
        *error = QStringLiteral("An existing calibration result has different contents.");
      }
      return false;
    }
    QSaveFile output(path);
    if (!output.open(QIODevice::WriteOnly) ||
        output.write(bytes) != bytes.size() || !output.commit()) {
      if (error != nullptr) {
        *error = QStringLiteral("A calibration result could not be written safely.");
      }
      return false;
    }
    return true;
  };
  QString write_error;
  const auto result_path_available = [&write_error](const QString& path,
                                                     const QByteArray& bytes) {
    QFile existing(path);
    if (!existing.exists()) {
      return true;
    }
    if (existing.open(QIODevice::ReadOnly) && existing.readAll() == bytes) {
      return true;
    }
    write_error =
        QStringLiteral("An existing calibration result has different contents.");
    return false;
  };
  if (!result_path_available(reviewed_manifest_path,
                             reviewed_manifest_bytes) ||
      !result_path_available(profile_path, profile_bytes)) {
    return fail_finalize(write_error);
  }
  if (!write_exact(reviewed_manifest_path, reviewed_manifest_bytes,
                   &write_error) ||
      !write_exact(profile_path, profile_bytes, &write_error)) {
    return fail_finalize(write_error);
  }
  const auto import_report = importPhotographerCalibrationProfile(
      QString::fromUtf8(profile_bytes));
  if (!import_report.value(QStringLiteral("ok")).toBool()) {
    return fail_finalize(
        import_report.value(QStringLiteral("failureReason")).toString());
  }
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("finalized"), true);
  report.insert(QStringLiteral("profileImported"), true);
  report.insert(QStringLiteral("caseCount"), case_order.size());
  report.insert(QStringLiteral("profile"),
                import_report.value(QStringLiteral("profile")));
  report.insert(QStringLiteral("packetDigestSha256"), packet_digest);
  report.insert(QStringLiteral("profileDigestSha256"),
                profile.value(QStringLiteral("profileDigestSha256")));
  report.insert(QStringLiteral("reviewedManifestSha256"),
                reviewed_manifest_digest);
  report.insert(QStringLiteral("reviewedManifestPath"),
                reviewed_manifest_path);
  report.insert(QStringLiteral("profilePath"), profile_path);
  report.insert(QStringLiteral("reviewedManifestFileName"),
                reviewed_manifest_name);
  report.insert(QStringLiteral("profileFileName"), profile_name);
  report.insert(QStringLiteral("humanPassCount"),
                outcomes.value(QStringLiteral("agreementPass")).toInt() +
                    outcomes.value(QStringLiteral("overConservative")).toInt());
  report.insert(QStringLiteral("humanFailCount"),
                outcomes.value(QStringLiteral("falseConfidence")).toInt() +
                    outcomes.value(QStringLiteral("agreementFail")).toInt());
  report.insert(QStringLiteral("thresholdReviewRequired"),
                outcomes.value(QStringLiteral("falseConfidence")).toInt() > 0 ||
                    outcomes.value(QStringLiteral("overConservative")).toInt() > 0);
  report.insert(QStringLiteral("memoryWrite"),
                import_report.value(QStringLiteral("memoryWrite")));
  report.insert(QStringLiteral("userVisibleMemoryEvents"),
                import_report.value(QStringLiteral("userVisibleMemoryEvents")));
  return report;
}

QVariantMap AgentEditController::forgetPhotographerCalibrationProfile(
    bool confirmed) {
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("forget-photographer-calibration")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-photographer-calibration-forget-v1")},
      {QStringLiteral("projectKey"), currentContinuityProjectKey()},
      {QStringLiteral("confirmed"), confirmed},
      {QStringLiteral("confirmationRequired"), !confirmed},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("memoryEffect"),
       QStringLiteral("exclude-calibration-from-future-project-planning")},
  };
  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(currentContinuityProjectKey()).toMap();
  const auto stored =
      entry.value(QStringLiteral("photographerCalibration")).toMap();
  if (stored.isEmpty()) {
    const auto error = QStringLiteral(
        "No photographer calibration is active for this project.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  report.insert(
      QStringLiteral("profileDigestSha256"),
      stored.value(QStringLiteral("profileDigestSha256")));
  if (!confirmed) {
    const auto error = QStringLiteral(
        "Forget this photographer calibration for future project edits? Existing edits will not change.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  entry.remove(QStringLiteral("photographerCalibration"));
  entry.insert(
      QStringLiteral("tasteUpdatedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(currentContinuityProjectKey(), entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(
        QStringLiteral("failureReason"),
        write_report.value(QStringLiteral("errors"))
            .toStringList()
            .join(QStringLiteral("; ")));
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  emit projectTasteChanged();
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("forgotten"), true);
  report.insert(QStringLiteral("confirmationRequired"), false);
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.remove(QStringLiteral("errors"));
  report.remove(QStringLiteral("failureReason"));
  return report;
}

QVariantMap AgentEditController::projectNorthStarStatus() const {
  const auto project_key = currentContinuityProjectKey();
  const auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  const auto north_star =
      state.value(QStringLiteral("projects"))
          .toMap()
          .value(project_key)
          .toMap()
          .value(QStringLiteral("projectNorthStar"))
          .toMap();
  return QVariantMap{
      {QStringLiteral("ok"), true},
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-north-star-status-v1")},
      {QStringLiteral("available"), !north_star.isEmpty()},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"),
       project_key != QStringLiteral("__global__")},
      {QStringLiteral("northStar"), north_star},
      {QStringLiteral("brief"),
       north_star.value(QStringLiteral("brief"))},
      {QStringLiteral("guidesFuturePlanning"), !north_star.isEmpty()},
      {QStringLiteral("qualitativePlanningInfluence"), !north_star.isEmpty()},
      {QStringLiteral("currentRequestWins"), true},
      {QStringLiteral("styleAndSafetyWin"), true},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("automaticRecipeInfluence"), false},
      {QStringLiteral("directNumericRecipeAuthority"), false},
      {QStringLiteral("automaticCullAuthority"), false},
      {QStringLiteral("automaticRetouchAuthority"), false},
      {QStringLiteral("destructiveAuthority"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
}

QVariantMap AgentEditController::saveProjectNorthStar(
    const QString& brief) {
  const auto project_key = currentContinuityProjectKey();
  const auto normalized_brief = brief.simplified();
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"), QStringLiteral("save-project-north-star")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-north-star-save-v1")},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"),
       project_key != QStringLiteral("__global__")},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("guidesFuturePlanning"), true},
      {QStringLiteral("qualitativePlanningInfluence"), true},
      {QStringLiteral("currentRequestWins"), true},
      {QStringLiteral("styleAndSafetyWin"), true},
      {QStringLiteral("automaticRecipeInfluence"), false},
      {QStringLiteral("directNumericRecipeAuthority"), false},
      {QStringLiteral("automaticCullAuthority"), false},
      {QStringLiteral("automaticRetouchAuthority"), false},
      {QStringLiteral("destructiveAuthority"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  QStringList errors;
  if (project_key == QStringLiteral("__global__")) {
    errors.append(QStringLiteral(
        "Choose a project before setting its North Star."));
  }
  if (normalized_brief.size() < 12) {
    errors.append(QStringLiteral(
        "Describe the assignment's enduring intent in at least 12 characters."));
  }
  if (normalized_brief.size() > 360) {
    errors.append(QStringLiteral(
        "Keep the Project North Star to 360 characters or fewer."));
  }
  if (normalized_brief.contains(QStringLiteral("data:image"),
                                Qt::CaseInsensitive) ||
      normalized_brief.contains(QStringLiteral(";base64,"),
                                Qt::CaseInsensitive)) {
    errors.append(QStringLiteral(
        "Project intent cannot contain embedded image data."));
  }
  if (!errors.isEmpty()) {
    report.insert(QStringLiteral("errors"), errors);
    report.insert(QStringLiteral("failureReason"),
                  errors.join(QStringLiteral("; ")));
    return report;
  }

  const auto identity = QVariantMap{
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("brief"), normalized_brief},
  };
  QVariantMap north_star{
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-north-star-memory-v1")},
      {QStringLiteral("schemaVersion"), 1},
      {QStringLiteral("id"),
       QStringLiteral("north-star-%1")
           .arg(stable_variant_hash(identity).left(16))},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("brief"), normalized_brief},
      {QStringLiteral("source"), QStringLiteral("explicit-user-authored")},
      {QStringLiteral("updatedAtUtc"),
       QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)},
      {QStringLiteral("authority"),
       QStringLiteral("qualitative-project-planning-brief-only")},
      {QStringLiteral("precedence"),
       QStringLiteral("current-request-then-style-and-safety-then-north-star")},
      {QStringLiteral("guidesFuturePlanning"), true},
      {QStringLiteral("qualitativePlanningInfluence"), true},
      {QStringLiteral("requiresFreshDraft"), true},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("automaticRecipeInfluence"), false},
      {QStringLiteral("automaticCullInfluence"), false},
      {QStringLiteral("directNumericRecipeAuthority"), false},
      {QStringLiteral("automaticCullAuthority"), false},
      {QStringLiteral("automaticRetouchAuthority"), false},
      {QStringLiteral("destructiveAuthority"), false},
      {QStringLiteral("storesAssetIds"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  north_star.insert(QStringLiteral("digestSha256"),
                    stable_variant_hash(north_star));

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  if (!state.value(QStringLiteral("ok")).toBool()) {
    state = QVariantMap{
        {QStringLiteral("version"), 1},
        {QStringLiteral("projects"), QVariantMap{}},
    };
  }
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  entry.insert(QStringLiteral("projectKey"), project_key);
  entry.insert(QStringLiteral("projectNorthStar"), north_star);
  entry.insert(QStringLiteral("tasteUpdatedAtUtc"),
               QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(QStringLiteral("failureReason"),
                  write_report.value(QStringLiteral("errors"))
                      .toStringList()
                      .join(QStringLiteral("; ")));
    return report;
  }

  auto memory_event = user_visible_memory_event(
      QStringLiteral("project_north_star_saved"),
      selected_style_id_,
      selectedStyle().value(QStringLiteral("name")).toString(),
      QStringLiteral("Project North Star saved"),
      normalized_brief,
      QVariantMap{
          {QStringLiteral("northStarId"),
           north_star.value(QStringLiteral("id"))},
          {QStringLiteral("projectKey"), project_key},
      });
  memory_event.insert(QStringLiteral("requiresUserVisibility"), true);
  memory_event.insert(QStringLiteral("memoryWriteApproved"), true);
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("saved"), true);
  report.insert(QStringLiteral("northStar"), north_star);
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.insert(QStringLiteral("userVisibleMemoryEvents"),
                QVariantList{memory_event});
  report.remove(QStringLiteral("errors"));
  report.remove(QStringLiteral("failureReason"));
  emit projectTasteChanged();
  return report;
}

QVariantMap AgentEditController::forgetProjectNorthStar(
    bool confirmed) {
  const auto project_key = currentContinuityProjectKey();
  const auto status = projectNorthStarStatus();
  const auto north_star = status.value(QStringLiteral("northStar")).toMap();
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"), QStringLiteral("forget-project-north-star")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-north-star-forget-v1")},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"),
       project_key != QStringLiteral("__global__")},
      {QStringLiteral("confirmed"), confirmed},
      {QStringLiteral("confirmationRequired"), !confirmed},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("memoryEffect"),
       QStringLiteral("exclude-from-future-project-planning")},
  };
  if (north_star.isEmpty()) {
    const auto error = QStringLiteral(
        "No Project North Star is saved for this project.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  report.insert(QStringLiteral("northStarId"),
                north_star.value(QStringLiteral("id")));
  if (!confirmed) {
    const auto message = QStringLiteral(
        "Forget this Project North Star for future drafts? Existing edits and the active draft will not change.");
    report.insert(QStringLiteral("errors"), QStringList{message});
    report.insert(QStringLiteral("failureReason"), message);
    return report;
  }

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  entry.remove(QStringLiteral("projectNorthStar"));
  entry.insert(QStringLiteral("tasteUpdatedAtUtc"),
               QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(QStringLiteral("failureReason"),
                  write_report.value(QStringLiteral("errors"))
                      .toStringList()
                      .join(QStringLiteral("; ")));
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("forgotten"), true);
  report.insert(QStringLiteral("confirmationRequired"), false);
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.remove(QStringLiteral("errors"));
  report.remove(QStringLiteral("failureReason"));
  emit projectTasteChanged();
  return report;
}

QVariantMap AgentEditController::approvedProjectTaste() const {
  const auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  const auto project_key = currentContinuityProjectKey();
  const auto entry = state.value(QStringLiteral("projects"))
                         .toMap()
                         .value(project_key)
                         .toMap();
  const auto project_north_star =
      entry.value(QStringLiteral("projectNorthStar")).toMap();
  const auto approvals = entry.value(QStringLiteral("approvedEdits")).toList();
  const auto corrections =
      entry.value(QStringLiteral("approvedCorrections")).toList();
  const auto rejected_drafts =
      entry.value(QStringLiteral("rejectedDrafts")).toList();
  const auto story_preferences =
      entry.value(QStringLiteral("storyPreferences")).toList();
  const auto calibration = photographer_calibration_card(
      entry.value(QStringLiteral("photographerCalibration")).toMap());
  const auto visual_referents = recentVisualReferents();
  auto approved_asset_count = 0;
  auto first_look_choice_count = 0;
  auto deep_review_choice_count = 0;
  auto touched_selector_count = 0;
  QString latest_two_speed_version;
  for (const auto& approval_value : approvals) {
    const auto approval = approval_value.toMap();
    approved_asset_count +=
        approval.value(QStringLiteral("assetCount")).toInt();
    const auto choice =
        approval.value(QStringLiteral("twoSpeedDraftChoice")).toMap();
    if (choice.value(QStringLiteral("contract")).toString() !=
        QStringLiteral("agent-two-speed-taste-choice-v1")) {
      continue;
    }
    const auto selected_version =
        choice.value(QStringLiteral("selectedVersion")).toString();
    if (selected_version == QStringLiteral("first-look")) {
      ++first_look_choice_count;
    } else if (selected_version == QStringLiteral("deep-review")) {
      ++deep_review_choice_count;
    } else {
      continue;
    }
    if (latest_two_speed_version.isEmpty()) {
      latest_two_speed_version = selected_version;
    }
    if (choice.value(QStringLiteral("selectorTouched")).toBool()) {
      ++touched_selector_count;
    }
  }
  const auto two_speed_choice_count =
      first_look_choice_count + deep_review_choice_count;
  const auto enough_two_speed_evidence = two_speed_choice_count >= 2;
  const auto has_two_speed_preference =
      enough_two_speed_evidence &&
      first_look_choice_count != deep_review_choice_count;
  const auto preferred_two_speed_version =
      !has_two_speed_preference
          ? QString{}
      : first_look_choice_count > deep_review_choice_count
          ? QStringLiteral("first-look")
          : QStringLiteral("deep-review");
  const auto two_speed_guidance =
      !enough_two_speed_evidence
          ? QStringLiteral(
                "Observe this choice only; wait for another confirmed edit "
                "before it influences planning.")
      : preferred_two_speed_version == QStringLiteral("first-look")
          ? QStringLiteral(
                "Prefer restrained, direct edits close to the proved first "
                "look unless this photo or request clearly benefits from "
                "deeper refinement.")
      : preferred_two_speed_version == QStringLiteral("deep-review")
          ? QStringLiteral(
                "Allow evidence-backed deep refinements when they improve the "
                "proved first look, while keeping the first look available "
                "for review.")
          : QStringLiteral(
                "The photographer's proved-version choices are mixed; keep "
                "both versions neutral and ask through the visible choice.");
  const QVariantMap two_speed_preference{
      {QStringLiteral("contract"),
       QStringLiteral("agent-two-speed-taste-signal-v1")},
      {QStringLiteral("available"), two_speed_choice_count > 0},
      {QStringLiteral("choiceCount"), two_speed_choice_count},
      {QStringLiteral("firstLookCount"), first_look_choice_count},
      {QStringLiteral("deepReviewCount"), deep_review_choice_count},
      {QStringLiteral("selectorTouchedCount"), touched_selector_count},
      {QStringLiteral("latestSelectedVersion"), latest_two_speed_version},
      {QStringLiteral("minimumEvidenceCount"), 2},
      {QStringLiteral("enoughEvidence"), enough_two_speed_evidence},
      {QStringLiteral("preferredVersion"), preferred_two_speed_version},
      {QStringLiteral("influencesPlanning"), has_two_speed_preference},
      {QStringLiteral("planningGuidance"), two_speed_guidance},
      {QStringLiteral("authority"),
       QStringLiteral("project-local-qualitative-guidance-only")},
      {QStringLiteral("currentRequestWins"), true},
      {QStringLiteral("automaticVersionSelectionAllowed"), false},
      {QStringLiteral("automaticCommitAllowed"), false},
      {QStringLiteral("forgetRequiresConfirmation"), true},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesProofPaths"), false},
      {QStringLiteral("storesAdjustmentSnapshots"), false},
  };
  QVariantList exemplars;
  for (const auto& approval_value : approvals.mid(0, 3)) {
    exemplars.append(approval_value);
  }
  QVariantList evidence;
  const auto append_evidence =
      [&evidence](const QString& kind,
                  const QVariantMap& source,
                  const QString& title,
                  const QString& summary,
                  const QString& detail,
                  const QString& at_utc) {
        QStringList asset_ids;
        const auto append_asset_id = [&asset_ids](const QString& asset_id) {
          const auto normalized_id = asset_id.trimmed();
          if (!normalized_id.isEmpty() && !asset_ids.contains(normalized_id) &&
              asset_ids.size() < 4) {
            asset_ids.append(normalized_id);
          }
        };
        for (const auto& asset_id :
             source.value(QStringLiteral("assetIds")).toStringList()) {
          append_asset_id(asset_id);
        }
        append_asset_id(source.value(QStringLiteral("assetId")).toString());
        for (const auto& examples_key : {
                 QStringLiteral("assetExamples"),
                 QStringLiteral("approvedRecipeExamples"),
                 QStringLiteral("rejectedRecipeExamples"),
                 QStringLiteral("recipeExamples")}) {
          for (const auto& example_value :
               source.value(examples_key).toList()) {
            append_asset_id(
                example_value.toMap().value(QStringLiteral("assetId")).toString());
          }
        }
        QVariantMap item{
            {QStringLiteral("contract"),
             QStringLiteral("agent-project-taste-evidence-v1")},
            {QStringLiteral("kind"), kind},
            {QStringLiteral("id"),
             project_taste_evidence_id(kind, source)},
            {QStringLiteral("title"), title},
            {QStringLiteral("summary"), summary.simplified().left(240)},
            {QStringLiteral("detail"), detail.simplified().left(160)},
            {QStringLiteral("atUtc"), at_utc},
            {QStringLiteral("forgettable"), true},
            {QStringLiteral("confirmationRequired"), true},
        };
        item.insert(QStringLiteral("assetIds"), asset_ids);
        item.insert(QStringLiteral("visualExemplarAvailable"),
                    !asset_ids.isEmpty());
        evidence.append(item);
      };
  for (const auto& value : approvals) {
    const auto approval = value.toMap();
    const auto direction_choice =
        approval.value(QStringLiteral("directionChoice")).toMap();
    const auto two_speed_choice =
        approval.value(QStringLiteral("twoSpeedDraftChoice")).toMap();
    const auto taste_teaching_signal =
        direction_choice.value(QStringLiteral("tasteTeachingSignal")).toBool() ||
        !two_speed_choice.isEmpty();
    auto summary = approval.value(QStringLiteral("planSummary")).toString();
    if (!two_speed_choice.isEmpty()) {
      const auto selected_label =
          two_speed_choice
              .value(QStringLiteral("selectedLabel"))
              .toString();
      const auto intent =
          approval.value(QStringLiteral("userIntent")).toString();
      summary = intent.trimmed().isEmpty()
                    ? selected_label
                    : QStringLiteral("%1 · %2")
                          .arg(selected_label, intent);
    } else if (taste_teaching_signal &&
        !direction_choice.value(QStringLiteral("summary"))
             .toString()
             .trimmed()
             .isEmpty()) {
      summary = direction_choice.value(QStringLiteral("summary")).toString();
    }
    if (summary.trimmed().isEmpty()) {
      summary = approval.value(QStringLiteral("userIntent")).toString();
    }
    append_evidence(
        QStringLiteral("approved-look"),
        approval,
        !two_speed_choice.isEmpty()
            ? QStringLiteral("Proved version you chose")
        : taste_teaching_signal
            ? QStringLiteral("Taste choice you taught me")
            : QStringLiteral("Approved look"),
        summary,
        !two_speed_choice.isEmpty()
            ? QStringLiteral(
                  "Chosen from First Look and Deep Review · remembered only "
                  "after commit")
        : taste_teaching_signal
            ? QStringLiteral(
                  "Chosen from two rendered calibration directions · remembered after commit")
            : QStringLiteral("%1 photo%2 · %3")
                  .arg(approval.value(QStringLiteral("assetCount")).toInt())
                  .arg(approval.value(QStringLiteral("assetCount")).toInt() == 1
                           ? QString()
                           : QStringLiteral("s"))
                  .arg(approval.value(QStringLiteral("styleId")).toString()),
        approval.value(QStringLiteral("approvedAtUtc")).toString());
  }
  for (const auto& value : corrections) {
    const auto correction = value.toMap();
    append_evidence(
        QStringLiteral("approved-correction"),
        correction,
        QStringLiteral("Correction you taught me"),
        correction.value(QStringLiteral("feedback")).toString(),
        QStringLiteral("Learned only after you approved the revised edit"),
        correction.value(QStringLiteral("approvedAtUtc")).toString());
  }
  for (const auto& value : rejected_drafts) {
    const auto rejected = value.toMap();
    append_evidence(
        QStringLiteral("rejected-draft"),
        rejected,
        QStringLiteral("Direction you discarded"),
        rejected.value(QStringLiteral("userIntent")).toString(),
        QStringLiteral("Avoid exact recipe only · no reason inferred"),
        rejected.value(QStringLiteral("rejectedAtUtc")).toString());
  }
  for (const auto& value : visual_referents) {
    const auto referent = value.toMap();
    append_evidence(
        QStringLiteral("visual-referent"),
        referent,
        QStringLiteral("Remembered object"),
        referent.value(QStringLiteral("chosenLabel")).toString(),
        QStringLiteral("Exact project and photo only"),
        referent.value(QStringLiteral("confirmedAtUtc")).toString());
  }
  for (const auto& value : story_preferences) {
    const auto preference = value.toMap();
    QStringList role_labels;
    for (const auto& anchor_value :
         preference.value(QStringLiteral("roleAnchors")).toList()) {
      role_labels.append(assignment_story_role_label(
          anchor_value.toMap().value(QStringLiteral("role")).toString()));
    }
    append_evidence(
        QStringLiteral("story-preference"),
        preference,
        QStringLiteral("Remembered story arc"),
        role_labels.join(QStringLiteral(" → ")),
        QStringLiteral(
            "Source-order role suggestions only · no recipe or culling influence"),
        preference.value(QStringLiteral("rememberedAtUtc")).toString());
  }
  if (calibration.value(QStringLiteral("available")).toBool()) {
    append_evidence(
        QStringLiteral("photographer-calibration"),
        calibration,
        QStringLiteral("Blind photographer calibration"),
        calibration.value(QStringLiteral("summary")).toString(),
        calibration.value(QStringLiteral("requiresThresholdReview")).toBool()
            ? QStringLiteral(
                  "Conservative guidance active · threshold changes still require a fresh corpus")
            : QStringLiteral(
                  "Photographer evidence active · no automatic threshold changes"),
        calibration.value(QStringLiteral("reviewedAt")).toString());
  }
  std::stable_sort(
      evidence.begin(),
      evidence.end(),
      [](const QVariant& left, const QVariant& right) {
        return left.toMap().value(QStringLiteral("atUtc")).toString() >
               right.toMap().value(QStringLiteral("atUtc")).toString();
      });
  QString taste_summary;
  if (!story_preferences.isEmpty()) {
    taste_summary = QStringLiteral(
        "Use the explicitly remembered source-order story arc for future suggestions.");
  } else if (!corrections.isEmpty()) {
    taste_summary = corrections.first()
                        .toMap()
                        .value(QStringLiteral("feedback"))
                        .toString();
  } else if (!approvals.isEmpty()) {
    const auto latest = approvals.first().toMap();
    const auto latest_two_speed_choice =
        latest.value(QStringLiteral("twoSpeedDraftChoice")).toMap();
    if (!latest_two_speed_choice.isEmpty()) {
      taste_summary = QStringLiteral(
          "You approved %1 from two proved versions. %2")
                            .arg(
                                latest_two_speed_choice
                                    .value(QStringLiteral("selectedLabel"))
                                    .toString(),
                                two_speed_guidance);
    } else {
      taste_summary =
          latest.value(QStringLiteral("planSummary")).toString();
    }
    if (taste_summary.trimmed().isEmpty()) {
      taste_summary = latest.value(QStringLiteral("userIntent")).toString();
    }
  } else if (!visual_referents.isEmpty()) {
    taste_summary = QStringLiteral("Remember %1 on this exact photo.")
                        .arg(visual_referents.first()
                                 .toMap()
                                 .value(QStringLiteral("chosenLabel"))
                                 .toString());
  } else if (!rejected_drafts.isEmpty()) {
    taste_summary = QStringLiteral(
        "Avoid the discarded recipe direction without guessing why.");
  } else if (calibration.value(QStringLiteral("available")).toBool()) {
    taste_summary = calibration.value(QStringLiteral("summary")).toString();
  }
  const auto evidence_count = evidence.size();
  auto visual_exemplar_count = 0;
  for (const auto& evidence_value : evidence) {
    if (evidence_value
            .toMap()
            .value(QStringLiteral("visualExemplarAvailable"))
            .toBool()) {
      ++visual_exemplar_count;
    }
  }
  const auto maturity = calibration.value(QStringLiteral("available")).toBool()
                            ? QStringLiteral("calibrated")
                        : approvals.size() + corrections.size() >= 3
                            ? QStringLiteral("established")
                        : evidence_count > 0
                            ? QStringLiteral("learning")
                            : QStringLiteral("new");
  auto taste_name = entry.value(QStringLiteral("tasteName")).toString().trimmed();
  if (taste_name.isEmpty()) {
    taste_name = selectedStyle().value(QStringLiteral("name")).toString().trimmed();
  }
  if (taste_name.isEmpty()) {
    taste_name = QStringLiteral("Project Taste");
  }
  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-taste-mirror-v2")},
      {QStringLiteral("available"),
       !approvals.isEmpty() || !corrections.isEmpty() ||
           !rejected_drafts.isEmpty() || !visual_referents.isEmpty() ||
           !story_preferences.isEmpty() ||
           !project_north_star.isEmpty() ||
           calibration.value(QStringLiteral("available")).toBool()},
      {QStringLiteral("hasApprovedTaste"), !approvals.isEmpty()},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"), project_key != QStringLiteral("__global__")},
      {QStringLiteral("name"), taste_name.left(80)},
      {QStringLiteral("renamable"), project_key != QStringLiteral("__global__")},
      {QStringLiteral("editable"), true},
      {QStringLiteral("forgetRequiresConfirmation"), true},
      {QStringLiteral("evidenceCount"), evidence_count},
      {QStringLiteral("evidence"), evidence},
      {QStringLiteral("visualExemplarCount"), visual_exemplar_count},
      {QStringLiteral("visualExemplarsByCatalogId"), true},
      {QStringLiteral("summary"), taste_summary.simplified().left(280)},
      {QStringLiteral("maturity"), maturity},
      {QStringLiteral("approvalCount"), approvals.size()},
      {QStringLiteral("approvedAssetCount"), approved_asset_count},
      {QStringLiteral("latestApprovedAtUtc"),
       approvals.isEmpty()
           ? QVariant{}
           : approvals.first().toMap().value(QStringLiteral("approvedAtUtc"))},
      {QStringLiteral("exemplars"), exemplars},
      {QStringLiteral("correctionCount"), corrections.size()},
      {QStringLiteral("corrections"), corrections.mid(0, 3)},
      {QStringLiteral("rejectionCount"), rejected_drafts.size()},
      {QStringLiteral("rejectedDrafts"), rejected_drafts.mid(0, 3)},
      {QStringLiteral("visualReferentCount"), visual_referents.size()},
      {QStringLiteral("recentVisualReferents"), visual_referents.mid(0, 4)},
      {QStringLiteral("storyPreferenceCount"), story_preferences.size()},
      {QStringLiteral("storyPreferences"), story_preferences.mid(0, 3)},
      {QStringLiteral("twoSpeedPreference"), two_speed_preference},
      {QStringLiteral("projectNorthStarAvailable"),
       !project_north_star.isEmpty()},
      {QStringLiteral("projectNorthStar"), project_north_star},
      {QStringLiteral("photographerCalibrationAvailable"),
       calibration.value(QStringLiteral("available"))},
      {QStringLiteral("photographerCalibration"), calibration},
      {QStringLiteral("maximumStoredApprovals"), 12},
      {QStringLiteral("maximumStoredCorrections"), 12},
      {QStringLiteral("maximumStoredRejections"), 8},
      {QStringLiteral("maximumStoredVisualReferents"), 12},
      {QStringLiteral("projectIsolation"), QStringLiteral("exact-project-key-only")},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
}

QVariantMap AgentEditController::assignmentTasteReflection() const {
  const auto taste = approvedProjectTaste();
  const auto project_key = taste.value(QStringLiteral("projectKey")).toString();
  const auto preference =
      taste.value(QStringLiteral("twoSpeedPreference")).toMap();
  const auto project_local =
      taste.value(QStringLiteral("projectLocal")).toBool();
  const auto north_star_available =
      taste.value(QStringLiteral("projectNorthStarAvailable")).toBool();
  const auto preference_available =
      preference.value(QStringLiteral("influencesPlanning")).toBool();
  const auto preferred_version =
      preference.value(QStringLiteral("preferredVersion")).toString();
  const auto choice_count =
      preference.value(QStringLiteral("choiceCount")).toInt();
  const auto first_look_count =
      preference.value(QStringLiteral("firstLookCount")).toInt();
  const auto deep_review_count =
      preference.value(QStringLiteral("deepReviewCount")).toInt();
  const auto selector_touched_count =
      preference.value(QStringLiteral("selectorTouchedCount")).toInt();
  const auto available =
      project_local && !north_star_available && preference_available &&
      choice_count >= 2 &&
      (preferred_version == QStringLiteral("first-look") ||
       preferred_version == QStringLiteral("deep-review"));

  const auto preferred_label =
      preferred_version == QStringLiteral("first-look")
          ? QStringLiteral("First Look")
          : QStringLiteral("Deep Review");
  const auto headline =
      preferred_version == QStringLiteral("first-look")
          ? QStringLiteral(
                "You repeatedly kept the restrained first look.")
          : QStringLiteral(
                "You repeatedly kept the evidence-backed deep review.");
  const auto proposed_north_star =
      preferred_version == QStringLiteral("first-look")
          ? QStringLiteral(
                "Keep edits restrained and direct unless the photograph or "
                "current request clearly benefits from deeper refinement.")
          : QStringLiteral(
                "Allow evidence-backed refinement when it clearly improves "
                "the proved first look, while keeping the result natural and "
                "reviewable.");

  QVariantList observations;
  if (available) {
    observations.append(QVariantMap{
        {QStringLiteral("kind"),
         QStringLiteral("confirmed-proved-version-pattern")},
        {QStringLiteral("headline"), headline},
        {QStringLiteral("detail"),
         QStringLiteral(
             "%1 of %2 confirmed choices kept %3; the other %4 kept %5.")
             .arg(preferred_version == QStringLiteral("first-look")
                      ? first_look_count
                      : deep_review_count)
             .arg(choice_count)
             .arg(preferred_label)
             .arg(preferred_version == QStringLiteral("first-look")
                      ? deep_review_count
                      : first_look_count)
             .arg(preferred_version == QStringLiteral("first-look")
                      ? QStringLiteral("Deep Review")
                      : QStringLiteral("First Look"))},
        {QStringLiteral("confirmedEvidenceCount"), choice_count},
    });
    if (selector_touched_count > 0) {
      observations.append(QVariantMap{
          {QStringLiteral("kind"),
           QStringLiteral("deliberate-comparison")},
          {QStringLiteral("headline"),
           QStringLiteral("You compared before deciding.")},
          {QStringLiteral("detail"),
           QStringLiteral(
               "The version switcher was used on %1 confirmed choice%2.")
               .arg(selector_touched_count)
               .arg(selector_touched_count == 1 ? QString()
                                                : QStringLiteral("s"))},
          {QStringLiteral("confirmedEvidenceCount"),
           selector_touched_count},
      });
    }
  }

  return QVariantMap{
      {QStringLiteral("contract"),
       QStringLiteral("agent-assignment-taste-reflection-v1")},
      {QStringLiteral("available"), available},
      {QStringLiteral("unavailableReason"),
       !project_local
           ? QStringLiteral("project-required")
       : north_star_available
           ? QStringLiteral("north-star-already-authored")
       : !preference_available
           ? QStringLiteral("repeated-confirmed-choice-required")
           : QString{}},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"), project_local},
      {QStringLiteral("headline"), available ? headline : QString{}},
      {QStringLiteral("observations"), observations},
      {QStringLiteral("observationCount"), observations.size()},
      {QStringLiteral("sourceContract"),
       QStringLiteral("agent-two-speed-taste-signal-v1")},
      {QStringLiteral("sourceChoiceCount"), choice_count},
      {QStringLiteral("sourcePreferredVersion"), preferred_version},
      {QStringLiteral("proposedNorthStar"),
       available ? proposed_north_star : QString{}},
      {QStringLiteral("proposalOrigin"),
       QStringLiteral("aggregate-confirmed-proved-version-choices")},
      {QStringLiteral("durableMemoryWritten"), false},
      {QStringLiteral("requiresExplicitNorthStarSave"), true},
      {QStringLiteral("automaticMemoryWriteAllowed"), false},
      {QStringLiteral("automaticRecipeInfluenceAllowed"), false},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("currentRequestWins"), true},
      {QStringLiteral("dismissalScope"), QStringLiteral("session-only")},
      {QStringLiteral("storesAssetIds"), false},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
      {QStringLiteral("storesAdjustmentSnapshots"), false},
  };
}

QVariantMap AgentEditController::renameProjectTaste(
    const QString& display_name) {
  const auto normalized_name = display_name.simplified();
  const auto project_key = currentContinuityProjectKey();
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"), QStringLiteral("rename-project-taste")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-taste-rename-v1")},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"),
       project_key != QStringLiteral("__global__")},
      {QStringLiteral("name"), normalized_name.left(80)},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  if (project_key == QStringLiteral("__global__")) {
    const auto error = QStringLiteral(
        "Choose a project before naming its learned look.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }
  if (normalized_name.size() < 2 || normalized_name.size() > 80) {
    const auto error = QStringLiteral(
        "Use a project look name between 2 and 80 characters.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    return report;
  }

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  if (!state.value(QStringLiteral("ok")).toBool()) {
    state = QVariantMap{
        {QStringLiteral("version"), 1},
        {QStringLiteral("projects"), QVariantMap{}},
    };
  }
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  entry.insert(QStringLiteral("projectKey"), project_key);
  entry.insert(QStringLiteral("tasteName"), normalized_name);
  entry.insert(
      QStringLiteral("tasteUpdatedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(
        QStringLiteral("failureReason"),
        write_report.value(QStringLiteral("errors"))
            .toStringList()
            .join(QStringLiteral("; ")));
    return report;
  }

  emit projectTasteChanged();
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("renamed"), true);
  report.insert(QStringLiteral("taste"), approvedProjectTaste());
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.remove(QStringLiteral("errors"));
  report.remove(QStringLiteral("failureReason"));
  return report;
}

QVariantMap AgentEditController::forgetProjectTasteEvidence(
    const QString& kind,
    const QString& evidence_id,
    bool confirmed) {
  const auto normalized_kind = kind.trimmed().toLower();
  const auto normalized_id = evidence_id.trimmed();
  const QStringList supported_kinds{
      QStringLiteral("approved-look"),
      QStringLiteral("approved-correction"),
      QStringLiteral("rejected-draft"),
      QStringLiteral("visual-referent"),
      QStringLiteral("story-preference"),
      QStringLiteral("photographer-calibration"),
  };
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"), QStringLiteral("forget-project-taste-evidence")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-project-taste-forget-v1")},
      {QStringLiteral("kind"), normalized_kind},
      {QStringLiteral("evidenceId"), normalized_id},
      {QStringLiteral("projectKey"), currentContinuityProjectKey()},
      {QStringLiteral("projectLocal"),
       currentContinuityProjectKey() != QStringLiteral("__global__")},
      {QStringLiteral("confirmed"), confirmed},
      {QStringLiteral("confirmationRequired"), !confirmed},
      {QStringLiteral("activeDraftUnaffected"), true},
      {QStringLiteral("memoryEffect"),
       QStringLiteral("exclude-from-future-project-planning")},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesSourcePaths"), false},
  };
  if (!supported_kinds.contains(normalized_kind) || normalized_id.isEmpty()) {
    const auto error = QStringLiteral(
        "Choose one valid project-taste item to forget.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }

  const auto current_taste = approvedProjectTaste();
  QVariantMap selected_evidence;
  for (const auto& value :
       current_taste.value(QStringLiteral("evidence")).toList()) {
    const auto candidate = value.toMap();
    if (candidate.value(QStringLiteral("kind")).toString() ==
            normalized_kind &&
        candidate.value(QStringLiteral("id")).toString() == normalized_id) {
      selected_evidence = candidate;
      break;
    }
  }
  if (selected_evidence.isEmpty()) {
    const auto error = QStringLiteral(
        "That project-taste item is no longer available.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  report.insert(QStringLiteral("title"),
                selected_evidence.value(QStringLiteral("title")));
  report.insert(QStringLiteral("summary"),
                selected_evidence.value(QStringLiteral("summary")));
  if (!confirmed) {
    const auto message = QStringLiteral(
        "Forget this item for future edits in %1? Existing edits will not change.")
                             .arg(currentContinuityProjectKey());
    report.insert(QStringLiteral("errors"), QStringList{message});
    report.insert(QStringLiteral("failureReason"), message);
    return report;
  }

  if (normalized_kind == QStringLiteral("photographer-calibration")) {
    return forgetPhotographerCalibrationProfile(true);
  }

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  if (!state.value(QStringLiteral("ok")).toBool()) {
    const auto error = QStringLiteral(
        "Project taste memory is unavailable, so nothing was removed.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  const auto project_key = currentContinuityProjectKey();
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  const auto storage_key =
      normalized_kind == QStringLiteral("approved-look")
          ? QStringLiteral("approvedEdits")
      : normalized_kind == QStringLiteral("approved-correction")
          ? QStringLiteral("approvedCorrections")
      : normalized_kind == QStringLiteral("rejected-draft")
          ? QStringLiteral("rejectedDrafts")
      : normalized_kind == QStringLiteral("story-preference")
          ? QStringLiteral("storyPreferences")
          : QStringLiteral("visualReferents");
  auto stored = entry.value(storage_key).toList();
  auto removed_count = 0;
  for (auto index = stored.size() - 1; index >= 0; --index) {
    if (project_taste_evidence_id(
            normalized_kind, stored.at(index).toMap()) == normalized_id) {
      stored.removeAt(index);
      ++removed_count;
    }
  }
  if (removed_count == 0) {
    const auto error = QStringLiteral(
        "That project-taste item changed before it could be removed.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  entry.insert(storage_key, stored);
  entry.insert(QStringLiteral("approvedEditCount"),
               entry.value(QStringLiteral("approvedEdits")).toList().size());
  entry.insert(
      QStringLiteral("approvedCorrectionCount"),
      entry.value(QStringLiteral("approvedCorrections")).toList().size());
  entry.insert(QStringLiteral("rejectedDraftCount"),
               entry.value(QStringLiteral("rejectedDrafts")).toList().size());
  entry.insert(QStringLiteral("visualReferentCount"),
               entry.value(QStringLiteral("visualReferents")).toList().size());
  entry.insert(QStringLiteral("storyPreferenceCount"),
               entry.value(QStringLiteral("storyPreferences")).toList().size());
  entry.insert(
      QStringLiteral("tasteUpdatedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(
        QStringLiteral("failureReason"),
        write_report.value(QStringLiteral("errors"))
            .toStringList()
            .join(QStringLiteral("; ")));
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }

  if (normalized_kind == QStringLiteral("visual-referent")) {
    for (auto iterator = transient_visual_referent_masks_.begin();
         iterator != transient_visual_referent_masks_.end();) {
      const auto cached = iterator.value();
      if (cached.value(QStringLiteral("projectKey")).toString() ==
              project_key &&
          cached.value(QStringLiteral("referentId")).toString() ==
              normalized_id) {
        iterator = transient_visual_referent_masks_.erase(iterator);
      } else {
        ++iterator;
      }
    }
  }
  emit projectTasteChanged();
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("forgotten"), true);
  report.insert(QStringLiteral("removedCount"), removed_count);
  report.insert(QStringLiteral("confirmationRequired"), false);
  report.insert(QStringLiteral("remainingTaste"), approvedProjectTaste());
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.remove(QStringLiteral("errors"));
  report.remove(QStringLiteral("failureReason"));
  return report;
}

QVariantMap AgentEditController::forgetTwoSpeedTastePreference(
    bool confirmed) {
  const auto project_key = currentContinuityProjectKey();
  const auto current_preference =
      approvedProjectTaste()
          .value(QStringLiteral("twoSpeedPreference"))
          .toMap();
  QVariantMap report{
      {QStringLiteral("ok"), false},
      {QStringLiteral("mode"),
       QStringLiteral("forget-two-speed-taste-preference")},
      {QStringLiteral("contract"),
       QStringLiteral("agent-two-speed-taste-forget-v1")},
      {QStringLiteral("projectKey"), project_key},
      {QStringLiteral("projectLocal"),
       project_key != QStringLiteral("__global__")},
      {QStringLiteral("confirmed"), confirmed},
      {QStringLiteral("confirmationRequired"), !confirmed},
      {QStringLiteral("activeEditsUnaffected"), true},
      {QStringLiteral("approvedEditEvidenceRetained"), true},
      {QStringLiteral("memoryEffect"),
       QStringLiteral("remove-proved-version-preference-only")},
      {QStringLiteral("storesImageBytes"), false},
      {QStringLiteral("storesProofPaths"), false},
      {QStringLiteral("storesAdjustmentSnapshots"), false},
  };
  if (project_key == QStringLiteral("__global__")) {
    const auto error = QStringLiteral(
        "Choose a project before changing its proved-version preference.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  if (!current_preference.value(QStringLiteral("available")).toBool()) {
    const auto error = QStringLiteral(
        "No First Look or Deep Review preference is remembered for this "
        "project.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  report.insert(QStringLiteral("choiceCount"),
                current_preference.value(QStringLiteral("choiceCount")));
  if (!confirmed) {
    const auto message = QStringLiteral(
        "Forget whether you tended to choose First Look or Deep Review in "
        "%1? Approved looks and existing edits will remain.")
                             .arg(project_key);
    report.insert(QStringLiteral("errors"), QStringList{message});
    report.insert(QStringLiteral("failureReason"), message);
    return report;
  }

  auto state =
      agent_memory_continuity_state(AppBootstrap::appDataLocation());
  if (!state.value(QStringLiteral("ok")).toBool()) {
    const auto error = QStringLiteral(
        "Project taste memory is unavailable, so nothing was removed.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  auto projects = state.value(QStringLiteral("projects")).toMap();
  auto entry = projects.value(project_key).toMap();
  auto approvals = entry.value(QStringLiteral("approvedEdits")).toList();
  auto removed_count = 0;
  for (auto index = 0; index < approvals.size(); ++index) {
    auto approval = approvals.at(index).toMap();
    if (!approval.contains(QStringLiteral("twoSpeedDraftChoice"))) {
      continue;
    }
    approval.remove(QStringLiteral("twoSpeedDraftChoice"));
    approvals[index] = approval;
    ++removed_count;
  }
  if (removed_count == 0) {
    const auto error = QStringLiteral(
        "The proved-version preference changed before it could be removed.");
    report.insert(QStringLiteral("errors"), QStringList{error});
    report.insert(QStringLiteral("failureReason"), error);
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }
  entry.insert(QStringLiteral("approvedEdits"), approvals);
  entry.insert(
      QStringLiteral("tasteUpdatedAtUtc"),
      QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));
  projects.insert(project_key, entry);
  state.insert(QStringLiteral("projects"), projects);
  const auto write_report = write_agent_memory_continuity_state(
      AppBootstrap::appDataLocation(), state);
  if (!write_report.value(QStringLiteral("ok")).toBool()) {
    report.insert(QStringLiteral("errors"),
                  write_report.value(QStringLiteral("errors")));
    report.insert(
        QStringLiteral("failureReason"),
        write_report.value(QStringLiteral("errors"))
            .toStringList()
            .join(QStringLiteral("; ")));
    report.insert(QStringLiteral("confirmationRequired"), false);
    return report;
  }

  emit projectTasteChanged();
  report.insert(QStringLiteral("ok"), true);
  report.insert(QStringLiteral("forgotten"), true);
  report.insert(QStringLiteral("removedChoiceCount"), removed_count);
  report.insert(QStringLiteral("confirmationRequired"), false);
  report.insert(QStringLiteral("remainingTaste"), approvedProjectTaste());
  report.insert(QStringLiteral("memoryWrite"), write_report);
  report.remove(QStringLiteral("errors"));
  report.remove(QStringLiteral("failureReason"));
  return report;
}

