  pending.insert(QStringLiteral("mode"),
                 QStringLiteral("draft-planning-continuation"));
  pending.insert(QStringLiteral("scope"), scope);
  pending.insert(QStringLiteral("errorCode"),
                 QStringLiteral("async_stage_pending"));
  pending.insert(QStringLiteral("asyncStagePending"), true);
  pending.insert(QStringLiteral("asyncStage"), stage_name);
  pending.insert(QStringLiteral("requestId"), active_draft_request_id_);
  pending.insert(QStringLiteral("planningContinuation"),
                 requestOwnedPlanningContinuationReport());
