    stopped.insert(QStringLiteral("safeStopReason"),
                   QStringLiteral("ambiguous_visible_instance"));
    stopped.insert(
        QStringLiteral("userQuestions"),
        QVariantList{QStringLiteral("Which %1 should I change?").arg(target_label)});
    stopped.insert(QStringLiteral("scope"), report_scope);
    stopped.insert(QStringLiteral("continuityProjectKey"),
                   currentContinuityProjectKey());
    stopped.insert(QStringLiteral("editingFreedom"), editing_freedom_);
    stopped.insert(QStringLiteral("assetIds"), target_asset_ids);
    stopped.insert(QStringLiteral("assetId"), representative_asset_id);
    stopped.insert(QStringLiteral("representativeAssetId"), representative_asset_id);
    stopped.insert(QStringLiteral("modelId"), model_id);
    stopped.insert(QStringLiteral("modelBackend"), model.value(QStringLiteral("backend")));
    stopped.insert(QStringLiteral("plannedRecipePatch"),
                   plan.value(QStringLiteral("recipePatch")));
    stopped.insert(QStringLiteral("selectionConfirmation"), grounding_confirmation);
    stopped.insert(QStringLiteral("progressivePreview"), restored_preview);
    stopped.insert(QStringLiteral("resumeScope"), report_scope);
    stopped.insert(
        QStringLiteral("resumeInstructions"),
        instructions.trimmed().isEmpty() ? user_instructions_ : instructions);
    stopped.insert(QStringLiteral("draftActive"), false);
    appendRunEvent(
        QStringLiteral("ground"),
        QStringLiteral("Confirm target"),
        QStringLiteral("needs_user_input"),
        QStringLiteral("Found more than one plausible %1 and stopped before editing.")
            .arg(target_label),
        grounding_confirmation);
    attachRunInteractionFeedback(&stopped);
    finalize_timing(&stopped, started_at_utc, elapsed_run_ms(), {});
    write_agent_run_manifest(&stopped, run_style, model, model_id);
    setRunning(false);
    setStatus(QStringLiteral("Confirm object"));
    setErrorMessage(QString());
    setPendingAgentInput(stopped);
    setLastRunReport(stopped);
    return stopped;
