  draft.insert(QStringLiteral("modelPromptAudit"), plan.value(QStringLiteral("modelPromptAudit")));
  draft.insert(QStringLiteral("mcpDiscovery"), mcp_discovery);
  draft.insert(QStringLiteral("mcpObservation"), mcp_observation);
